window.SHAKESPEARE_CHINESE["part0022"]={"id":"part0022","title":"亨利六世上篇","translator":"章益","translatorCredit":"章益译","attributionStatus":"explicit","kind":"play","englishId":"1henryvi","sections":[{"id":"part0022-section-000","label":"书前与人物","kind":"preface","blocks":[{"id":"part0022-00000","html":"\n\u003ch2 id=\"epub-part0022-a458\" class=\"epub-calibre15\">亨利六世上篇\u003c/h2>\n","text":"\n亨利六世上篇\n","sourceAnchor":"a458","tag":"h2"},{"id":"part0022-00001","html":"\u003cp class=\"epub-center\">章益译\u003c/p>\n","text":"章益译\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00002","html":"\u003cp class=\"epub-center\">\u003cimg src=\"data/chinese-collection/images/00111.jpeg\" alt=\"\" loading=\"lazy\" class=\"epub-calibre2 epub-image\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00003","html":"\u003cp class=\"epub-center\">\u003cb class=\"epub-calibre3\">剧中人物\u003c/b>\u003c/p>\n","text":"剧中人物\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00004","html":"\u003cp class=\"epub-calibre1\">亨利六世\u003c/p>\n","text":"亨利六世\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00005","html":"\u003cp class=\"epub-calibre1\">葛罗斯特公爵 护国公，亨利王之叔父\u003c/p>\n","text":"葛罗斯特公爵 护国公，亨利王之叔父\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00006","html":"\u003cp class=\"epub-calibre1\">培福公爵 总管法国事务大臣，亨利王之叔父\u003c/p>\n","text":"培福公爵 总管法国事务大臣，亨利王之叔父\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00007","html":"\u003cp class=\"epub-calibre1\">托马斯·波福 爱克塞特公爵，亨利王之叔祖\u003c/p>\n","text":"托马斯·波福 爱克塞特公爵，亨利王之叔祖\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00008","html":"\u003cp class=\"epub-calibre1\">亨利·波福 温彻斯特主教，后晋升为红衣主教，亨利王之叔祖\u003c/p>\n","text":"亨利·波福 温彻斯特主教，后晋升为红衣主教，亨利王之叔祖\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00009","html":"\u003cp class=\"epub-calibre1\">约翰·波福 萨穆塞特伯爵，后晋升为公爵\u003c/p>\n","text":"约翰·波福 萨穆塞特伯爵，后晋升为公爵\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00010","html":"\u003cp class=\"epub-calibre1\">理查·普兰塔琪纳特 已故剑桥伯爵理查之子，后受封为约克公爵\u003c/p>\n","text":"理查·普兰塔琪纳特 已故剑桥伯爵理查之子，后受封为约克公爵\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00011","html":"\u003cp class=\"epub-calibre1\">华列克伯爵\u003c/p>\n","text":"华列克伯爵\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00012","html":"\u003cp class=\"epub-calibre1\">萨立斯伯雷伯爵\u003c/p>\n","text":"萨立斯伯雷伯爵\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00013","html":"\u003cp class=\"epub-calibre1\">萨福克伯爵\u003c/p>\n","text":"萨福克伯爵\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00014","html":"\u003cp class=\"epub-calibre1\">塔尔博勋爵 后受封为索鲁斯伯雷伯爵\u003c/p>\n","text":"塔尔博勋爵 后受封为索鲁斯伯雷伯爵\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00015","html":"\u003cp class=\"epub-calibre1\">约翰·塔尔博 塔尔博勋爵之子\u003c/p>\n","text":"约翰·塔尔博 塔尔博勋爵之子\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00016","html":"\u003cp class=\"epub-calibre1\">爱德蒙·摩提默 马契伯爵\u003c/p>\n","text":"爱德蒙·摩提默 马契伯爵\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00017","html":"\u003cp class=\"epub-calibre1\">约翰·福斯托夫爵士\u003c/p>\n","text":"约翰·福斯托夫爵士\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00018","html":"\u003cp class=\"epub-calibre1\">威廉·路西爵士\u003c/p>\n","text":"威廉·路西爵士\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00019","html":"\u003cp class=\"epub-calibre1\">威廉·葛兰斯台尔爵士\u003c/p>\n","text":"威廉·葛兰斯台尔爵士\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00020","html":"\u003cp class=\"epub-calibre1\">托马斯·嘉格莱夫爵士\u003c/p>\n","text":"托马斯·嘉格莱夫爵士\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00021","html":"\u003cp class=\"epub-calibre1\">伍德维尔 伦敦塔卫队长\u003c/p>\n","text":"伍德维尔 伦敦塔卫队长\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00022","html":"\u003cp class=\"epub-calibre1\">伦敦市长\u003c/p>\n","text":"伦敦市长\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00023","html":"\u003cp class=\"epub-calibre1\">看守摩提默的狱卒们\u003c/p>\n","text":"看守摩提默的狱卒们\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00024","html":"\u003cp class=\"epub-calibre1\">律师\u003c/p>\n","text":"律师\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00025","html":"\u003cp class=\"epub-calibre1\">凡农 约克党\u003c/p>\n","text":"凡农 约克党\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00026","html":"\u003cp class=\"epub-calibre1\">巴塞特 兰开斯特党\u003c/p>\n","text":"巴塞特 兰开斯特党\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00027","html":"\u003cp class=\"epub-calibre1\">查理 法国皇太子，后继承王位\u003c/p>\n","text":"查理 法国皇太子，后继承王位\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00028","html":"\u003cp class=\"epub-calibre1\">瑞尼埃 安佐公爵，兼那不勒斯国王称号\u003c/p>\n","text":"瑞尼埃 安佐公爵，兼那不勒斯国王称号\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00029","html":"\u003cp class=\"epub-calibre1\">勃艮第公爵\u003c/p>\n","text":"勃艮第公爵\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00030","html":"\u003cp class=\"epub-calibre1\">阿朗松公爵\u003c/p>\n","text":"阿朗松公爵\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00031","html":"\u003cp class=\"epub-calibre1\">奥尔良庶子\u003c/p>\n","text":"奥尔良庶子\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00032","html":"\u003cp class=\"epub-calibre1\">巴黎市长\u003c/p>\n","text":"巴黎市长\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00033","html":"\u003cp class=\"epub-calibre1\">奥尔良炮兵队长及其子\u003c/p>\n","text":"奥尔良炮兵队长及其子\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00034","html":"\u003cp class=\"epub-calibre1\">波尔多地区法国统兵官\u003c/p>\n","text":"波尔多地区法国统兵官\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00035","html":"\u003cp class=\"epub-calibre1\">法军军曹\u003c/p>\n","text":"法军军曹\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00036","html":"\u003cp class=\"epub-calibre1\">看门人\u003c/p>\n","text":"看门人\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00037","html":"\u003cp class=\"epub-calibre1\">牧羊老人 贞德之父\u003c/p>\n","text":"牧羊老人 贞德之父\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00038","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00039","html":"\u003cp class=\"epub-calibre1\">玛格莱特 瑞尼埃之女，后与亨利六世结婚\u003c/p>\n","text":"玛格莱特 瑞尼埃之女，后与亨利六世结婚\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00040","html":"\u003cp class=\"epub-calibre1\">奥凡涅伯爵夫人\u003c/p>\n","text":"奥凡涅伯爵夫人\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00041","html":"\u003cp class=\"epub-calibre1\">贞德\u003c/p>\n","text":"贞德\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00042","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00043","html":"\u003cp class=\"epub-calibre1\">群臣、伦敦塔守兵、司礼官、传令官、吏员、兵士、使者、侍从等对贞德显灵的幽灵\u003c/p>\n","text":"群臣、伦敦塔守兵、司礼官、传令官、吏员、兵士、使者、侍从等对贞德显灵的幽灵\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00044","html":"\u003cp class=\"epub-center\">\u003cb class=\"epub-calibre3\">地点\u003c/b>\u003c/p>\n","text":"地点\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00045","html":"\u003cp class=\"epub-center\">英国；法国\u003c/p>\n","text":"英国；法国\n","sourceAnchor":null,"tag":"p"}]},{"id":"part0022-section-001","label":"第一幕","kind":"act","blocks":[{"id":"part0022-00046","html":"\u003ch3 id=\"epub-part0022-a459\" class=\"epub-calibre11\">第一幕\u003c/h3>\n","text":"第一幕\n","sourceAnchor":"a459","tag":"h3"}],"heading":"第一幕","headingLevel":3,"sourceAnchor":"a459","actNumber":1},{"id":"part0022-section-002","label":"第一幕 · 第一场 威司敏斯特寺院","kind":"scene","blocks":[{"id":"part0022-00047","html":"\u003ch4 id=\"epub-part0022-a460\" class=\"epub-calibre12\">第一场 威司敏斯特寺院\u003c/h4>\n","text":"第一场 威司敏斯特寺院\n","sourceAnchor":"a460","tag":"h4"},{"id":"part0022-00048","html":"\u003cp class=\"epub-block1\">内奏丧礼哀乐。英王亨利五世葬仪队上场，送葬者培福、葛罗斯特、爱克塞特、华列克、温彻斯特、司礼官等同上。\u003c/p>\n","text":"内奏丧礼哀乐。英王亨利五世葬仪队上场，送葬者培福、葛罗斯特、爱克塞特、华列克、温彻斯特、司礼官等同上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00049","html":"\u003cp class=\"epub-calibre1\">培福 让天空张起黑幕，叫白天让位给黑夜！预兆时世盛衰、国家兴亡的彗星，望你们在空中挥动你们的万丈光芒的尾巴！用你们的尾巴鞭挞那些恶毒的叛逆的星辰，以惩治它们坐视先王崩殂的罪戾！我们的先王亨利五世，因威名过盛，以致不克永年！在英格兰逝去的君王当中，有谁比得上他的高贵？\u003c/p>\n","text":"培福 让天空张起黑幕，叫白天让位给黑夜！预兆时世盛衰、国家兴亡的彗星，望你们在空中挥动你们的万丈光芒的尾巴！用你们的尾巴鞭挞那些恶毒的叛逆的星辰，以惩治它们坐视先王崩殂的罪戾！我们的先王亨利五世，因威名过盛，以致不克永年！在英格兰逝去的君王当中，有谁比得上他的高贵？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00050","html":"\u003cp class=\"epub-calibre1\">葛罗斯特 英格兰有史以来，他是唯一的真命之主。他的德行足以服众；他挥动起来的宝剑的光辉，使人不敢对他逼视；他张开的两臂比龙翼更为广阔；他那双神威奕奕的眸子比正午时分的骄阳更使他的敌人目眩神昏，退避不遑。我该说些什么呢？他的功业绝非言语所能罄述；他征服四方真是易如反掌。\u003c/p>\n","text":"葛罗斯特 英格兰有史以来，他是唯一的真命之主。他的德行足以服众；他挥动起来的宝剑的光辉，使人不敢对他逼视；他张开的两臂比龙翼更为广阔；他那双神威奕奕的眸子比正午时分的骄阳更使他的敌人目眩神昏，退避不遑。我该说些什么呢？他的功业绝非言语所能罄述；他征服四方真是易如反掌。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00051","html":"\u003cp class=\"epub-calibre1\">爱克塞特 我们穿着丧服志哀，我们为什么不用鲜血来表示哀悼？先王晏驾，再也不能返回人世了。我们跟随在灵柩后边，好像拴在敌人的得胜战车后面的俘虏一般，这简直是用我们的庄严行列来为死神的可耻的胜利增光。嘿，难道我们只对那些断送我们荣光的灾星诅咒一番就算完事了吗？倒是让我们认真想一想，那些狡诈的法兰西巫师们，因为畏惧先王，竟然使用妖术和符咒来夺去他的寿算，他们的这个罪该怎样惩处才好！\u003c/p>\n","text":"爱克塞特 我们穿着丧服志哀，我们为什么不用鲜血来表示哀悼？先王晏驾，再也不能返回人世了。我们跟随在灵柩后边，好像拴在敌人的得胜战车后面的俘虏一般，这简直是用我们的庄严行列来为死神的可耻的胜利增光。嘿，难道我们只对那些断送我们荣光的灾星诅咒一番就算完事了吗？倒是让我们认真想一想，那些狡诈的法兰西巫师们，因为畏惧先王，竟然使用妖术和符咒来夺去他的寿算，他们的这个罪该怎样惩处才好！\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00052","html":"\u003cp class=\"epub-calibre1\">温彻斯特 我们的先王是受到万王之王\u003ca id=\"epub-part0022-w001\">\u003c/a>\u003ca href=\"#epub-part0022-m001\" data-source-anchor=\"m001\">\u003csup class=\"epub-calibre13\">[1]\u003c/sup>\u003c/a>的福佑的。法兰西人见了他，吓得战战兢兢，甚至比末日审判的时候更加害怕。先王是替天行讨，我们教会的颂祷使他的国运昌隆。\u003c/p>\n","text":"温彻斯特 我们的先王是受到万王之王[1]的福佑的。法兰西人见了他，吓得战战兢兢，甚至比末日审判的时候更加害怕。先王是替天行讨，我们教会的颂祷使他的国运昌隆。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00053","html":"\u003cp class=\"epub-calibre1\">葛罗斯特 说什么教会！教会在哪儿？若不是你们那班僧侣们胡乱祈祷，他还不会如此短寿哩。你们最喜欢的是孱弱的幼主，像小学生一样，能受你们的摆布。\u003c/p>\n","text":"葛罗斯特 说什么教会！教会在哪儿？若不是你们那班僧侣们胡乱祈祷，他还不会如此短寿哩。你们最喜欢的是孱弱的幼主，像小学生一样，能受你们的摆布。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00054","html":"\u003cp class=\"epub-calibre1\">温彻斯特 葛罗斯特，不管我们喜欢的是什么，反正你是护国公，太子也好，国家也好，都在你的掌握之中。你的老婆是个骄横的女人，她把你治得服服帖帖，比上帝或是教士都更有灵验。\u003c/p>\n","text":"温彻斯特 葛罗斯特，不管我们喜欢的是什么，反正你是护国公，太子也好，国家也好，都在你的掌握之中。你的老婆是个骄横的女人，她把你治得服服帖帖，比上帝或是教士都更有灵验。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00055","html":"\u003cp class=\"epub-calibre1\">葛罗斯特 别提教会啦，你爱的是肉体的享乐，你除了要去诅咒你的仇人以外，终年也不见你走进礼拜堂的大门。\u003c/p>\n","text":"葛罗斯特 别提教会啦，你爱的是肉体的享乐，你除了要去诅咒你的仇人以外，终年也不见你走进礼拜堂的大门。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00056","html":"\u003cp class=\"epub-calibre1\">培福 得啦，停止你们的争吵，大家和和气气的吧。让我们到祭坛那边去；司礼官们，随侍我们。我们不用金银作祭礼，我们要献上我们的武器，因为先王已死，武器已经无用。后代的人们，等着过苦日子吧。婴儿们将从母亲湿淋淋的眼眶里吮吸泪水，我们的岛国将变成咸泪遍地的沼泽，男人们将死尽杀绝，只剩下妇女们为死者哀号。亨利五世我的先王啊，我恳求您在天之灵保佑这片国土太平兴旺，不要让内战发生，把天上的灾星全都击退！您的英灵是一颗灿烂的明星，您的光辉远胜过裘力斯·恺撒和任何亮晶晶的……\u003c/p>\n","text":"培福 得啦，停止你们的争吵，大家和和气气的吧。让我们到祭坛那边去；司礼官们，随侍我们。我们不用金银作祭礼，我们要献上我们的武器，因为先王已死，武器已经无用。后代的人们，等着过苦日子吧。婴儿们将从母亲湿淋淋的眼眶里吮吸泪水，我们的岛国将变成咸泪遍地的沼泽，男人们将死尽杀绝，只剩下妇女们为死者哀号。亨利五世我的先王啊，我恳求您在天之灵保佑这片国土太平兴旺，不要让内战发生，把天上的灾星全都击退！您的英灵是一颗灿烂的明星，您的光辉远胜过裘力斯·恺撒和任何亮晶晶的……\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00057","html":"\u003cp class=\"epub-block1\">一使者上。\u003c/p>\n","text":"一使者上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00058","html":"\u003cp class=\"epub-calibre1\">使者 列位大人，敬祝你们政躬安泰！我从法兰西给你们带来了损失、屠杀、挫败的悲惨消息：居恩、香槟、里姆、奥尔良、巴黎、纪莎、波亚叠全都沦陷了。\u003c/p>\n","text":"使者 列位大人，敬祝你们政躬安泰！我从法兰西给你们带来了损失、屠杀、挫败的悲惨消息：居恩、香槟、里姆、奥尔良、巴黎、纪莎、波亚叠全都沦陷了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00059","html":"\u003cp class=\"epub-calibre1\">培福 汉子，你在老王的灵前说的是什么话？轻声一点，要不然，这些名城沦陷的消息会使老王爷砸碎铅制的棺盖，从棺材里爬出来。\u003c/p>\n","text":"培福 汉子，你在老王的灵前说的是什么话？轻声一点，要不然，这些名城沦陷的消息会使老王爷砸碎铅制的棺盖，从棺材里爬出来。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00060","html":"\u003cp class=\"epub-calibre1\">葛罗斯特 巴黎丢了吗？卢昂投降了吗？假使老王果真复活，他听到这样的噩耗，还是要撒手归天的。\u003c/p>\n","text":"葛罗斯特 巴黎丢了吗？卢昂投降了吗？假使老王果真复活，他听到这样的噩耗，还是要撒手归天的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00061","html":"\u003cp class=\"epub-calibre1\">爱克塞特 这些城池是怎样丢掉的？他们使用了什么诡计？\u003c/p>\n","text":"爱克塞特 这些城池是怎样丢掉的？他们使用了什么诡计？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00062","html":"\u003cp class=\"epub-calibre1\">使者 没有什么诡计；只是因为缺少兵丁和钱粮。兵士们都在纷纷议论，说你们这里派系纷争，在这样的决战关头还举棋不定，争吵不休：一位大巨要节省开支，宁愿把战事拖长；另一位恨不得插翅飞翔，可是又缺乏羽翼；第三位的主张是，一文不费，只靠甜言蜜语来赢得和平。醒来吧，醒来吧，英格兰的贵胄们！不要再徘徊迂缓，让新近博得的荣光黯然失色。绣在你们铠甲上的百合花纹章\u003ca id=\"epub-part0022-w002\">\u003c/a>\u003ca href=\"#epub-part0022-m002\" data-source-anchor=\"m002\">\u003csup class=\"epub-calibre13\">[2]\u003c/sup>\u003c/a>已被剪去尖儿了，英格兰的国徽已被割去半幅了。\u003c/p>\n","text":"使者 没有什么诡计；只是因为缺少兵丁和钱粮。兵士们都在纷纷议论，说你们这里派系纷争，在这样的决战关头还举棋不定，争吵不休：一位大巨要节省开支，宁愿把战事拖长；另一位恨不得插翅飞翔，可是又缺乏羽翼；第三位的主张是，一文不费，只靠甜言蜜语来赢得和平。醒来吧，醒来吧，英格兰的贵胄们！不要再徘徊迂缓，让新近博得的荣光黯然失色。绣在你们铠甲上的百合花纹章[2]已被剪去尖儿了，英格兰的国徽已被割去半幅了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00063","html":"\u003cp class=\"epub-calibre1\">爱克塞特 假如我们在丧礼中没有流泪，听到这些噩耗，也禁不住要泪如泉涌的。\u003c/p>\n","text":"爱克塞特 假如我们在丧礼中没有流泪，听到这些噩耗，也禁不住要泪如泉涌的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00064","html":"\u003cp class=\"epub-calibre1\">培福 我既身为总管法国事务的大臣，这是我义不容辞的任务。我要抛开这些不体面的丧服，穿上我的戎装，我要为保卫我们在法兰西的领土而作战。我要让法兰西人的身上多开几个像眼睛一样的伤口，好让他们血泪交流，来哀悼他们层出不穷的灾祸。\u003c/p>\n","text":"培福 我既身为总管法国事务的大臣，这是我义不容辞的任务。我要抛开这些不体面的丧服，穿上我的戎装，我要为保卫我们在法兰西的领土而作战。我要让法兰西人的身上多开几个像眼睛一样的伤口，好让他们血泪交流，来哀悼他们层出不穷的灾祸。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00065","html":"\u003cp class=\"epub-block1\">又一使者上。\u003c/p>\n","text":"又一使者上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00066","html":"\u003cp class=\"epub-calibre1\">使者乙 大人们，请读一读这些充满灾殃的信简吧。法兰西除开几个无关紧要的小城镇以外，已经全面地对英国背叛了。查理太子在里姆斯已经登上法国王位；奥尔良的庶子已经依附在他的身边；安佐公爵瑞尼埃表示对他赞助；阿朗松公爵也投奔了他。\u003c/p>\n","text":"使者乙 大人们，请读一读这些充满灾殃的信简吧。法兰西除开几个无关紧要的小城镇以外，已经全面地对英国背叛了。查理太子在里姆斯已经登上法国王位；奥尔良的庶子已经依附在他的身边；安佐公爵瑞尼埃表示对他赞助；阿朗松公爵也投奔了他。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00067","html":"\u003cp class=\"epub-calibre1\">爱克塞特 那太子竟然登上王位！大伙儿都投奔了他！嗳哟，面对着这样的耻辱，叫我们向哪里投奔呢？\u003c/p>\n","text":"爱克塞特 那太子竟然登上王位！大伙儿都投奔了他！嗳哟，面对着这样的耻辱，叫我们向哪里投奔呢？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00068","html":"\u003cp class=\"epub-calibre1\">葛罗斯特 我们哪儿也不投奔，除非奔向敌人的咽喉。培福，要是你迟疑不决，就由我亲自出征。\u003c/p>\n","text":"葛罗斯特 我们哪儿也不投奔，除非奔向敌人的咽喉。培福，要是你迟疑不决，就由我亲自出征。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00069","html":"\u003cp class=\"epub-calibre1\">培福 葛罗斯特，你对我勇往直前的性格难道还有什么怀疑吗？我心里已在盘算如何集合大军去踏遍法兰西全境了。\u003c/p>\n","text":"培福 葛罗斯特，你对我勇往直前的性格难道还有什么怀疑吗？我心里已在盘算如何集合大军去踏遍法兰西全境了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00070","html":"\u003cp class=\"epub-block1\">使者丙上。\u003c/p>\n","text":"使者丙上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00071","html":"\u003cp class=\"epub-calibre1\">使者丙 仁慈的大人们，当你们正为老王的遗体洒泪的时候，我不免要增添列位的烦恼。我不得不把骁勇的塔尔博爵爷败于法兰西人的消息向您报告。\u003c/p>\n","text":"使者丙 仁慈的大人们，当你们正为老王的遗体洒泪的时候，我不免要增添列位的烦恼。我不得不把骁勇的塔尔博爵爷败于法兰西人的消息向您报告。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00072","html":"\u003cp class=\"epub-calibre1\">温彻斯特 怎么！塔尔博在战事中屈服了吗？是这样的吗？\u003c/p>\n","text":"温彻斯特 怎么！塔尔博在战事中屈服了吗？是这样的吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00073","html":"\u003cp class=\"epub-calibre1\">使者丙 唔，他没有屈服；塔尔博爵爷是在战争中被打垮了。当时的情况请容我详细说明。在八月十号那天，这位威风凛凛的爵爷，从围攻奥尔良的阵地上撤下来，那时他手下的部队不足六千人，而包围他的敌军却有二万三千之众。他来不及将队伍列成阵势；他弄不到掩护弓箭手的木栅，只能从篱笆上拆下一些尖端的木杙草草地插在地面上，用以代替栅栏，作为防御骑兵进攻的障碍物。战斗进行了三个钟头；英勇的塔尔博以超人的气概挥动他的长矛和宝剑建立了奇功：上百的敌人在他的矛、剑下丧命，他左冲右突，所向披靡。法国人把他当作煞神下降，全部敌军望见他都吓得魄散魂飞。我方士兵受到他的鼓舞，齐声欢呼“塔尔博！塔尔博！”一下子都冲到垓心。这一天本可稳稳地打一个漂亮的胜仗，要不是福斯托夫爵士干出懦夫的勾当。按照作战的部署，福斯托夫爵士的队伍留在后面担当接应的任务，却不料他一仗未打，就怯懦地临阵脱逃。这一来就引起全军崩溃，陷入敌人的重围，遭到一场屠杀。一个名叫瓦鲁恩的无耻之徒，为了博取法国太子的欢心，从塔尔博的背后攮了他一枪；这位盖世英雄，连整个法兰西集中了精锐的兵力也不敢对他正视的，却不料就这样遭了暗算。\u003c/p>\n","text":"使者丙 唔，他没有屈服；塔尔博爵爷是在战争中被打垮了。当时的情况请容我详细说明。在八月十号那天，这位威风凛凛的爵爷，从围攻奥尔良的阵地上撤下来，那时他手下的部队不足六千人，而包围他的敌军却有二万三千之众。他来不及将队伍列成阵势；他弄不到掩护弓箭手的木栅，只能从篱笆上拆下一些尖端的木杙草草地插在地面上，用以代替栅栏，作为防御骑兵进攻的障碍物。战斗进行了三个钟头；英勇的塔尔博以超人的气概挥动他的长矛和宝剑建立了奇功：上百的敌人在他的矛、剑下丧命，他左冲右突，所向披靡。法国人把他当作煞神下降，全部敌军望见他都吓得魄散魂飞。我方士兵受到他的鼓舞，齐声欢呼“塔尔博！塔尔博！”一下子都冲到垓心。这一天本可稳稳地打一个漂亮的胜仗，要不是福斯托夫爵士干出懦夫的勾当。按照作战的部署，福斯托夫爵士的队伍留在后面担当接应的任务，却不料他一仗未打，就怯懦地临阵脱逃。这一来就引起全军崩溃，陷入敌人的重围，遭到一场屠杀。一个名叫瓦鲁恩的无耻之徒，为了博取法国太子的欢心，从塔尔博的背后攮了他一枪；这位盖世英雄，连整个法兰西集中了精锐的兵力也不敢对他正视的，却不料就这样遭了暗算。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00074","html":"\u003cp class=\"epub-calibre1\">培福 塔尔博阵亡了吗？要是这样一位高贵的统帅因为力尽援绝，遭到怯懦的敌人的暗算，而我还安享尊荣，那我也宁愿自刎而死。\u003c/p>\n","text":"培福 塔尔博阵亡了吗？要是这样一位高贵的统帅因为力尽援绝，遭到怯懦的敌人的暗算，而我还安享尊荣，那我也宁愿自刎而死。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00075","html":"\u003cp class=\"epub-calibre1\">使者丙 啊，他投有阵亡，他还活着，不过他已被俘，一同被俘的还有斯凯尔斯勋爵和亨格福德勋爵。其余的人有的被杀，有的也被俘。\u003c/p>\n","text":"使者丙 啊，他投有阵亡，他还活着，不过他已被俘，一同被俘的还有斯凯尔斯勋爵和亨格福德勋爵。其余的人有的被杀，有的也被俘。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00076","html":"\u003cp class=\"epub-calibre1\">培福 他的赎金是不会有别人担承的，只好由我来支付，我要把法国太子从他的宝座上一把拖下来，用他的王冠作为我朋友的赎金。我要用四个从法军捉来的将军换回我们的一名大将。列位大人，再见；我立刻去料理出征的事。我要在法国燃起庆功的焰火，在那里欢度我们伟大的圣乔治节日。我要率领一万大军出征，在那里用鲜血干下的事迹将使全欧洲为之震动。\u003c/p>\n","text":"培福 他的赎金是不会有别人担承的，只好由我来支付，我要把法国太子从他的宝座上一把拖下来，用他的王冠作为我朋友的赎金。我要用四个从法军捉来的将军换回我们的一名大将。列位大人，再见；我立刻去料理出征的事。我要在法国燃起庆功的焰火，在那里欢度我们伟大的圣乔治节日。我要率领一万大军出征，在那里用鲜血干下的事迹将使全欧洲为之震动。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00077","html":"\u003cp class=\"epub-calibre1\">使者丙 只怕是不得不如此了；奥尔良还在围攻之中，英国军队日益疲惫了。萨立斯伯雷伯爵渴盼援军，他由于兵力单薄，在以寡敌众的形势之下，要防止军心涣散已感到十分吃力。\u003c/p>\n","text":"使者丙 只怕是不得不如此了；奥尔良还在围攻之中，英国军队日益疲惫了。萨立斯伯雷伯爵渴盼援军，他由于兵力单薄，在以寡敌众的形势之下，要防止军心涣散已感到十分吃力。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00078","html":"\u003cp class=\"epub-calibre1\">爱克塞特 列位大人，请记住你们对亨利老王的誓言，你们曾经表示，若不将法国太子彻底摧毁，也要强迫他俯首归降。\u003c/p>\n","text":"爱克塞特 列位大人，请记住你们对亨利老王的誓言，你们曾经表示，若不将法国太子彻底摧毁，也要强迫他俯首归降。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00079","html":"\u003cp class=\"epub-calibre1\">培福 我记住的。我现在就向列位告别，立即收拾启程。\u003cb class=\"epub-calibre3\">（下。）\u003c/b>\u003c/p>\n","text":"培福 我记住的。我现在就向列位告别，立即收拾启程。（下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00080","html":"\u003cp class=\"epub-calibre1\">葛罗斯特 我要尽快到伦敦塔去检阅枪炮和弹药，然后我还要宣布幼主亨利登基。\u003cb class=\"epub-calibre3\">（下。）\u003c/b>\u003c/p>\n","text":"葛罗斯特 我要尽快到伦敦塔去检阅枪炮和弹药，然后我还要宣布幼主亨利登基。（下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00081","html":"\u003cp class=\"epub-calibre1\">爱克塞特 我要赶往埃尔萨姆宫，那是新王驻跸的所在。我被任为他的侍从大臣，就应当竭力保卫他的安全。\u003cb class=\"epub-calibre3\">（下。）\u003c/b>\u003c/p>\n","text":"爱克塞特 我要赶往埃尔萨姆宫，那是新王驻跸的所在。我被任为他的侍从大臣，就应当竭力保卫他的安全。（下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00082","html":"\u003cp class=\"epub-calibre1\">温彻斯特 他们每人都有职位，都有公事要办，只剩下我独自一人无事可做。可我也不是一个久甘寂寞的人。我打算把新王从埃尔萨姆宫哄出来，好让我坐上掌握国运的最高舵楼。\u003cb class=\"epub-calibre3\">（同下。）\u003c/b>\u003c/p>\n","text":"温彻斯特 他们每人都有职位，都有公事要办，只剩下我独自一人无事可做。可我也不是一个久甘寂寞的人。我打算把新王从埃尔萨姆宫哄出来，好让我坐上掌握国运的最高舵楼。（同下。）\n","sourceAnchor":null,"tag":"p"}],"heading":"第一场 威司敏斯特寺院","headingLevel":4,"sourceAnchor":"a460","actNumber":1,"sceneNumber":1},{"id":"part0022-section-003","label":"第一幕 · 第二场 法国。奥尔良城前","kind":"scene","blocks":[{"id":"part0022-00083","html":"\u003ch4 id=\"epub-part0022-a461\" class=\"epub-calibre12\">第二场 法国。奥尔良城前\u003c/h4>\n","text":"第二场 法国。奥尔良城前\n","sourceAnchor":"a461","tag":"h4"},{"id":"part0022-00084","html":"\u003cp class=\"epub-block1\">喇叭奏花腔。法国太子查理、阿朗松、瑞尼埃率鼓乐及兵士同上。\u003c/p>\n","text":"喇叭奏花腔。法国太子查理、阿朗松、瑞尼埃率鼓乐及兵士同上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00085","html":"\u003cp class=\"epub-calibre1\">查理 战神这座星宿在人世间的行程，就像他在天上的行程一样，到底是采取怎样的路线，至今还没法猜透；不久以前他还照耀在英国人的头顶上，而现在我们却成为胜利者，他在对着我们微笑了。现在哪一座重要的城市不是掌握在我们的手中？我们驻扎在奥尔良附近，好不逍遥自在！英国的饿鬼们，像苍白的幽灵一样，只能在偶尔之间向我们进行一次虚弱无力的围攻。\u003c/p>\n","text":"查理 战神这座星宿在人世间的行程，就像他在天上的行程一样，到底是采取怎样的路线，至今还没法猜透；不久以前他还照耀在英国人的头顶上，而现在我们却成为胜利者，他在对着我们微笑了。现在哪一座重要的城市不是掌握在我们的手中？我们驻扎在奥尔良附近，好不逍遥自在！英国的饿鬼们，像苍白的幽灵一样，只能在偶尔之间向我们进行一次虚弱无力的围攻。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00086","html":"\u003cp class=\"epub-calibre1\">阿朗松 英国佬都是些贪嘴的家伙，爱的是菜汤和肥牛肉。你得像喂骡子一样饲养他们，把草料拴在他们的嘴上，不然的话，他们就同淹死的老鼠一般，垂头丧气。\u003c/p>\n","text":"阿朗松 英国佬都是些贪嘴的家伙，爱的是菜汤和肥牛肉。你得像喂骡子一样饲养他们，把草料拴在他们的嘴上，不然的话，他们就同淹死的老鼠一般，垂头丧气。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00087","html":"\u003cp class=\"epub-calibre1\">瑞尼埃 让我们立刻去解奥尔良之围，干吗还要呆在这里？我们素来所怕的那个塔尔博已被我们捉住了，剩下来的只有那个笨蛋萨立斯伯雷。他在那里只能干着急，手里既无兵、又无钱，没法把仗打下去。\u003c/p>\n","text":"瑞尼埃 让我们立刻去解奥尔良之围，干吗还要呆在这里？我们素来所怕的那个塔尔博已被我们捉住了，剩下来的只有那个笨蛋萨立斯伯雷。他在那里只能干着急，手里既无兵、又无钱，没法把仗打下去。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00088","html":"\u003cp class=\"epub-calibre1\">查理 吩咐他们擂起鼓来！我们要向他们进攻。为了我们颠沛流离的法兰西人民的荣誉，猛攻呀！谁要是看见我退却一步，就拔出刀来杀掉我，我决不加罪于他。\u003cb class=\"epub-calibre3\">（同下。）\u003c/b>\u003c/p>\n","text":"查理 吩咐他们擂起鼓来！我们要向他们进攻。为了我们颠沛流离的法兰西人民的荣誉，猛攻呀！谁要是看见我退却一步，就拔出刀来杀掉我，我决不加罪于他。（同下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00089","html":"\u003cp class=\"epub-block1\">内擂鼓；两军交锋，法军败退。查理、阿朗松及瑞尼埃等同重上。\u003c/p>\n","text":"内擂鼓；两军交锋，法军败退。查理、阿朗松及瑞尼埃等同重上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00090","html":"\u003cp class=\"epub-calibre1\">查理 谁见过这样的事情？在我手下的都是一班什么人！都是些狗崽子！懦夫！胆小鬼！我本来不想逃，可他们竟把我丢在敌人当中不管了。\u003c/p>\n","text":"查理 谁见过这样的事情？在我手下的都是一班什么人！都是些狗崽子！懦夫！胆小鬼！我本来不想逃，可他们竟把我丢在敌人当中不管了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00091","html":"\u003cp class=\"epub-calibre1\">瑞尼埃 萨立斯伯雷简直是个亡命之徒，他打起仗来简直像活够了似的。其余的将军们也像饿狮一般，把我们当作他们的口中之食。\u003c/p>\n","text":"瑞尼埃 萨立斯伯雷简直是个亡命之徒，他打起仗来简直像活够了似的。其余的将军们也像饿狮一般，把我们当作他们的口中之食。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00092","html":"\u003cp class=\"epub-calibre1\">阿朗松 我国一位历史家傅瓦萨写过这样的记载，他说，英王爱德华三世在位时代，猛将如云，战士如雨，现在看起来，这话倒是真实的。他们派出来的将士，都和巨无霸一样，真是一以当十。这些骨瘦如柴的恶棍呀！谁料得到他们竟是如此的勇敢善战？\u003c/p>\n","text":"阿朗松 我国一位历史家傅瓦萨写过这样的记载，他说，英王爱德华三世在位时代，猛将如云，战士如雨，现在看起来，这话倒是真实的。他们派出来的将士，都和巨无霸一样，真是一以当十。这些骨瘦如柴的恶棍呀！谁料得到他们竟是如此的勇敢善战？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00093","html":"\u003cp class=\"epub-calibre1\">查理 我们还是快点离开这里吧，那些轻举妄动的奴才，为饥饿所迫，是会更加拼命的。我早就知道他们的性格，他们宁可用牙齿啃下城墙，也决不肯把围城的兵丁撤退。\u003c/p>\n","text":"查理 我们还是快点离开这里吧，那些轻举妄动的奴才，为饥饿所迫，是会更加拼命的。我早就知道他们的性格，他们宁可用牙齿啃下城墙，也决不肯把围城的兵丁撤退。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00094","html":"\u003cp class=\"epub-calibre1\">瑞尼埃 我猜想他们的胳膊一定像自鸣钟上的小槌一样，是用什么机械装上的，能自动地敲打，不然的话，他们怎能一直坚持下去？依我的愚见，还是不要惹他们的好。\u003c/p>\n","text":"瑞尼埃 我猜想他们的胳膊一定像自鸣钟上的小槌一样，是用什么机械装上的，能自动地敲打，不然的话，他们怎能一直坚持下去？依我的愚见，还是不要惹他们的好。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00095","html":"\u003cp class=\"epub-calibre1\">阿朗松 我也同意。\u003c/p>\n","text":"阿朗松 我也同意。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00096","html":"\u003cp class=\"epub-block1\">奥尔良庶子上。\u003c/p>\n","text":"奥尔良庶子上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00097","html":"\u003cp class=\"epub-calibre1\">庶子 太子殿下在哪里？我有要事向他禀报。\u003c/p>\n","text":"庶子 太子殿下在哪里？我有要事向他禀报。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00098","html":"\u003cp class=\"epub-calibre1\">查理 奥尔良贤卿，我万分欢迎你来到这里。\u003c/p>\n","text":"查理 奥尔良贤卿，我万分欢迎你来到这里。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00099","html":"\u003cp class=\"epub-calibre1\">庶子 我看到殿下似乎有些闷闷不乐，您的一团高兴已经消逝了，是不是因为新近吃了败仗的缘故？且请殿下宽心，我们有了救星了。我带来了一位圣女，她受到上苍的启示，奉命前来替这危城解围，还要把英国兵逐出我们的国境。她具有很深的道行，比古罗马的九天仙女的道行还要高。无论往古来今，她都洞如观火。请殿下降旨，可否由我引她来晋见？请您相信我的报告，并无半句虚言。\u003c/p>\n","text":"庶子 我看到殿下似乎有些闷闷不乐，您的一团高兴已经消逝了，是不是因为新近吃了败仗的缘故？且请殿下宽心，我们有了救星了。我带来了一位圣女，她受到上苍的启示，奉命前来替这危城解围，还要把英国兵逐出我们的国境。她具有很深的道行，比古罗马的九天仙女的道行还要高。无论往古来今，她都洞如观火。请殿下降旨，可否由我引她来晋见？请您相信我的报告，并无半句虚言。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00100","html":"\u003cp class=\"epub-calibre1\">查理 好，带她来见我。\u003cb class=\"epub-calibre3\">（庶子下）\u003c/b>让我们先来考验她一下，瑞尼埃，你暂且扮作本太子的模样，拿起架子来和她对话，你要摆出十分的气派，这样才能试得出她到底有没有道行。\u003cb class=\"epub-calibre3\">（退至台后。）\u003c/b>\u003c/p>\n","text":"查理 好，带她来见我。（庶子下）让我们先来考验她一下，瑞尼埃，你暂且扮作本太子的模样，拿起架子来和她对话，你要摆出十分的气派，这样才能试得出她到底有没有道行。（退至台后。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00101","html":"\u003cp class=\"epub-block1\">奥尔良庶子引贞德同上。\u003c/p>\n","text":"奥尔良庶子引贞德同上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00102","html":"\u003cp class=\"epub-calibre1\">瑞尼埃 好姑娘，是由你来承担这非常的任务吗？\u003c/p>\n","text":"瑞尼埃 好姑娘，是由你来承担这非常的任务吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00103","html":"\u003cp class=\"epub-calibre1\">贞德 瑞尼埃，是你打算来哄骗我吗？太子在哪里？嗨，请从后边走出来吧。我虽没有见过您，可我对您是熟悉的。不要感到惊奇，天下事全都瞒不过我。请您屏去左右，我要单独和您谈话。列位大人，暂请退下，让我和太子交谈。\u003c/p>\n","text":"贞德 瑞尼埃，是你打算来哄骗我吗？太子在哪里？嗨，请从后边走出来吧。我虽没有见过您，可我对您是熟悉的。不要感到惊奇，天下事全都瞒不过我。请您屏去左右，我要单独和您谈话。列位大人，暂请退下，让我和太子交谈。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00104","html":"\u003cp class=\"epub-calibre1\">瑞尼埃 她这一开头气派就不小哇。\u003c/p>\n","text":"瑞尼埃 她这一开头气派就不小哇。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00105","html":"\u003cp class=\"epub-calibre1\">贞德 太子殿下，我的出身是个牧人的女儿，我没有受过什么教育。可是上帝和仁慈的圣母对我垂青，用他们的荣光照耀在我的卑微的身世之上。有一天，我正在照料着我的温柔的羊群，我的双颊曝晒在烈日之下，圣母忽然向我显灵，显出庄严法象，命令我离开我的低微职业，去挽救我们国家的灾难。她允诺给我支援，保证我一定胜利。她的法象充满荣光。我本来生得黝黑，她却用圣洁的光辉注射在我的身上，把我变成一个美好的女子，正如您现在看到的模样。请您向我提出任何的问题，我可以不假思索，对答如流。假如您有胆量和我比武，您可以试试我的勇力，您会发现我绝非寻常女流可比。只要您下定决心，和我结为战友，包管你无往不利。\u003c/p>\n","text":"贞德 太子殿下，我的出身是个牧人的女儿，我没有受过什么教育。可是上帝和仁慈的圣母对我垂青，用他们的荣光照耀在我的卑微的身世之上。有一天，我正在照料着我的温柔的羊群，我的双颊曝晒在烈日之下，圣母忽然向我显灵，显出庄严法象，命令我离开我的低微职业，去挽救我们国家的灾难。她允诺给我支援，保证我一定胜利。她的法象充满荣光。我本来生得黝黑，她却用圣洁的光辉注射在我的身上，把我变成一个美好的女子，正如您现在看到的模样。请您向我提出任何的问题，我可以不假思索，对答如流。假如您有胆量和我比武，您可以试试我的勇力，您会发现我绝非寻常女流可比。只要您下定决心，和我结为战友，包管你无往不利。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00106","html":"\u003cp class=\"epub-calibre1\">查理 你这样大的口气，已经使我吃惊。我只须再试一试你的勇力，我要和你单人比武，如果你得胜，我就相信你所说的全是真话，否则你就得不到我的信任。\u003c/p>\n","text":"查理 你这样大的口气，已经使我吃惊。我只须再试一试你的勇力，我要和你单人比武，如果你得胜，我就相信你所说的全是真话，否则你就得不到我的信任。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00107","html":"\u003cp class=\"epub-calibre1\">贞德 我已经准备好了。这是我的锋利的宝剑，两边都镌有五朵百合花的花纹。我这口剑是我在土瑞恩省圣凯瑟琳礼拜堂的后院里从一堆废铁里拣出来的。\u003c/p>\n","text":"贞德 我已经准备好了。这是我的锋利的宝剑，两边都镌有五朵百合花的花纹。我这口剑是我在土瑞恩省圣凯瑟琳礼拜堂的后院里从一堆废铁里拣出来的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00108","html":"\u003cp class=\"epub-calibre1\">查理 来吧，凭上帝的名义；女人是吓不倒我的。\u003c/p>\n","text":"查理 来吧，凭上帝的名义；女人是吓不倒我的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00109","html":"\u003cp class=\"epub-calibre1\">贞德 我只要还有一口气，就决不在男人面前退缩。\u003c/p>\n","text":"贞德 我只要还有一口气，就决不在男人面前退缩。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00110","html":"\u003cp class=\"epub-block1\">两人交手，贞德胜。\u003c/p>\n","text":"两人交手，贞德胜。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00111","html":"\u003cp class=\"epub-calibre1\">查理 停下来，快住手！你是一个女英雄，使起剑来赛过底波拉\u003ca id=\"epub-part0022-w003\">\u003c/a>\u003ca href=\"#epub-part0022-m003\" data-source-anchor=\"m003\">\u003csup class=\"epub-calibre13\">[3]\u003c/sup>\u003c/a>。\u003c/p>\n","text":"查理 停下来，快住手！你是一个女英雄，使起剑来赛过底波拉[3]。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00112","html":"\u003cp class=\"epub-calibre1\">贞德 我是得到圣母的助力，要不然，我哪有这般力气。\u003c/p>\n","text":"贞德 我是得到圣母的助力，要不然，我哪有这般力气。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00113","html":"\u003cp class=\"epub-calibre1\">查理 不管助你的是谁，反正你是非给我助力不可了。我心头燃烧着爱慕你的烈火，你不单降伏了我的手，你也降伏了我的心。超群绝伦的贞德呵，假如你的名字是这两个字，不要把我当作你的君主，把我当作你的臣仆吧。法国太子在这里向你求爱了。\u003c/p>\n","text":"查理 不管助你的是谁，反正你是非给我助力不可了。我心头燃烧着爱慕你的烈火，你不单降伏了我的手，你也降伏了我的心。超群绝伦的贞德呵，假如你的名字是这两个字，不要把我当作你的君主，把我当作你的臣仆吧。法国太子在这里向你求爱了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00114","html":"\u003cp class=\"epub-calibre1\">贞德 我乃是奉天意前来救世，在此刻谈不到儿女私情；等我把国境内狼烟扫净，那时节再和你叙叙衷情。\u003c/p>\n","text":"贞德 我乃是奉天意前来救世，在此刻谈不到儿女私情；等我把国境内狼烟扫净，那时节再和你叙叙衷情。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00115","html":"\u003cp class=\"epub-calibre1\">查理 只求你对我这匍匐在你面前的奴仆表示一点怜恤之意吧。\u003c/p>\n","text":"查理 只求你对我这匍匐在你面前的奴仆表示一点怜恤之意吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00116","html":"\u003cp class=\"epub-calibre1\">瑞尼埃 我看我们的主公谈话的时间够长啦。\u003c/p>\n","text":"瑞尼埃 我看我们的主公谈话的时间够长啦。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00117","html":"\u003cp class=\"epub-calibre1\">阿朗松 他听取这女人的报告一直听到她贴肉的衣服里去了，否则怎么会把谈话的时间拉得这么长。\u003c/p>\n","text":"阿朗松 他听取这女人的报告一直听到她贴肉的衣服里去了，否则怎么会把谈话的时间拉得这么长。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00118","html":"\u003cp class=\"epub-calibre1\">瑞尼埃 他既然这样漫无节制，要不要叫他一声？\u003c/p>\n","text":"瑞尼埃 他既然这样漫无节制，要不要叫他一声？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00119","html":"\u003cp class=\"epub-calibre1\">阿朗松 他总有他的道理，我们这些可怜的人是猜不透的。这种女人口齿利落，怪会迷人的。\u003c/p>\n","text":"阿朗松 他总有他的道理，我们这些可怜的人是猜不透的。这种女人口齿利落，怪会迷人的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00120","html":"\u003cp class=\"epub-calibre1\">瑞尼埃 殿下，您在哪儿啦？您在打什么主意呀？我们是不是放弃奥尔良，嗯？\u003c/p>\n","text":"瑞尼埃 殿下，您在哪儿啦？您在打什么主意呀？我们是不是放弃奥尔良，嗯？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00121","html":"\u003cp class=\"epub-calibre1\">贞德 哪儿的话，你们这些多疑的胆小鬼！当然不放弃，我说。战斗到最后一口气，我担当你们的守护人。\u003c/p>\n","text":"贞德 哪儿的话，你们这些多疑的胆小鬼！当然不放弃，我说。战斗到最后一口气，我担当你们的守护人。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00122","html":"\u003cp class=\"epub-calibre1\">查理 她说的话我全批准，我们要作战到底。\u003c/p>\n","text":"查理 她说的话我全批准，我们要作战到底。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00123","html":"\u003cp class=\"epub-calibre1\">贞德 我是奉了天命来讨伐英国人的，今晚就一定把奥尔良解围。等我一加入战争，太平日子就快到来了。光荣如同水面上的水花一样，从一个小圆圈变成大圆圈，不停地扩大，直到无可再大，归于消灭。英王亨利一死，英国的光荣圈也完蛋了，圈儿里的荣光也就消逝无余了。我好比是那座巍峨壮丽的楼船，上面装载着恺撒和他的好运。\u003ca id=\"epub-part0022-w004\">\u003c/a>\u003ca href=\"#epub-part0022-m004\" data-source-anchor=\"m004\">\u003csup class=\"epub-calibre13\">[4]\u003c/sup>\u003c/a>\u003c/p>\n","text":"贞德 我是奉了天命来讨伐英国人的，今晚就一定把奥尔良解围。等我一加入战争，太平日子就快到来了。光荣如同水面上的水花一样，从一个小圆圈变成大圆圈，不停地扩大，直到无可再大，归于消灭。英王亨利一死，英国的光荣圈也完蛋了，圈儿里的荣光也就消逝无余了。我好比是那座巍峨壮丽的楼船，上面装载着恺撒和他的好运。[4]\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00124","html":"\u003cp class=\"epub-calibre1\">查理 据说穆罕默德是由一只鸽子将天意传授给他的，那么，传授天意给你的一定是只天鹰。无论是当年康士坦丁大帝的海伦娜母后\u003ca id=\"epub-part0022-w005\">\u003c/a>\u003ca href=\"#epub-part0022-m005\" data-source-anchor=\"m005\">\u003csup class=\"epub-calibre13\">[5]\u003c/sup>\u003c/a>，或是圣腓力的女儿们\u003ca id=\"epub-part0022-w006\">\u003c/a>\u003ca href=\"#epub-part0022-m006\" data-source-anchor=\"m006\">\u003csup class=\"epub-calibre13\">[6]\u003c/sup>\u003c/a>，谁都比不上你。从天而降的司理美丽与爱情的女神呵，无论我怎样对你膜拜顶礼，也表达不出我的爱慕之情呵！\u003c/p>\n","text":"查理 据说穆罕默德是由一只鸽子将天意传授给他的，那么，传授天意给你的一定是只天鹰。无论是当年康士坦丁大帝的海伦娜母后[5]，或是圣腓力的女儿们[6]，谁都比不上你。从天而降的司理美丽与爱情的女神呵，无论我怎样对你膜拜顶礼，也表达不出我的爱慕之情呵！\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00125","html":"\u003cp class=\"epub-calibre1\">阿朗松 别再耽搁啦，赶快去解围要紧。\u003c/p>\n","text":"阿朗松 别再耽搁啦，赶快去解围要紧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00126","html":"\u003cp class=\"epub-calibre1\">瑞尼埃 那一女子听着，拿出你的本领来挽救我们的荣誉，把敌人从奥尔良赶走，你就将名垂不朽了。\u003c/p>\n","text":"瑞尼埃 那一女子听着，拿出你的本领来挽救我们的荣誉，把敌人从奥尔良赶走，你就将名垂不朽了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00127","html":"\u003cp class=\"epub-calibre1\">查理 我们马上就试试，来吧，让我们立即动手。假如她的话不灵验，以后我就再也不相信什么先知了。\u003cb class=\"epub-calibre3\">（同下。）\u003c/b>\u003c/p>\n","text":"查理 我们马上就试试，来吧，让我们立即动手。假如她的话不灵验，以后我就再也不相信什么先知了。（同下。）\n","sourceAnchor":null,"tag":"p"}],"heading":"第二场 法国。奥尔良城前","headingLevel":4,"sourceAnchor":"a461","actNumber":1,"sceneNumber":2},{"id":"part0022-section-004","label":"第一幕 · 第三场 伦敦。伦敦塔前","kind":"scene","blocks":[{"id":"part0022-00128","html":"\u003ch4 id=\"epub-part0022-a462\" class=\"epub-calibre12\">第三场 伦敦。伦敦塔前\u003c/h4>\n","text":"第三场 伦敦。伦敦塔前\n","sourceAnchor":"a462","tag":"h4"},{"id":"part0022-00129","html":"\u003cp class=\"epub-block1\">葛罗斯特率蓝制服的亲兵来至塔门。\u003c/p>\n","text":"葛罗斯特率蓝制服的亲兵来至塔门。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00130","html":"\u003cp class=\"epub-calibre1\">葛罗斯特 我今天来到这里视察伦敦塔。自从亨利老王去世以后，我很担心有人在搞什么阴谋。守兵们都往哪里去了，怎不在这里值班？把门打开，是我葛罗斯特公爵来叫门。\u003cb class=\"epub-calibre3\">（亲兵敲门。）\u003c/b>\u003c/p>\n","text":"葛罗斯特 我今天来到这里视察伦敦塔。自从亨利老王去世以后，我很担心有人在搞什么阴谋。守兵们都往哪里去了，怎不在这里值班？把门打开，是我葛罗斯特公爵来叫门。（亲兵敲门。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00131","html":"\u003cp class=\"epub-calibre1\">守兵甲 \u003cb class=\"epub-calibre3\">（内）\u003c/b>谁在大惊小怪地敲门？\u003c/p>\n","text":"守兵甲 （内）谁在大惊小怪地敲门？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00132","html":"\u003cp class=\"epub-calibre1\">亲兵甲 是尊贵的葛罗斯特爵爷在叫门。\u003c/p>\n","text":"亲兵甲 是尊贵的葛罗斯特爵爷在叫门。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00133","html":"\u003cp class=\"epub-calibre1\">守兵乙 \u003cb class=\"epub-calibre3\">（内）\u003c/b>不管是谁，别想进来。\u003c/p>\n","text":"守兵乙 （内）不管是谁，别想进来。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00134","html":"\u003cp class=\"epub-calibre1\">亲兵甲 混账东西，你们对护国公大人是这样回话的吗？\u003c/p>\n","text":"亲兵甲 混账东西，你们对护国公大人是这样回话的吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00135","html":"\u003cp class=\"epub-calibre1\">守兵甲 \u003cb class=\"epub-calibre3\">（内）\u003c/b>让老天爷护着他吧！我们就是这样回他的话。我们奉命怎么办就怎么办。\u003c/p>\n","text":"守兵甲 （内）让老天爷护着他吧！我们就是这样回他的话。我们奉命怎么办就怎么办。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00136","html":"\u003cp class=\"epub-calibre1\">葛罗斯特 奉谁的命？除了我的命令，还有谁的命令算数？朝廷里只有我是护国公。快把门打开，我保证你们不会错。难道一群粪夫们也敢在我面前调皮捣鬼？\u003cb class=\"epub-calibre3\">（葛罗斯特的亲兵们冲打塔门，守塔的卫队长伍德维尔在内白。）\u003c/b>\u003c/p>\n","text":"葛罗斯特 奉谁的命？除了我的命令，还有谁的命令算数？朝廷里只有我是护国公。快把门打开，我保证你们不会错。难道一群粪夫们也敢在我面前调皮捣鬼？（葛罗斯特的亲兵们冲打塔门，守塔的卫队长伍德维尔在内白。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00137","html":"\u003cp class=\"epub-calibre1\">伍德维尔 \u003cb class=\"epub-calibre3\">（内）\u003c/b>什么事这样喊叫？什么人想在这里造反？\u003c/p>\n","text":"伍德维尔 （内）什么事这样喊叫？什么人想在这里造反？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00138","html":"\u003cp class=\"epub-calibre1\">葛罗斯特 卫队长，我是听见你的声音在说话吗？开开门，本公爵要进来。\u003c/p>\n","text":"葛罗斯特 卫队长，我是听见你的声音在说话吗？开开门，本公爵要进来。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00139","html":"\u003cp class=\"epub-calibre1\">伍德维尔 \u003cb class=\"epub-calibre3\">（内）\u003c/b>对不起，尊贵的爵爷，我不能开门，温彻斯特红衣主教有令不准开门。他特地吩咐我不准放你和你的手下人进来。\u003c/p>\n","text":"伍德维尔 （内）对不起，尊贵的爵爷，我不能开门，温彻斯特红衣主教有令不准开门。他特地吩咐我不准放你和你的手下人进来。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00140","html":"\u003cp class=\"epub-calibre1\">葛罗斯特 糊涂的伍德维尔，你把他看得比我更重吗？那个大胆的温彻斯特，那个肆无忌惮的、老王在日一直不能容忍的主教？你这样做，既得罪了上帝，也得罪了王上。快开门，否则我立即要把你撵出去。\u003c/p>\n","text":"葛罗斯特 糊涂的伍德维尔，你把他看得比我更重吗？那个大胆的温彻斯特，那个肆无忌惮的、老王在日一直不能容忍的主教？你这样做，既得罪了上帝，也得罪了王上。快开门，否则我立即要把你撵出去。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00141","html":"\u003cp class=\"epub-calibre1\">亲兵甲 开门让护国公进去。如果你们不快点开，我们就要冲进来了。\u003c/p>\n","text":"亲兵甲 开门让护国公进去。如果你们不快点开，我们就要冲进来了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00142","html":"\u003cp class=\"epub-block1\">温彻斯特率领褐制服的亲兵上。\u003c/p>\n","text":"温彻斯特率领褐制服的亲兵上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00143","html":"\u003cp class=\"epub-calibre1\">温彻斯特 怎么啦，野心的亨弗雷！这是怎么回事？\u003c/p>\n","text":"温彻斯特 怎么啦，野心的亨弗雷！这是怎么回事？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00144","html":"\u003cp class=\"epub-calibre1\">葛罗斯特 光脑袋的和尚，是你命令他们把我关在门外的吗？\u003c/p>\n","text":"葛罗斯特 光脑袋的和尚，是你命令他们把我关在门外的吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00145","html":"\u003cp class=\"epub-calibre1\">温彻斯特 是我。你哪里是我们朝廷里的护国公？倒不如说你是一个揽权僭位的窃国公。\u003c/p>\n","text":"温彻斯特 是我。你哪里是我们朝廷里的护国公？倒不如说你是一个揽权僭位的窃国公。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00146","html":"\u003cp class=\"epub-calibre1\">葛罗斯特 退下，你这明目张胆的阴谋家，你打着坏主意想害死老王，你纵容娼妓们干罪孽的勾当\u003ca id=\"epub-part0022-w007\">\u003c/a>\u003ca href=\"#epub-part0022-m007\" data-source-anchor=\"m007\">\u003csup class=\"epub-calibre13\">[7]\u003c/sup>\u003c/a>。你如果再这样荒唐下去，我要把你盛在你的宽边的红衣主教帽子里，抛上去再扔下来。\u003c/p>\n","text":"葛罗斯特 退下，你这明目张胆的阴谋家，你打着坏主意想害死老王，你纵容娼妓们干罪孽的勾当[7]。你如果再这样荒唐下去，我要把你盛在你的宽边的红衣主教帽子里，抛上去再扔下来。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00147","html":"\u003cp class=\"epub-calibre1\">温彻斯特 胡说，你给我退下，我是一步也不后退的。只要你敢，你就把这地方当作大马士革，亲自扮演那个杀死亲兄弟的罪犯该隐吧。\u003c/p>\n","text":"温彻斯特 胡说，你给我退下，我是一步也不后退的。只要你敢，你就把这地方当作大马士革，亲自扮演那个杀死亲兄弟的罪犯该隐吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00148","html":"\u003cp class=\"epub-calibre1\">葛罗斯特 我不杀你，我只把你赶回去。我要用你的大红袍当作送婴儿受洗的襁褓，把你从这里抬走。\u003c/p>\n","text":"葛罗斯特 我不杀你，我只把你赶回去。我要用你的大红袍当作送婴儿受洗的襁褓，把你从这里抬走。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00149","html":"\u003cp class=\"epub-calibre1\">温彻斯特 你敢怎样就怎样，我当面刮你的胡子。\u003c/p>\n","text":"温彻斯特 你敢怎样就怎样，我当面刮你的胡子。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00150","html":"\u003cp class=\"epub-calibre1\">葛罗斯特 什么！你对我挑衅，你刮我胡子？亲兵们，拔出刀来，保卫这个特权地带。蓝号衣对付褐号衣。和尚，留心你的胡子，我要抓着你的胡子，把你好好地揍一顿。\u003cb class=\"epub-calibre3\">（葛罗斯特及亲兵攻打红衣主教）\u003c/b>我要把你的红衣主教的帽子放在脚底下踩。不管教皇和教会里的权威怎样，我要拧着你的腮帮，把你拖来拖去。\u003c/p>\n","text":"葛罗斯特 什么！你对我挑衅，你刮我胡子？亲兵们，拔出刀来，保卫这个特权地带。蓝号衣对付褐号衣。和尚，留心你的胡子，我要抓着你的胡子，把你好好地揍一顿。（葛罗斯特及亲兵攻打红衣主教）我要把你的红衣主教的帽子放在脚底下踩。不管教皇和教会里的权威怎样，我要拧着你的腮帮，把你拖来拖去。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00151","html":"\u003cp class=\"epub-calibre1\">温彻斯特 葛罗斯特，你这样胡闹，看你怎样对教皇交代。\u003c/p>\n","text":"温彻斯特 葛罗斯特，你这样胡闹，看你怎样对教皇交代。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00152","html":"\u003cp class=\"epub-calibre1\">葛罗斯特 婊子儿，我说，给他带上络头，带上络头！把他们赶走，你们为什么让他们呆在这里？你这披着羊皮的狼，我要把你赶走。滚开，褐号衣的家伙！滚开，穿大红袍的伪善者！\u003c/p>\n","text":"葛罗斯特 婊子儿，我说，给他带上络头，带上络头！把他们赶走，你们为什么让他们呆在这里？你这披着羊皮的狼，我要把你赶走。滚开，褐号衣的家伙！滚开，穿大红袍的伪善者！\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00153","html":"\u003cp class=\"epub-block1\">葛罗斯特的亲兵击退红衣主教的亲兵。在混战中伦敦市长率吏员上。\u003c/p>\n","text":"葛罗斯特的亲兵击退红衣主教的亲兵。在混战中伦敦市长率吏员上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00154","html":"\u003cp class=\"epub-calibre1\">市长 嗳哟，大人们！你们这些高级官长怎么不怕难为情，公然扰乱治安！\u003c/p>\n","text":"市长 嗳哟，大人们！你们这些高级官长怎么不怕难为情，公然扰乱治安！\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00155","html":"\u003cp class=\"epub-calibre1\">葛罗斯特 还说什么治安，市长！你哪知道我受的什么气。波福这家伙，目无上帝，目无王上，竟把伦敦塔占为私有啦。\u003c/p>\n","text":"葛罗斯特 还说什么治安，市长！你哪知道我受的什么气。波福这家伙，目无上帝，目无王上，竟把伦敦塔占为私有啦。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00156","html":"\u003cp class=\"epub-calibre1\">温彻斯特 这个葛罗斯特是人民的公敌，他挑拨战争，破坏和平，他用苛刻的罚金榨取你们自由人的钱袋，他企图推翻教会。他当上了护国公，就一心想把这塔里的军械弄到手，好让他迫害太子，篡夺王位。\u003c/p>\n","text":"温彻斯特 这个葛罗斯特是人民的公敌，他挑拨战争，破坏和平，他用苛刻的罚金榨取你们自由人的钱袋，他企图推翻教会。他当上了护国公，就一心想把这塔里的军械弄到手，好让他迫害太子，篡夺王位。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00157","html":"\u003cp class=\"epub-calibre1\">葛罗斯特 我不用舌头答复你，要用拳头答复你。\u003cb class=\"epub-calibre3\">（双方又混战。）\u003c/b>\u003c/p>\n","text":"葛罗斯特 我不用舌头答复你，要用拳头答复你。（双方又混战。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00158","html":"\u003cp class=\"epub-calibre1\">市长 这样闹下去我没有其他办法，只好给他们一个公开宣告了。来吧，吏员，提高嗓子大声宣告吧。大声点。\u003c/p>\n","text":"市长 这样闹下去我没有其他办法，只好给他们一个公开宣告了。来吧，吏员，提高嗓子大声宣告吧。大声点。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00159","html":"\u003cp class=\"epub-calibre1\">吏员 一切携带武器聚集在此地破坏上帝和王上的治安的各色人等听着：我以王上陛下的名义责成和命令你们各自回到本人的住处，今后不得携带和使用任何刀剑、匕首或其他兵器，违者处死。\u003c/p>\n","text":"吏员 一切携带武器聚集在此地破坏上帝和王上的治安的各色人等听着：我以王上陛下的名义责成和命令你们各自回到本人的住处，今后不得携带和使用任何刀剑、匕首或其他兵器，违者处死。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00160","html":"\u003cp class=\"epub-calibre1\">葛罗斯特 红衣主教，我不愿违犯法律，过一天我再和你碰头，大家把心里的话尽情说出来。\u003c/p>\n","text":"葛罗斯特 红衣主教，我不愿违犯法律，过一天我再和你碰头，大家把心里的话尽情说出来。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00161","html":"\u003cp class=\"epub-calibre1\">温彻斯特 葛罗斯特，我们还会碰头的；毫无问题，吃亏的将是你。你今天这样横行霸道，我非叫你洒出心头的鲜血不可。\u003c/p>\n","text":"温彻斯特 葛罗斯特，我们还会碰头的；毫无问题，吃亏的将是你。你今天这样横行霸道，我非叫你洒出心头的鲜血不可。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00162","html":"\u003cp class=\"epub-calibre1\">市长 你们如果再不散走开，我要叫他们使用警棍了。这个红衣主教比魔鬼更不讲理。\u003c/p>\n","text":"市长 你们如果再不散走开，我要叫他们使用警棍了。这个红衣主教比魔鬼更不讲理。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00163","html":"\u003cp class=\"epub-calibre1\">葛罗斯特 市长，再见，你这是照章办事。\u003c/p>\n","text":"葛罗斯特 市长，再见，你这是照章办事。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00164","html":"\u003cp class=\"epub-calibre1\">温彻斯特 可恶的葛罗斯特，当心你的脑袋。等不到很久，我一定会把它取下来。\u003cb class=\"epub-calibre3\">（葛罗斯特、温彻斯特率领自己的亲兵分头下。）\u003c/b>\u003c/p>\n","text":"温彻斯特 可恶的葛罗斯特，当心你的脑袋。等不到很久，我一定会把它取下来。（葛罗斯特、温彻斯特率领自己的亲兵分头下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00165","html":"\u003cp class=\"epub-calibre1\">市长 看看还有闲人没有，我们也要走了。我的老天爷，这些贵族们怎么这样爱闹事！我在四十年当中一次架也没打过。\u003cb class=\"epub-calibre3\">（同下。）\u003c/b>\u003c/p>\n","text":"市长 看看还有闲人没有，我们也要走了。我的老天爷，这些贵族们怎么这样爱闹事！我在四十年当中一次架也没打过。（同下。）\n","sourceAnchor":null,"tag":"p"}],"heading":"第三场 伦敦。伦敦塔前","headingLevel":4,"sourceAnchor":"a462","actNumber":1,"sceneNumber":3},{"id":"part0022-section-005","label":"第一幕 · 第四场 法国。奥尔良城前","kind":"scene","blocks":[{"id":"part0022-00166","html":"\u003ch4 id=\"epub-part0022-a463\" class=\"epub-calibre12\">第四场 法国。奥尔良城前\u003c/h4>\n","text":"第四场 法国。奥尔良城前\n","sourceAnchor":"a463","tag":"h4"},{"id":"part0022-00167","html":"\u003cp class=\"epub-block1\">炮兵队长及其子上至城头。\u003c/p>\n","text":"炮兵队长及其子上至城头。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00168","html":"\u003cp class=\"epub-calibre1\">炮兵队长 孩子，奥尔良围困的情形你清楚吗？咱们的近郊都被英国人占领啦。\u003c/p>\n","text":"炮兵队长 孩子，奥尔良围困的情形你清楚吗？咱们的近郊都被英国人占领啦。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00169","html":"\u003cp class=\"epub-calibre1\">儿子 父亲，我全知道；我向他们射击过好多次，可惜我运气不好，没能打中。\u003c/p>\n","text":"儿子 父亲，我全知道；我向他们射击过好多次，可惜我运气不好，没能打中。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00170","html":"\u003cp class=\"epub-calibre1\">炮兵队长 现在你就不会打不中啦。你依照我的吩咐行事；我是本城炮兵的总队长，一定要干出一点出色的事情来。咱们王爷的侦察兵告诉我，英国人在城外把我们围得水泄不通，还老从一座塔楼上铁窗棂的秘密洞口窥探我们城中的虚实，想找出一个最有利的办法，或用炮火，或用冲锋，来对我们进行骚扰。要叫他们不再捣乱，我已经安好一尊大炮，对准那座塔楼；这三天里我一直在监视着他们，等他们一露面我就动手。现在我要到别处走一走，暂且由我瞭望。你一看到有什么动静，就立刻跑来告诉我，你到指挥官那里就能找到我。\u003cb class=\"epub-calibre3\">（下。）\u003c/b>\u003c/p>\n","text":"炮兵队长 现在你就不会打不中啦。你依照我的吩咐行事；我是本城炮兵的总队长，一定要干出一点出色的事情来。咱们王爷的侦察兵告诉我，英国人在城外把我们围得水泄不通，还老从一座塔楼上铁窗棂的秘密洞口窥探我们城中的虚实，想找出一个最有利的办法，或用炮火，或用冲锋，来对我们进行骚扰。要叫他们不再捣乱，我已经安好一尊大炮，对准那座塔楼；这三天里我一直在监视着他们，等他们一露面我就动手。现在我要到别处走一走，暂且由我瞭望。你一看到有什么动静，就立刻跑来告诉我，你到指挥官那里就能找到我。（下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00171","html":"\u003cp class=\"epub-calibre1\">儿子 父亲，我向您保证；您放心好了；若是我看到他们，决不误您的事。\u003cb class=\"epub-calibre3\">（下。）\u003c/b>\u003c/p>\n","text":"儿子 父亲，我向您保证；您放心好了；若是我看到他们，决不误您的事。（下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00172","html":"\u003cp class=\"epub-block1\">萨立斯伯雷、塔尔博、威廉·葛兰斯台尔、托马斯·嘉格莱夫等登上塔楼。\u003c/p>\n","text":"萨立斯伯雷、塔尔博、威廉·葛兰斯台尔、托马斯·嘉格莱夫等登上塔楼。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00173","html":"\u003cp class=\"epub-calibre1\">萨立斯伯雷 塔尔博，我重新见到你，我的活力、我的欢乐，都又回复过来了！你被俘期间，他们是怎样对待你的？你又是用了什么办法获得释放的？我请求你，在这塔楼顶上，跟我谈谈吧。\u003c/p>\n","text":"萨立斯伯雷 塔尔博，我重新见到你，我的活力、我的欢乐，都又回复过来了！你被俘期间，他们是怎样对待你的？你又是用了什么办法获得释放的？我请求你，在这塔楼顶上，跟我谈谈吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00174","html":"\u003cp class=\"epub-calibre1\">塔尔博 培福公爵捉到一个俘虏，一个名叫彭东·德·桑特莱勋爵的勇将，是用他来和我交换，才把我赎回。他们曾想用一个身份低得多的人来换我，那是存心污辱我，我怎能把那样的人放在眼里？我是宁愿一死也不能忍受那样的蔑视的。到后来，终于依照我的要求把我赎回了。可是，哼，那背信弃义的福斯托夫真伤透我的心了，要是此刻我能把他捉回来，我就是用一双拳头也要揍死他。\u003c/p>\n","text":"塔尔博 培福公爵捉到一个俘虏，一个名叫彭东·德·桑特莱勋爵的勇将，是用他来和我交换，才把我赎回。他们曾想用一个身份低得多的人来换我，那是存心污辱我，我怎能把那样的人放在眼里？我是宁愿一死也不能忍受那样的蔑视的。到后来，终于依照我的要求把我赎回了。可是，哼，那背信弃义的福斯托夫真伤透我的心了，要是此刻我能把他捉回来，我就是用一双拳头也要揍死他。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00175","html":"\u003cp class=\"epub-calibre1\">萨立斯伯雷 可是你还没有告诉我你受到了怎样的待遇呢。\u003c/p>\n","text":"萨立斯伯雷 可是你还没有告诉我你受到了怎样的待遇呢。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00176","html":"\u003cp class=\"epub-calibre1\">塔尔博 他们把我拖到街心，对我百般凌辱，要叫我在老百姓面前丢脸。他们口里还说，“这家伙就是我们法国人的死对头，就是吓唬我们的孩子们的稻草人。”后来我从监押我的军官们的手里挣脱出来，用我的指甲挖出地上的石子，向那些看我出丑的观众们扔过去。他们看到我这样凶狠，都吓得四散奔逃，一个也不敢靠近我，唯恐死于非命。他们把我关在铜墙铁壁里还不放心，只因我的威名早使他们慑服，他们甚至以为我能将钢条折断，能将花岗石的柱子碎为齑粉。因此，他们派了一队精选的射击手充当我的守兵，守兵们每分钟都在我周围巡逻，万一我一翻身从床上跌下来，他们也会立刻射穿我的心脏。\u003c/p>\n","text":"塔尔博 他们把我拖到街心，对我百般凌辱，要叫我在老百姓面前丢脸。他们口里还说，“这家伙就是我们法国人的死对头，就是吓唬我们的孩子们的稻草人。”后来我从监押我的军官们的手里挣脱出来，用我的指甲挖出地上的石子，向那些看我出丑的观众们扔过去。他们看到我这样凶狠，都吓得四散奔逃，一个也不敢靠近我，唯恐死于非命。他们把我关在铜墙铁壁里还不放心，只因我的威名早使他们慑服，他们甚至以为我能将钢条折断，能将花岗石的柱子碎为齑粉。因此，他们派了一队精选的射击手充当我的守兵，守兵们每分钟都在我周围巡逻，万一我一翻身从床上跌下来，他们也会立刻射穿我的心脏。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00177","html":"\u003cp class=\"epub-block1\">炮兵队长之子手持火绳杆上。\u003c/p>\n","text":"炮兵队长之子手持火绳杆上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00178","html":"\u003cp class=\"epub-calibre1\">萨立斯伯雷 听到您受了这些苦难，我心里好难过啊，这个仇我们得好好报一下。现在是奥尔良城里吃晚饭的时候了，瞧，我从这个窗棂眼里，可以清清楚楚地看到那些法国人，看到他们的防御工事。大家来看吧，你看到那边的情形会觉得好笑的。嘉格莱夫爵士，葛兰斯台尔爵士，我想征求你们两位的意见，此后我们的炮位安在什么地方最好？\u003c/p>\n","text":"萨立斯伯雷 听到您受了这些苦难，我心里好难过啊，这个仇我们得好好报一下。现在是奥尔良城里吃晚饭的时候了，瞧，我从这个窗棂眼里，可以清清楚楚地看到那些法国人，看到他们的防御工事。大家来看吧，你看到那边的情形会觉得好笑的。嘉格莱夫爵士，葛兰斯台尔爵士，我想征求你们两位的意见，此后我们的炮位安在什么地方最好？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00179","html":"\u003cp class=\"epub-calibre1\">嘉格莱夫 我以为，放在北门最好，因为他们的首脑都集聚在那边。\u003c/p>\n","text":"嘉格莱夫 我以为，放在北门最好，因为他们的首脑都集聚在那边。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00180","html":"\u003cp class=\"epub-calibre1\">葛兰斯台尔 依我看，可以安装在桥头堡上。\u003c/p>\n","text":"葛兰斯台尔 依我看，可以安装在桥头堡上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00181","html":"\u003cp class=\"epub-calibre1\">塔尔博 照我所看到的情形判断起来，城里是缺粮啦，经过这几阵小仗以后，他们的力量是削弱啦。\u003cb class=\"epub-calibre3\">（城上向塔楼开炮，萨立斯伯雷及嘉格莱夫两人倒地。）\u003c/b>\u003c/p>\n","text":"塔尔博 照我所看到的情形判断起来，城里是缺粮啦，经过这几阵小仗以后，他们的力量是削弱啦。（城上向塔楼开炮，萨立斯伯雷及嘉格莱夫两人倒地。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00182","html":"\u003cp class=\"epub-calibre1\">萨立斯伯雷 主啊，对我们这些可怜的罪人大发慈悲吧！\u003c/p>\n","text":"萨立斯伯雷 主啊，对我们这些可怜的罪人大发慈悲吧！\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00183","html":"\u003cp class=\"epub-calibre1\">嘉格莱夫 主啊，垂怜我这个遭难的人吧！\u003c/p>\n","text":"嘉格莱夫 主啊，垂怜我这个遭难的人吧！\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00184","html":"\u003cp class=\"epub-calibre1\">塔尔博 怎么陡然之间发生这场横祸？说呀，萨立斯伯雷。你这位军人的模范，若是你还能开口，至少让我们知道你还能行吗？你一只眼睛和一个腮帮是打掉了！这个可诅咒的塔楼！还有那可诅咒的肇祸凶手！萨立斯伯雷曾打过十三场胜仗，我们的老王也曾跟他学习过军事。只要号筒在吹，战鼓在响，他的大刀在战场上就从不曾歇过手。萨立斯伯雷，你还活着吗？虽然你是不能说话了，可是你还有一只眼睛可以望着上苍，得到上苍的福佑呀。太阳不就是用一只眼睛看着整个世界的吗？老天爷呀，如果萨立斯伯雷得不到您的慈悲，那您就不用再降福给任何活人了！把他的身体抬过去，我要亲自照料他的葬礼。嘉格莱夫爵士，你还有命吗？对塔尔博说呀。唉，你不能开口，就对他看一眼吧。萨立斯伯雷，请你宽心，你是不会白死的，只要——他还向我招手，对我微笑呢，他似乎想说：“我死之后，别忘记在法国人身上替我报仇。”普兰塔琪纳特，我一定替你报仇。我要像罗马的尼禄王一样，一面弹着琵琶，一面观赏那燃烧着的城市。只要有我在，就叫法兰西遭殃。\u003cb class=\"epub-calibre3\">（一阵鼓角声，天空鸣雷闪电）\u003c/b>这阵骚乱是怎么一回事？天上怎么也是乱七八糟的？哪里来的这阵鼓角声和喧哗？\u003c/p>\n","text":"塔尔博 怎么陡然之间发生这场横祸？说呀，萨立斯伯雷。你这位军人的模范，若是你还能开口，至少让我们知道你还能行吗？你一只眼睛和一个腮帮是打掉了！这个可诅咒的塔楼！还有那可诅咒的肇祸凶手！萨立斯伯雷曾打过十三场胜仗，我们的老王也曾跟他学习过军事。只要号筒在吹，战鼓在响，他的大刀在战场上就从不曾歇过手。萨立斯伯雷，你还活着吗？虽然你是不能说话了，可是你还有一只眼睛可以望着上苍，得到上苍的福佑呀。太阳不就是用一只眼睛看着整个世界的吗？老天爷呀，如果萨立斯伯雷得不到您的慈悲，那您就不用再降福给任何活人了！把他的身体抬过去，我要亲自照料他的葬礼。嘉格莱夫爵士，你还有命吗？对塔尔博说呀。唉，你不能开口，就对他看一眼吧。萨立斯伯雷，请你宽心，你是不会白死的，只要——他还向我招手，对我微笑呢，他似乎想说：“我死之后，别忘记在法国人身上替我报仇。”普兰塔琪纳特，我一定替你报仇。我要像罗马的尼禄王一样，一面弹着琵琶，一面观赏那燃烧着的城市。只要有我在，就叫法兰西遭殃。（一阵鼓角声，天空鸣雷闪电）这阵骚乱是怎么一回事？天上怎么也是乱七八糟的？哪里来的这阵鼓角声和喧哗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00185","html":"\u003cp class=\"epub-block1\">一使者上。\u003c/p>\n","text":"一使者上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00186","html":"\u003cp class=\"epub-calibre1\">使者 大人，大人，法国的人马增添了。一个新露面的女圣贤，叫做什么贞德的，扶持着法国太子，率领着一支大军来替奥尔良解围了。\u003cb class=\"epub-calibre3\">（萨立斯伯雷抬起身子，发出呻吟之声。）\u003c/b>\u003c/p>\n","text":"使者 大人，大人，法国的人马增添了。一个新露面的女圣贤，叫做什么贞德的，扶持着法国太子，率领着一支大军来替奥尔良解围了。（萨立斯伯雷抬起身子，发出呻吟之声。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00187","html":"\u003cp class=\"epub-calibre1\">塔尔博 听呀，听听萨立斯伯雷临终的呻吟够多惨呀！他报不了仇，心里一定沉痛得很。法兰西人听着，萨立斯伯雷死了，还有我哪！贞德也罢，针黹也罢；太子也罢，弹子也罢，我要用我的马蹄踩出你们的心肺，我要把你们的脑浆捣成稀泥。替我把萨立斯伯雷抬到他的营帐里去，我们倒要试试看这些胆小怕死的法兰西人敢干些什么。\u003cb class=\"epub-calibre3\">（众舁尸体同下。）\u003c/b>\u003c/p>\n","text":"塔尔博 听呀，听听萨立斯伯雷临终的呻吟够多惨呀！他报不了仇，心里一定沉痛得很。法兰西人听着，萨立斯伯雷死了，还有我哪！贞德也罢，针黹也罢；太子也罢，弹子也罢，我要用我的马蹄踩出你们的心肺，我要把你们的脑浆捣成稀泥。替我把萨立斯伯雷抬到他的营帐里去，我们倒要试试看这些胆小怕死的法兰西人敢干些什么。（众舁尸体同下。）\n","sourceAnchor":null,"tag":"p"}],"heading":"第四场 法国。奥尔良城前","headingLevel":4,"sourceAnchor":"a463","actNumber":1,"sceneNumber":4},{"id":"part0022-section-006","label":"第一幕 · 第五场 同前。城门外","kind":"scene","blocks":[{"id":"part0022-00188","html":"\u003ch4 id=\"epub-part0022-a464\" class=\"epub-calibre12\">第五场 同前。城门外\u003c/h4>\n","text":"第五场 同前。城门外\n","sourceAnchor":"a464","tag":"h4"},{"id":"part0022-00189","html":"\u003cp class=\"epub-block1\">鼓角声。两军交战。塔尔博追法国太子下。随后，贞德追逐英军上，绕场后同下。稍顷，塔尔博重上。\u003c/p>\n","text":"鼓角声。两军交战。塔尔博追法国太子下。随后，贞德追逐英军上，绕场后同下。稍顷，塔尔博重上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00190","html":"\u003cp class=\"epub-calibre1\">塔尔博 我的膂力、我的勇气、我的力量，都往哪里去了？我们英国军队退了下来，我止不住他们，一个穿盔戴甲的女人追赶着他们。\u003c/p>\n","text":"塔尔博 我的膂力、我的勇气、我的力量，都往哪里去了？我们英国军队退了下来，我止不住他们，一个穿盔戴甲的女人追赶着他们。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00191","html":"\u003cp class=\"epub-block1\">贞德重上。\u003c/p>\n","text":"贞德重上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00192","html":"\u003cp class=\"epub-calibre1\">塔尔博 嘿，她来了。我要和你决一胜负。你是雄鬼也好，雌鬼也好，我要驱除你这邪魔。你既是一个巫婆，我就抽出你的血来，径直地打发你的灵魂到你侍奉的魔王那里去。\u003c/p>\n","text":"塔尔博 嘿，她来了。我要和你决一胜负。你是雄鬼也好，雌鬼也好，我要驱除你这邪魔。你既是一个巫婆，我就抽出你的血来，径直地打发你的灵魂到你侍奉的魔王那里去。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00193","html":"\u003cp class=\"epub-calibre1\">贞德 来吧，来吧，你是一定要败在我手里的。\u003cb class=\"epub-calibre3\">（两人交战。）\u003c/b>\u003c/p>\n","text":"贞德 来吧，来吧，你是一定要败在我手里的。（两人交战。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00194","html":"\u003cp class=\"epub-calibre1\">塔尔博 老天呀，您能允许魔鬼这般猖獗吗？我奋力过度，我的胸膛要炸开了，我的胳膊要从肩头折裂下来了，但我非把这狂妄的娼妇惩治一下不可。\u003cb class=\"epub-calibre3\">（两人再交战。）\u003c/b>\u003c/p>\n","text":"塔尔博 老天呀，您能允许魔鬼这般猖獗吗？我奋力过度，我的胸膛要炸开了，我的胳膊要从肩头折裂下来了，但我非把这狂妄的娼妇惩治一下不可。（两人再交战。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00195","html":"\u003cp class=\"epub-calibre1\">贞德 算了吧，塔尔博，你的死期还未到。我要赶快把粮食送进奥尔良城里去了。\u003cb class=\"epub-calibre3\">（短短一阵鼓角声，贞德率领兵丁进城）\u003c/b>你若是有本领，就来追我，你那点气力真不在我眼里。去吧，去吧，去抚慰你手下的饿鬼们吧。去帮着萨立斯伯雷写他的遗嘱吧。今天这日子是属于我们的了，以后许多日子还将属于我们。\u003cb class=\"epub-calibre3\">（下。）\u003c/b>\u003c/p>\n","text":"贞德 算了吧，塔尔博，你的死期还未到。我要赶快把粮食送进奥尔良城里去了。（短短一阵鼓角声，贞德率领兵丁进城）你若是有本领，就来追我，你那点气力真不在我眼里。去吧，去吧，去抚慰你手下的饿鬼们吧。去帮着萨立斯伯雷写他的遗嘱吧。今天这日子是属于我们的了，以后许多日子还将属于我们。（下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00196","html":"\u003cp class=\"epub-calibre1\">塔尔博 我的头脑好像陶工的辘轳盘一样在打转。我不知道我此刻是在什么地方，也不知道我是在干什么。这巫婆如同当年汉尼拔使用火牛阵一般，取胜不是凭着兵力，而是凭着制造恐怖，把我们的军队压迫回来。好比是用浓烟把蜜蜂熏出蜂房，用腥臊的臭气把鸽子赶出窠巢。法国人因为我们凶猛善战，管我们叫作英国的恶狗，可我们却像脓包的小狗一样，一面嗥吠，一面逃跑了。\u003cb class=\"epub-calibre3\">（短短一阵鼓角声）\u003c/b>同胞们，听我说！如果我们不能重新战斗下去，那就干脆把我们国徽上的狮子撕掉吧，那就放弃你们的土地，用绵羊来代替狮子吧。绵羊见了狼，牛马见了豹子，也绝不像你们见了屡次败在我们手中的奴隶这样胆怯，逃得这样快。\u003cb class=\"epub-calibre3\">（鼓角声，又一次混战）\u003c/b>没有用，退到你们的战壕里去吧。你们全都愿意让萨立斯伯雷白白死掉的，谁也不肯出一把力，替他报仇雪恨。尽管有我们的大军在此，也不管我们干了些什么，贞德是进了奥尔良城了。唉，我宁愿和萨立斯伯雷一同阵亡！这种败阵的耻辱简直使我抬不起头来。\u003cb class=\"epub-calibre3\">（鼓角声；吹退军号；塔尔博率军队下。）\u003c/b>\u003c/p>\n","text":"塔尔博 我的头脑好像陶工的辘轳盘一样在打转。我不知道我此刻是在什么地方，也不知道我是在干什么。这巫婆如同当年汉尼拔使用火牛阵一般，取胜不是凭着兵力，而是凭着制造恐怖，把我们的军队压迫回来。好比是用浓烟把蜜蜂熏出蜂房，用腥臊的臭气把鸽子赶出窠巢。法国人因为我们凶猛善战，管我们叫作英国的恶狗，可我们却像脓包的小狗一样，一面嗥吠，一面逃跑了。（短短一阵鼓角声）同胞们，听我说！如果我们不能重新战斗下去，那就干脆把我们国徽上的狮子撕掉吧，那就放弃你们的土地，用绵羊来代替狮子吧。绵羊见了狼，牛马见了豹子，也绝不像你们见了屡次败在我们手中的奴隶这样胆怯，逃得这样快。（鼓角声，又一次混战）没有用，退到你们的战壕里去吧。你们全都愿意让萨立斯伯雷白白死掉的，谁也不肯出一把力，替他报仇雪恨。尽管有我们的大军在此，也不管我们干了些什么，贞德是进了奥尔良城了。唉，我宁愿和萨立斯伯雷一同阵亡！这种败阵的耻辱简直使我抬不起头来。（鼓角声；吹退军号；塔尔博率军队下。）\n","sourceAnchor":null,"tag":"p"}],"heading":"第五场 同前。城门外","headingLevel":4,"sourceAnchor":"a464","actNumber":1,"sceneNumber":5},{"id":"part0022-section-007","label":"第一幕 · 第六场 同前","kind":"scene","blocks":[{"id":"part0022-00197","html":"\u003ch4 id=\"epub-part0022-a465\" class=\"epub-calibre12\">第六场 同前\u003c/h4>\n","text":"第六场 同前\n","sourceAnchor":"a465","tag":"h4"},{"id":"part0022-00198","html":"\u003cp class=\"epub-block1\">喇叭奏花腔。贞德、查理、瑞尼埃、阿朗松率兵士登上城头。\u003c/p>\n","text":"喇叭奏花腔。贞德、查理、瑞尼埃、阿朗松率兵士登上城头。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00199","html":"\u003cp class=\"epub-calibre1\">贞德 树起我们的国旗，让它在城头飘扬。奥尔良城已经从英国人手中解救出来了，贞德已经履行了她的诺言。\u003c/p>\n","text":"贞德 树起我们的国旗，让它在城头飘扬。奥尔良城已经从英国人手中解救出来了，贞德已经履行了她的诺言。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00200","html":"\u003cp class=\"epub-calibre1\">查理 尽美至善的人儿，公理之神的女儿，对你这样的丰功伟绩，我怎样才能表示我的敬意呢？你实现你的诺言，又快又好，好比阿都尼的花园，第一天才开的花，第二天就结了果子。法兰西哟，为你的光荣的女先知而高唱凯歌吧！奥尔良已经光复了。在我们国家，这真是一件空前的喜事。\u003c/p>\n","text":"查理 尽美至善的人儿，公理之神的女儿，对你这样的丰功伟绩，我怎样才能表示我的敬意呢？你实现你的诺言，又快又好，好比阿都尼的花园，第一天才开的花，第二天就结了果子。法兰西哟，为你的光荣的女先知而高唱凯歌吧！奥尔良已经光复了。在我们国家，这真是一件空前的喜事。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00201","html":"\u003cp class=\"epub-calibre1\">瑞尼埃 为什么不叫全城鸣钟击鼓？太子殿下，请您颁发谕旨，叫全城公民燃起庆祝的烟火，在大街上摆下庆功的筵席，来欢庆上帝赐给我们的这桩喜事。\u003c/p>\n","text":"瑞尼埃 为什么不叫全城鸣钟击鼓？太子殿下，请您颁发谕旨，叫全城公民燃起庆祝的烟火，在大街上摆下庆功的筵席，来欢庆上帝赐给我们的这桩喜事。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00202","html":"\u003cp class=\"epub-calibre1\">阿朗松 当整个法兰西听到我们的英勇事迹时，到处都将充满欢乐。\u003c/p>\n","text":"阿朗松 当整个法兰西听到我们的英勇事迹时，到处都将充满欢乐。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00203","html":"\u003cp class=\"epub-calibre1\">查理 赢得今天胜利的，不是我们，而是贞德。为了酬谢她的大功，我要和她共享这顶王冠。我要命令全国僧侣列队游行，歌颂她无穷的功德。我要为她兴建一座比孟菲斯更为庄严的金字塔。将来如果她一旦逝世，为了纪念她的遗徽，我们要用七宝香车，装殓她的骨殖，在盛大的仪仗中，运送到法兰西的先王、先后的陵寝中去安葬。以后我们就不用再向圣丹尼斯祈祷了，贞德圣女将成为法兰西的保护神。随我来吧，在这黄金般的胜利日子里，让我们举觞痛饮吧。\u003cb class=\"epub-calibre3\">（喇叭奏花腔。同下。）\u003c/b>\u003c/p>\n","text":"查理 赢得今天胜利的，不是我们，而是贞德。为了酬谢她的大功，我要和她共享这顶王冠。我要命令全国僧侣列队游行，歌颂她无穷的功德。我要为她兴建一座比孟菲斯更为庄严的金字塔。将来如果她一旦逝世，为了纪念她的遗徽，我们要用七宝香车，装殓她的骨殖，在盛大的仪仗中，运送到法兰西的先王、先后的陵寝中去安葬。以后我们就不用再向圣丹尼斯祈祷了，贞德圣女将成为法兰西的保护神。随我来吧，在这黄金般的胜利日子里，让我们举觞痛饮吧。（喇叭奏花腔。同下。）\n","sourceAnchor":null,"tag":"p"}],"heading":"第六场 同前","headingLevel":4,"sourceAnchor":"a465","actNumber":1,"sceneNumber":6},{"id":"part0022-section-008","label":"第二幕","kind":"act","blocks":[{"id":"part0022-00204","html":"\u003ch3 id=\"epub-part0022-a466\" class=\"epub-calibre11\">第二幕\u003c/h3>\n","text":"第二幕\n","sourceAnchor":"a466","tag":"h3"}],"heading":"第二幕","headingLevel":3,"sourceAnchor":"a466","actNumber":2},{"id":"part0022-section-009","label":"第二幕 · 第一场 法国。奥尔良城前","kind":"scene","blocks":[{"id":"part0022-00205","html":"\u003ch4 id=\"epub-part0022-a467\" class=\"epub-calibre12\">第一场 法国。奥尔良城前\u003c/h4>\n","text":"第一场 法国。奥尔良城前\n","sourceAnchor":"a467","tag":"h4"},{"id":"part0022-00206","html":"\u003cp class=\"epub-block1\">法军军曹及两哨兵同至城门口。\u003c/p>\n","text":"法军军曹及两哨兵同至城门口。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00207","html":"\u003cp class=\"epub-calibre1\">军 曹 弟兄们，站好岗位，小心提防着。如果你们听到城脚边有什么声响，或是看到敌兵，就马上用明白的信号，通知我们守卫室里的人。\u003c/p>\n","text":"军 曹 弟兄们，站好岗位，小心提防着。如果你们听到城脚边有什么声响，或是看到敌兵，就马上用明白的信号，通知我们守卫室里的人。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00208","html":"\u003cp class=\"epub-calibre1\">哨兵甲 队长，一定随时向您报告。\u003cb class=\"epub-calibre3\">（军曹下）\u003c/b>我们这些当杂差的活该倒楣，别人都在床上睡大觉，我们却不管风里雨里，得在黑地里站岗。\u003c/p>\n","text":"哨兵甲 队长，一定随时向您报告。（军曹下）我们这些当杂差的活该倒楣，别人都在床上睡大觉，我们却不管风里雨里，得在黑地里站岗。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00209","html":"\u003cp class=\"epub-block1\">塔尔博、培福、勃艮第率领众兵士上。他们带着云梯，低沉地敲着军鼓。\u003c/p>\n","text":"塔尔博、培福、勃艮第率领众兵士上。他们带着云梯，低沉地敲着军鼓。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00210","html":"\u003cp class=\"epub-calibre1\">塔尔博 总管大人，还有您，勇猛的勃艮第，仗托您的拉拢，阿陀亚、瓦隆和毕卡第这些地区都已和我们建立了友谊。今天法国人大吃大喝了一整天，他们今夜里正在放心大胆地睡觉，这是一个极好的机会，我们要趁此把他们依靠诡计和巫术给我们吃的亏，回敬给他们。\u003c/p>\n","text":"塔尔博 总管大人，还有您，勇猛的勃艮第，仗托您的拉拢，阿陀亚、瓦隆和毕卡第这些地区都已和我们建立了友谊。今天法国人大吃大喝了一整天，他们今夜里正在放心大胆地睡觉，这是一个极好的机会，我们要趁此把他们依靠诡计和巫术给我们吃的亏，回敬给他们。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00211","html":"\u003cp class=\"epub-calibre1\">培福 法兰西的懦夫哟！他对自己的武力已经丧失信心，只得结交巫婆，向地狱求救，这是多么不顾体面啊！\u003c/p>\n","text":"培福 法兰西的懦夫哟！他对自己的武力已经丧失信心，只得结交巫婆，向地狱求救，这是多么不顾体面啊！\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00212","html":"\u003cp class=\"epub-calibre1\">勃艮第 奸诈的人除了巫、鬼以外，还能有什么朋友？可是那个名叫贞德的，他们把她说得那样纯洁，到底是个怎样的角色？\u003c/p>\n","text":"勃艮第 奸诈的人除了巫、鬼以外，还能有什么朋友？可是那个名叫贞德的，他们把她说得那样纯洁，到底是个怎样的角色？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00213","html":"\u003cp class=\"epub-calibre1\">塔尔博 据他们说，她是一个姑娘。\u003c/p>\n","text":"塔尔博 据他们说，她是一个姑娘。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00214","html":"\u003cp class=\"epub-calibre1\">培福 一个姑娘！竟这般勇武！\u003c/p>\n","text":"培福 一个姑娘！竟这般勇武！\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00215","html":"\u003cp class=\"epub-calibre1\">勃艮第 上帝明鉴，如果她在法国人的旗帜下面当兵当下去，像她已经开始那样做的，她那雄赳赳的气概是不会长久保持的。\u003c/p>\n","text":"勃艮第 上帝明鉴，如果她在法国人的旗帜下面当兵当下去，像她已经开始那样做的，她那雄赳赳的气概是不会长久保持的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00216","html":"\u003cp class=\"epub-calibre1\">塔尔博 好吧，让他们扮神弄鬼好啦。上帝是我们的堡垒，凭着上帝的威名，让我们下定决心攀登那座石城。\u003c/p>\n","text":"塔尔博 好吧，让他们扮神弄鬼好啦。上帝是我们的堡垒，凭着上帝的威名，让我们下定决心攀登那座石城。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00217","html":"\u003cp class=\"epub-calibre1\">培福 爬上城去，勇敢的塔尔博，我们跟随你。\u003c/p>\n","text":"培福 爬上城去，勇敢的塔尔博，我们跟随你。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00218","html":"\u003cp class=\"epub-calibre1\">塔尔博 大家不要从一处上去，我想最好是分头进攻。万一一路失败，另一路还可以得手。\u003c/p>\n","text":"塔尔博 大家不要从一处上去，我想最好是分头进攻。万一一路失败，另一路还可以得手。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00219","html":"\u003cp class=\"epub-calibre1\">培福 就这么办。我去进攻那边一个城角。\u003c/p>\n","text":"培福 就这么办。我去进攻那边一个城角。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00220","html":"\u003cp class=\"epub-calibre1\">勃艮第 我担任这一边。\u003c/p>\n","text":"勃艮第 我担任这一边。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00221","html":"\u003cp class=\"epub-calibre1\">塔尔博 我塔尔博就在这里上城，上不去就葬在这里。嗨，萨立斯伯雷呀，为了你，也为了英王亨利的权利，今夜里我要表明我对你们两位是如何的忠心耿耿呵！\u003cb class=\"epub-calibre3\">（英军攀登城头，同时呐喊：“圣乔治！”“塔尔博主帅！”全部进入城内。）\u003c/b>\u003c/p>\n","text":"塔尔博 我塔尔博就在这里上城，上不去就葬在这里。嗨，萨立斯伯雷呀，为了你，也为了英王亨利的权利，今夜里我要表明我对你们两位是如何的忠心耿耿呵！（英军攀登城头，同时呐喊：“圣乔治！”“塔尔博主帅！”全部进入城内。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00222","html":"\u003cp class=\"epub-calibre1\">哨兵甲 快来呀！快来呀！敌人攻城啦！\u003c/p>\n","text":"哨兵甲 快来呀！快来呀！敌人攻城啦！\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00223","html":"\u003cp class=\"epub-block1\">穿内衣的法国兵士纷纷跳城。奥尔良庶子、阿朗松及瑞尼埃皆衣冠不整，分头上。\u003c/p>\n","text":"穿内衣的法国兵士纷纷跳城。奥尔良庶子、阿朗松及瑞尼埃皆衣冠不整，分头上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00224","html":"\u003cp class=\"epub-calibre1\">阿朗松 怎么啦，大人们！瞧，一个个的衣裳怎么都是这样七零八落的？\u003c/p>\n","text":"阿朗松 怎么啦，大人们！瞧，一个个的衣裳怎么都是这样七零八落的？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00225","html":"\u003cp class=\"epub-calibre1\">庶子 七零八落！哎，逃得性命就是万幸啦。\u003c/p>\n","text":"庶子 七零八落！哎，逃得性命就是万幸啦。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00226","html":"\u003cp class=\"epub-calibre1\">瑞尼埃 我听到房门口鼓角的声音，我想，那正该是醒过来起床的时候了。\u003c/p>\n","text":"瑞尼埃 我听到房门口鼓角的声音，我想，那正该是醒过来起床的时候了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00227","html":"\u003cp class=\"epub-calibre1\">阿朗松 自从我从军以来，也经历过不少风险，可我从来还没听见过，有像这一次仓皇应战的狼狈情形哩。\u003c/p>\n","text":"阿朗松 自从我从军以来，也经历过不少风险，可我从来还没听见过，有像这一次仓皇应战的狼狈情形哩。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00228","html":"\u003cp class=\"epub-calibre1\">庶子 我想这个塔尔博简直是从地狱出来的魔鬼。\u003c/p>\n","text":"庶子 我想这个塔尔博简直是从地狱出来的魔鬼。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00229","html":"\u003cp class=\"epub-calibre1\">瑞尼埃 如果他不是从地狱来的，那就一定是上天对他特别垂青。\u003c/p>\n","text":"瑞尼埃 如果他不是从地狱来的，那就一定是上天对他特别垂青。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00230","html":"\u003cp class=\"epub-calibre1\">阿朗松 查理来啦。我很奇怪他是怎样逃出来的。\u003c/p>\n","text":"阿朗松 查理来啦。我很奇怪他是怎样逃出来的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00231","html":"\u003cp class=\"epub-calibre1\">庶子 喏，有什么奇怪，他有贞德神女替他保镖呀！\u003c/p>\n","text":"庶子 喏，有什么奇怪，他有贞德神女替他保镖呀！\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00232","html":"\u003cp class=\"epub-block1\">查理及贞德上。\u003c/p>\n","text":"查理及贞德上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00233","html":"\u003cp class=\"epub-calibre1\">查理 这是你干的把戏吗，你这女骗子？你开头要哄我们，先让我们尝到一点儿甜头，然后再叫我们大吃苦头，这不就是你干的吗？\u003c/p>\n","text":"查理 这是你干的把戏吗，你这女骗子？你开头要哄我们，先让我们尝到一点儿甜头，然后再叫我们大吃苦头，这不就是你干的吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00234","html":"\u003cp class=\"epub-calibre1\">贞德 查理太子对待朋友怎么这样容易动火？您要叫我不分昼夜都把全副本领施展出来吗？难道叫我睡着也好，醒着也好，随时都得负责，否则您就对我大发脾气吗？你们这些粗心大意的兵丁们，若是你们守夜守得好，决不会有这场祸事。\u003c/p>\n","text":"贞德 查理太子对待朋友怎么这样容易动火？您要叫我不分昼夜都把全副本领施展出来吗？难道叫我睡着也好，醒着也好，随时都得负责，否则您就对我大发脾气吗？你们这些粗心大意的兵丁们，若是你们守夜守得好，决不会有这场祸事。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00235","html":"\u003cp class=\"epub-calibre1\">查理 阿朗松公爵，这就是你的不是了。今夜的守卫归你领班，你没把这份重担子担起来。\u003c/p>\n","text":"查理 阿朗松公爵，这就是你的不是了。今夜的守卫归你领班，你没把这份重担子担起来。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00236","html":"\u003cp class=\"epub-calibre1\">阿朗松 如果各处阵地都像我负责的那一段同样小心防守，我们就不会这样可耻地受到袭击。\u003c/p>\n","text":"阿朗松 如果各处阵地都像我负责的那一段同样小心防守，我们就不会这样可耻地受到袭击。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00237","html":"\u003cp class=\"epub-calibre1\">庶子 我的阵地是牢固的。\u003c/p>\n","text":"庶子 我的阵地是牢固的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00238","html":"\u003cp class=\"epub-calibre1\">瑞尼埃 我的阵地也没出毛病，殿下。\u003c/p>\n","text":"瑞尼埃 我的阵地也没出毛病，殿下。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00239","html":"\u003cp class=\"epub-calibre1\">查理 我自己呢，今夜里大部分时间我都在她的防区和我自己的防区，往来逡巡，监督着哨兵们换岗。这样说来，敌人是从哪一路、是怎样攻进来的呢？\u003c/p>\n","text":"查理 我自己呢，今夜里大部分时间我都在她的防区和我自己的防区，往来逡巡，监督着哨兵们换岗。这样说来，敌人是从哪一路、是怎样攻进来的呢？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00240","html":"\u003cp class=\"epub-calibre1\">贞德 大人们，我看不必再推敲这个问题了。不管他们是从哪儿来，是怎样来，反正敌人是找到了一处守卫力量薄弱的地方攻进来的。现在也没有其他办法，我们只得重新集合我们溃散了的兵丁，再定计策，重创敌人。\u003c/p>\n","text":"贞德 大人们，我看不必再推敲这个问题了。不管他们是从哪儿来，是怎样来，反正敌人是找到了一处守卫力量薄弱的地方攻进来的。现在也没有其他办法，我们只得重新集合我们溃散了的兵丁，再定计策，重创敌人。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00241","html":"\u003cp class=\"epub-block1\">鼓角声。一英国兵士上，口中叫喊：“塔尔博主帅！塔尔博！”法国太子等逃去，将衣服丢在地上。\u003c/p>\n","text":"鼓角声。一英国兵士上，口中叫喊：“塔尔博主帅！塔尔博！”法国太子等逃去，将衣服丢在地上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00242","html":"\u003cp class=\"epub-calibre1\">兵士 他们留下的这些东西，我就不客气地收下了。我喊了一声塔尔博，赛过使了一把钢刀。瞧，我只不过用他的名字当武器，其余的兵器啥也没有使，可我浑身就堆满了这么多的战利品啦。\u003cb class=\"epub-calibre3\">（下。）\u003c/b>\u003c/p>\n","text":"兵士 他们留下的这些东西，我就不客气地收下了。我喊了一声塔尔博，赛过使了一把钢刀。瞧，我只不过用他的名字当武器，其余的兵器啥也没有使，可我浑身就堆满了这么多的战利品啦。（下。）\n","sourceAnchor":null,"tag":"p"}],"heading":"第一场 法国。奥尔良城前","headingLevel":4,"sourceAnchor":"a467","actNumber":2,"sceneNumber":1},{"id":"part0022-section-010","label":"第二幕 · 第二场 同前。奥尔良城内","kind":"scene","blocks":[{"id":"part0022-00243","html":"\u003ch4 id=\"epub-part0022-a468\" class=\"epub-calibre12\">第二场 同前。奥尔良城内\u003c/h4>\n","text":"第二场 同前。奥尔良城内\n","sourceAnchor":"a468","tag":"h4"},{"id":"part0022-00244","html":"\u003cp class=\"epub-block1\">塔尔博、培福、勃艮第、一队长及余人上。\u003c/p>\n","text":"塔尔博、培福、勃艮第、一队长及余人上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00245","html":"\u003cp class=\"epub-calibre1\">培福 天将破晓了，用墨色大袍掩盖大地的黑夜即将离去了。\u003c/p>\n","text":"培福 天将破晓了，用墨色大袍掩盖大地的黑夜即将离去了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00246","html":"\u003cp class=\"epub-calibre1\">现在吹起收队的号音，停止我们的追击。\u003cb class=\"epub-calibre3\">（吹起收兵号。）\u003c/b>\u003c/p>\n","text":"现在吹起收队的号音，停止我们的追击。（吹起收兵号。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00247","html":"\u003cp class=\"epub-calibre1\">塔尔博 把萨立斯伯雷老将军的遗体抬过来，送到这个可恶的城的中心市场上去。我对他英魂立下的誓言，现在已经实践了。他流出的每一滴血，今夜里至少有五个法国人用性命抵偿了。我要在本城最大的一座庙宇里，替他建起坟墓，安葬他的尸体，使后代的人可以看到，为了替他报仇，我把这座城糟蹋成什么样子。在墓碑上，我要将他如何威镇法兰西，如何遭到暗算而惨死，以及我们攻克奥尔良的事实，全都铭记下来，让大家都能阅览。可是，大人们，在我们的血腥屠杀中，我们好像没有遇见法国太子本人，也未遇到他的新来的保驾人，那位贤良的贞德，也未遇到他那一群奸诈的党羽。\u003c/p>\n","text":"塔尔博 把萨立斯伯雷老将军的遗体抬过来，送到这个可恶的城的中心市场上去。我对他英魂立下的誓言，现在已经实践了。他流出的每一滴血，今夜里至少有五个法国人用性命抵偿了。我要在本城最大的一座庙宇里，替他建起坟墓，安葬他的尸体，使后代的人可以看到，为了替他报仇，我把这座城糟蹋成什么样子。在墓碑上，我要将他如何威镇法兰西，如何遭到暗算而惨死，以及我们攻克奥尔良的事实，全都铭记下来，让大家都能阅览。可是，大人们，在我们的血腥屠杀中，我们好像没有遇见法国太子本人，也未遇到他的新来的保驾人，那位贤良的贞德，也未遇到他那一群奸诈的党羽。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00248","html":"\u003cp class=\"epub-calibre1\">培福 塔尔博大人，这大概是在战斗开始的时候，他们从睡梦中陡然惊醒，就混在兵士中间，越城逃到野外去了。\u003c/p>\n","text":"培福 塔尔博大人，这大概是在战斗开始的时候，他们从睡梦中陡然惊醒，就混在兵士中间，越城逃到野外去了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00249","html":"\u003cp class=\"epub-calibre1\">勃艮第 我相信，如果在夜晚的烟雾中我没有看错的话，是我把那法国太子和他的那个姘妇惊动起来，他俩手搀手儿，飞快逃跑，好似一对恩爱鸳鸯一般，片刻不忍分离。等这里的事情安顿好了，我们再尽力去追赶他们。\u003c/p>\n","text":"勃艮第 我相信，如果在夜晚的烟雾中我没有看错的话，是我把那法国太子和他的那个姘妇惊动起来，他俩手搀手儿，飞快逃跑，好似一对恩爱鸳鸯一般，片刻不忍分离。等这里的事情安顿好了，我们再尽力去追赶他们。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00250","html":"\u003cp class=\"epub-block1\">一使者上。\u003c/p>\n","text":"一使者上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00251","html":"\u003cp class=\"epub-calibre1\">使者 敬礼，大人们！在列位贵人中间，哪一位是塔尔博将军？这位将军的事迹，在法兰西国土上，到处受到赞扬。\u003c/p>\n","text":"使者 敬礼，大人们！在列位贵人中间，哪一位是塔尔博将军？这位将军的事迹，在法兰西国土上，到处受到赞扬。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00252","html":"\u003cp class=\"epub-calibre1\">塔尔博 我就是塔尔博，谁要跟我说话？\u003c/p>\n","text":"塔尔博 我就是塔尔博，谁要跟我说话？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00253","html":"\u003cp class=\"epub-calibre1\">使者 一位贤德的夫人，奥凡涅伯爵夫人，久仰您的盛名，特地差我来请您，伟大的将军，慨允光临她的府邸，使她能以瞻仰威震遐迩的伟人的丰采为荣。\u003c/p>\n","text":"使者 一位贤德的夫人，奥凡涅伯爵夫人，久仰您的盛名，特地差我来请您，伟大的将军，慨允光临她的府邸，使她能以瞻仰威震遐迩的伟人的丰采为荣。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00254","html":"\u003cp class=\"epub-calibre1\">勃艮第 居然有这样的事？好啦，我看咱们的战争快要变成和平的玩意儿啦，连夫人太太们也要求和将军会见啦。我的将军，您可不能过拂人家的好意呀！\u003c/p>\n","text":"勃艮第 居然有这样的事？好啦，我看咱们的战争快要变成和平的玩意儿啦，连夫人太太们也要求和将军会见啦。我的将军，您可不能过拂人家的好意呀！\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00255","html":"\u003cp class=\"epub-calibre1\">塔尔博 我怎能那样不近情理？在男人们中间不能用辞令来说服的时候，女人一表示好意，就会占到上风。请你向她转达我的谢意，我一定登门拜访。列位大人，可否劳驾和我同去？\u003c/p>\n","text":"塔尔博 我怎能那样不近情理？在男人们中间不能用辞令来说服的时候，女人一表示好意，就会占到上风。请你向她转达我的谢意，我一定登门拜访。列位大人，可否劳驾和我同去？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00256","html":"\u003cp class=\"epub-calibre1\">培福 恕我不能奉陪，因为那是不合乎礼节的。我常听人说，不速之客只在告辞以后才最受欢迎。\u003c/p>\n","text":"培福 恕我不能奉陪，因为那是不合乎礼节的。我常听人说，不速之客只在告辞以后才最受欢迎。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00257","html":"\u003cp class=\"epub-calibre1\">塔尔博 那么，没有办法，我只好独自前往，去领受这位夫人的盛情了。队长，你过来。\u003cb class=\"epub-calibre3\">（耳语）\u003c/b>你懂得我的意思吗？\u003c/p>\n","text":"塔尔博 那么，没有办法，我只好独自前往，去领受这位夫人的盛情了。队长，你过来。（耳语）你懂得我的意思吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00258","html":"\u003cp class=\"epub-calibre1\">队长 我懂得的，大人，一定遵命办理。\u003cb class=\"epub-calibre3\">（同下。）\u003c/b>\u003c/p>\n","text":"队长 我懂得的，大人，一定遵命办理。（同下。）\n","sourceAnchor":null,"tag":"p"}],"heading":"第二场 同前。奥尔良城内","headingLevel":4,"sourceAnchor":"a468","actNumber":2,"sceneNumber":2},{"id":"part0022-section-011","label":"第二幕 · 第三场 奥凡涅。伯爵夫人邸宅","kind":"scene","blocks":[{"id":"part0022-00259","html":"\u003ch4 id=\"epub-part0022-a469\" class=\"epub-calibre12\">第三场 奥凡涅。伯爵夫人邸宅\u003c/h4>\n","text":"第三场 奥凡涅。伯爵夫人邸宅\n","sourceAnchor":"a469","tag":"h4"},{"id":"part0022-00260","html":"\u003cp class=\"epub-block1\">伯爵夫人及看门人上。\u003c/p>\n","text":"伯爵夫人及看门人上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00261","html":"\u003cp class=\"epub-calibre1\">伯爵夫人 看门的，记着我交代给你的任务，等你办妥以后，把钥匙交来给我。\u003c/p>\n","text":"伯爵夫人 看门的，记着我交代给你的任务，等你办妥以后，把钥匙交来给我。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00262","html":"\u003cp class=\"epub-calibre1\">看门人 夫人，遵命。\u003cb class=\"epub-calibre3\">（下。）\u003c/b>\u003c/p>\n","text":"看门人 夫人，遵命。（下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00263","html":"\u003cp class=\"epub-calibre1\">伯爵夫人 计策已经安排好了。如果一切进行顺利，我就能和弄死居鲁士的唐米莉的声名媲美了\u003ca id=\"epub-part0022-w008\">\u003c/a>\u003ca href=\"#epub-part0022-m008\" data-source-anchor=\"m008\">\u003csup class=\"epub-calibre13\">[8]\u003c/sup>\u003c/a>。外边都传说这个将军厉害得很，说他干了不少惊天动地的事情。耳闻不如目见，我要把这些传说亲自证实一下。\u003c/p>\n","text":"伯爵夫人 计策已经安排好了。如果一切进行顺利，我就能和弄死居鲁士的唐米莉的声名媲美了[8]。外边都传说这个将军厉害得很，说他干了不少惊天动地的事情。耳闻不如目见，我要把这些传说亲自证实一下。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00264","html":"\u003cp class=\"epub-block1\">使者及塔尔博上。\u003c/p>\n","text":"使者及塔尔博上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00265","html":"\u003cp class=\"epub-calibre1\">使者 夫人，您所邀请并希望见到的塔尔博将军来到了。\u003c/p>\n","text":"使者 夫人，您所邀请并希望见到的塔尔博将军来到了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00266","html":"\u003cp class=\"epub-calibre1\">伯爵夫人 欢迎他到来。怎么！这就是他吗？\u003c/p>\n","text":"伯爵夫人 欢迎他到来。怎么！这就是他吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00267","html":"\u003cp class=\"epub-calibre1\">使者 夫人，这位就是他。\u003c/p>\n","text":"使者 夫人，这位就是他。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00268","html":"\u003cp class=\"epub-calibre1\">伯爵夫人 人称作法兰西的丧门神的就是这人吗？这个人就是人人提到都害怕、母亲们用他的名字来制止孩子啼哭的那个塔尔博吗？我看外面的传说是言过其实了。我原指望他是一个顶天立地、魁梧奇伟的汉子，这个人却是一个小娃儿，一个貌不惊人的侏儒！要说这样一个软弱无力、缩头缩脑的矮人儿，能叫敌人望而生畏，才没人信呢。\u003c/p>\n","text":"伯爵夫人 人称作法兰西的丧门神的就是这人吗？这个人就是人人提到都害怕、母亲们用他的名字来制止孩子啼哭的那个塔尔博吗？我看外面的传说是言过其实了。我原指望他是一个顶天立地、魁梧奇伟的汉子，这个人却是一个小娃儿，一个貌不惊人的侏儒！要说这样一个软弱无力、缩头缩脑的矮人儿，能叫敌人望而生畏，才没人信呢。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00269","html":"\u003cp class=\"epub-calibre1\">塔尔博 夫人，我斗胆前来拜访，是过于唐突了。今天夫人既然无暇，我就改日再来吧。\u003c/p>\n","text":"塔尔博 夫人，我斗胆前来拜访，是过于唐突了。今天夫人既然无暇，我就改日再来吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00270","html":"\u003cp class=\"epub-calibre1\">伯爵夫人 他说些什么？你去问他要到哪儿去。\u003c/p>\n","text":"伯爵夫人 他说些什么？你去问他要到哪儿去。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00271","html":"\u003cp class=\"epub-calibre1\">使者 请暂停一下，塔尔博将军，我们的夫人要想知道您为什么突然告辞。\u003c/p>\n","text":"使者 请暂停一下，塔尔博将军，我们的夫人要想知道您为什么突然告辞。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00272","html":"\u003cp class=\"epub-calibre1\">塔尔博 哎，你们的夫人既然不肯见信，我要向她证明一下塔尔博的确是在这里。\u003c/p>\n","text":"塔尔博 哎，你们的夫人既然不肯见信，我要向她证明一下塔尔博的确是在这里。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00273","html":"\u003cp class=\"epub-block1\">看门人持钥匙重上。\u003c/p>\n","text":"看门人持钥匙重上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00274","html":"\u003cp class=\"epub-calibre1\">伯爵夫人 你既然就是他，那么你已经成为俘虏了。\u003c/p>\n","text":"伯爵夫人 你既然就是他，那么你已经成为俘虏了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00275","html":"\u003cp class=\"epub-calibre1\">塔尔博 成为俘虏？成为谁的俘虏？\u003c/p>\n","text":"塔尔博 成为俘虏？成为谁的俘虏？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00276","html":"\u003cp class=\"epub-calibre1\">伯爵夫人 成为我的俘虏了，好杀成性的爵爷，正是为了这个目的，我才把你诓到这儿来的。你的影子早就是我的奴隶，因为你的画像早就挂在我的画廊里，可是现在你的身子也将遭到同样的待遇。这许多年来，你残暴地蹂躏我们的国土，杀戮我们的人民，奴役我们的儿子和丈夫，我现在要把你的手脚用链索捆绑起来。\u003c/p>\n","text":"伯爵夫人 成为我的俘虏了，好杀成性的爵爷，正是为了这个目的，我才把你诓到这儿来的。你的影子早就是我的奴隶，因为你的画像早就挂在我的画廊里，可是现在你的身子也将遭到同样的待遇。这许多年来，你残暴地蹂躏我们的国土，杀戮我们的人民，奴役我们的儿子和丈夫，我现在要把你的手脚用链索捆绑起来。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00277","html":"\u003cp class=\"epub-calibre1\">塔尔博 哈，哈，哈！\u003c/p>\n","text":"塔尔博 哈，哈，哈！\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00278","html":"\u003cp class=\"epub-calibre1\">伯爵夫人 你还笑吗，倒楣鬼？只怕你笑不成还要哭呢。\u003c/p>\n","text":"伯爵夫人 你还笑吗，倒楣鬼？只怕你笑不成还要哭呢。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00279","html":"\u003cp class=\"epub-calibre1\">塔尔博 我看夫人满以为除了塔尔博的影子以外，还可以把您的威严用到什么别的东西上，不由得我要笑起来。\u003c/p>\n","text":"塔尔博 我看夫人满以为除了塔尔博的影子以外，还可以把您的威严用到什么别的东西上，不由得我要笑起来。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00280","html":"\u003cp class=\"epub-calibre1\">伯爵夫人 怎么，难道你不是塔尔博吗？\u003c/p>\n","text":"伯爵夫人 怎么，难道你不是塔尔博吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00281","html":"\u003cp class=\"epub-calibre1\">塔尔博 我的确是他。\u003c/p>\n","text":"塔尔博 我的确是他。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00282","html":"\u003cp class=\"epub-calibre1\">伯爵夫人 那么你的身子也在我掌握之中了。\u003c/p>\n","text":"伯爵夫人 那么你的身子也在我掌握之中了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00283","html":"\u003cp class=\"epub-calibre1\">塔尔博 这却不然，其实我也不过是我自己的影子罢了。您是上了当了，我的身子并不在这里。您所看到的只不过是我这人的极小的一个部分，一个最不重要的部分。容我告诉您，夫人，如果我全身在此的话，那是太高、太大了，只怕您的府第是装不下它的。\u003c/p>\n","text":"塔尔博 这却不然，其实我也不过是我自己的影子罢了。您是上了当了，我的身子并不在这里。您所看到的只不过是我这人的极小的一个部分，一个最不重要的部分。容我告诉您，夫人，如果我全身在此的话，那是太高、太大了，只怕您的府第是装不下它的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00284","html":"\u003cp class=\"epub-calibre1\">伯爵夫人 这人真会打哑谜，叫人猜不透。他是在这里，可他又不在这里，这个矛盾怎样才能解决？\u003c/p>\n","text":"伯爵夫人 这人真会打哑谜，叫人猜不透。他是在这里，可他又不在这里，这个矛盾怎样才能解决？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00285","html":"\u003cp class=\"epub-calibre1\">塔尔博 我马上就可替您解决。\u003cb class=\"epub-calibre3\">（塔尔博取出喇叭吹奏。）\u003c/b>\u003c/p>\n","text":"塔尔博 我马上就可替您解决。（塔尔博取出喇叭吹奏。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00286","html":"\u003cp class=\"epub-block1\">内擂鼓、鸣炮。众兵破门而入。\u003c/p>\n","text":"内擂鼓、鸣炮。众兵破门而入。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00287","html":"\u003cp class=\"epub-calibre1\">塔尔博 您以为如何，夫人？我说塔尔博不过是他自己的影子，您现在信了吗？这些人才是他的身子，才是他的筋腱、他的胳膊、他的膂力。他用这个身子拴住你们企图反抗的颈项，铲平你们的城池，毁灭你们的郡邑，把它们在俄顷之间变成一片荒原。\u003c/p>\n","text":"塔尔博 您以为如何，夫人？我说塔尔博不过是他自己的影子，您现在信了吗？这些人才是他的身子，才是他的筋腱、他的胳膊、他的膂力。他用这个身子拴住你们企图反抗的颈项，铲平你们的城池，毁灭你们的郡邑，把它们在俄顷之间变成一片荒原。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00288","html":"\u003cp class=\"epub-calibre1\">伯爵夫人 胜利的塔尔博将军！刚才冒犯虎威，请你宽恕了吧。我现在已经明白，你确是名不虚传，不能只凭外貌来估量你。我多有得罪的地方，务必请你原谅。我没有用应有的礼貌接待你，实在万分抱歉。\u003c/p>\n","text":"伯爵夫人 胜利的塔尔博将军！刚才冒犯虎威，请你宽恕了吧。我现在已经明白，你确是名不虚传，不能只凭外貌来估量你。我多有得罪的地方，务必请你原谅。我没有用应有的礼貌接待你，实在万分抱歉。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00289","html":"\u003cp class=\"epub-calibre1\">塔尔博 美貌的夫人，您不用担忧。刚才您看错了塔尔博的外貌，请您不要再误会他的内心吧。您刚才的举动，我并不见怪。我对您也没有其他的要求，我只请求您，如蒙慨允的话，拿出您的佳肴美酒，让我们尝一尝，因为军人的胃口对于这些东西，总是来者不拒的。\u003c/p>\n","text":"塔尔博 美貌的夫人，您不用担忧。刚才您看错了塔尔博的外貌，请您不要再误会他的内心吧。您刚才的举动，我并不见怪。我对您也没有其他的要求，我只请求您，如蒙慨允的话，拿出您的佳肴美酒，让我们尝一尝，因为军人的胃口对于这些东西，总是来者不拒的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00290","html":"\u003cp class=\"epub-calibre1\">伯爵夫人 我竭诚欢迎。我能在寒舍款待您这位伟大的将军，实是不胜荣幸。\u003cb class=\"epub-calibre3\">（同下。）\u003c/b>\u003c/p>\n","text":"伯爵夫人 我竭诚欢迎。我能在寒舍款待您这位伟大的将军，实是不胜荣幸。（同下。）\n","sourceAnchor":null,"tag":"p"}],"heading":"第三场 奥凡涅。伯爵夫人邸宅","headingLevel":4,"sourceAnchor":"a469","actNumber":2,"sceneNumber":3},{"id":"part0022-section-012","label":"第二幕 · 第四场 伦敦。国会花园","kind":"scene","blocks":[{"id":"part0022-00291","html":"\u003ch4 id=\"epub-part0022-a470\" class=\"epub-calibre12\">第四场 伦敦。国会花园\u003c/h4>\n","text":"第四场 伦敦。国会花园\n","sourceAnchor":"a470","tag":"h4"},{"id":"part0022-00292","html":"\u003cp class=\"epub-block1\">萨穆塞特、萨福克、华列克、理查·普兰塔琪纳特、凡农及一律师上。\u003c/p>\n","text":"萨穆塞特、萨福克、华列克、理查·普兰塔琪纳特、凡农及一律师上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00293","html":"\u003cp class=\"epub-calibre1\">普兰塔琪纳特 列位大人，诸位先生，大家怎么都不开口呀？难道没有人敢说一句公道话吗？\u003c/p>\n","text":"普兰塔琪纳特 列位大人，诸位先生，大家怎么都不开口呀？难道没有人敢说一句公道话吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00294","html":"\u003cp class=\"epub-calibre1\">萨福克 在议会大厅里我们争得太厉害了，在这里谈谈更方便些。\u003c/p>\n","text":"萨福克 在议会大厅里我们争得太厉害了，在这里谈谈更方便些。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00295","html":"\u003cp class=\"epub-calibre1\">普兰塔琪纳特 那么就请干脆说一句，我是不是站在真理的一边，或者说这个争论不休的萨穆塞特是不是错了。\u003c/p>\n","text":"普兰塔琪纳特 那么就请干脆说一句，我是不是站在真理的一边，或者说这个争论不休的萨穆塞特是不是错了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00296","html":"\u003cp class=\"epub-calibre1\">萨福克 说实话，我对于法律问题实在外行，我从来不能叫我的意志受法律支配，我宁可叫法律顺从我的意志。\u003c/p>\n","text":"萨福克 说实话，我对于法律问题实在外行，我从来不能叫我的意志受法律支配，我宁可叫法律顺从我的意志。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00297","html":"\u003cp class=\"epub-calibre1\">萨穆塞特 那么就请您，华列克爵爷，替我们判断一下吧。\u003c/p>\n","text":"萨穆塞特 那么就请您，华列克爵爷，替我们判断一下吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00298","html":"\u003cp class=\"epub-calibre1\">华列克 要叫我判断两只鹰，哪一只飞得更高；判断两条狗，哪一条吠得更响；判断两柄剑，哪一柄更锋利；判断两匹马，哪一匹跑得更稳；判断两个姑娘，哪一个的眼睛更媚人；我倒是略知一二；可是关于法律上的细致精微的论点，说老实话，我并不比一个傻子懂的更多。\u003c/p>\n","text":"华列克 要叫我判断两只鹰，哪一只飞得更高；判断两条狗，哪一条吠得更响；判断两柄剑，哪一柄更锋利；判断两匹马，哪一匹跑得更稳；判断两个姑娘，哪一个的眼睛更媚人；我倒是略知一二；可是关于法律上的细致精微的论点，说老实话，我并不比一个傻子懂的更多。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00299","html":"\u003cp class=\"epub-calibre1\">普兰塔琪纳特 嗳哟哟，这都是些虚文客套，推托之词。真理明明是属于我这方面，瞎子也能看得出的。\u003c/p>\n","text":"普兰塔琪纳特 嗳哟哟，这都是些虚文客套，推托之词。真理明明是属于我这方面，瞎子也能看得出的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00300","html":"\u003cp class=\"epub-calibre1\">萨穆塞特 在我这方面，真理是如此鲜明，如此明白，如此明亮，如此明显，即便映到盲人的眼里，也会发光。\u003c/p>\n","text":"萨穆塞特 在我这方面，真理是如此鲜明，如此明白，如此明亮，如此明显，即便映到盲人的眼里，也会发光。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00301","html":"\u003cp class=\"epub-calibre1\">普兰塔琪纳特 既然诸位都是守口如瓶，不愿说话，就请用一种无言的符号，表达你们的意见吧。谁要是一个出身高贵的上等人，愿意维持他门第的尊严，如果他认为我的主张是合乎真理的，就请他从这花丛里替我摘下一朵白色的玫瑰花。\u003c/p>\n","text":"普兰塔琪纳特 既然诸位都是守口如瓶，不愿说话，就请用一种无言的符号，表达你们的意见吧。谁要是一个出身高贵的上等人，愿意维持他门第的尊严，如果他认为我的主张是合乎真理的，就请他从这花丛里替我摘下一朵白色的玫瑰花。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00302","html":"\u003cp class=\"epub-calibre1\">萨穆塞特 谁要不是一个懦夫，不是一个阿谀奉承的人，而是敢于坚持真理的，就请他替我摘下一朵红色的玫瑰花。\u003c/p>\n","text":"萨穆塞特 谁要不是一个懦夫，不是一个阿谀奉承的人，而是敢于坚持真理的，就请他替我摘下一朵红色的玫瑰花。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00303","html":"\u003cp class=\"epub-calibre1\">华列克 我不喜欢五颜六色的东西，我也不愿沾上阿谀奉承的色彩，我替普兰塔琪纳特摘下这朵白玫瑰。\u003c/p>\n","text":"华列克 我不喜欢五颜六色的东西，我也不愿沾上阿谀奉承的色彩，我替普兰塔琪纳特摘下这朵白玫瑰。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00304","html":"\u003cp class=\"epub-calibre1\">萨福克 我替年轻的萨穆塞特摘下这朵红玫瑰，我还要说一句，我认为他所持的理由是正确的。\u003c/p>\n","text":"萨福克 我替年轻的萨穆塞特摘下这朵红玫瑰，我还要说一句，我认为他所持的理由是正确的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00305","html":"\u003cp class=\"epub-calibre1\">凡农 请停一停，大人们，先生们，暂时不要摘了，让我们先取得一致的意见，得到较少的玫瑰花的一方应该向另一方服输。\u003c/p>\n","text":"凡农 请停一停，大人们，先生们，暂时不要摘了，让我们先取得一致的意见，得到较少的玫瑰花的一方应该向另一方服输。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00306","html":"\u003cp class=\"epub-calibre1\">萨穆塞特 凡农，我的好先生，这主意提得很好。如果我得的花少，我就认输。\u003c/p>\n","text":"萨穆塞特 凡农，我的好先生，这主意提得很好。如果我得的花少，我就认输。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00307","html":"\u003cp class=\"epub-calibre1\">普兰塔琪纳特 我也如此。\u003c/p>\n","text":"普兰塔琪纳特 我也如此。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00308","html":"\u003cp class=\"epub-calibre1\">凡农 那么，为了表明本案中的真理显然属于何方，我摘下这朵无色的处女花，我的判决是站在白玫瑰方面的。\u003c/p>\n","text":"凡农 那么，为了表明本案中的真理显然属于何方，我摘下这朵无色的处女花，我的判决是站在白玫瑰方面的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00309","html":"\u003cp class=\"epub-calibre1\">萨穆塞特 你采花的时候要当心，不要让花刺戳了你的手，否则你的血把白花染红了，你就不由自主地站到我这一边来了。\u003c/p>\n","text":"萨穆塞特 你采花的时候要当心，不要让花刺戳了你的手，否则你的血把白花染红了，你就不由自主地站到我这一边来了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00310","html":"\u003cp class=\"epub-calibre1\">凡农 我的大人，如果我为了坚持我的主张而流血，我的主张能像医生一样，治好我的创伤，使我仍然站在原先的一边。\u003c/p>\n","text":"凡农 我的大人，如果我为了坚持我的主张而流血，我的主张能像医生一样，治好我的创伤，使我仍然站在原先的一边。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00311","html":"\u003cp class=\"epub-calibre1\">萨穆塞特 行，行，来吧，谁再来摘？\u003c/p>\n","text":"萨穆塞特 行，行，来吧，谁再来摘？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00312","html":"\u003cp class=\"epub-calibre1\">律师 \u003cb class=\"epub-calibre3\">（向萨穆塞特）\u003c/b>除非我的法律知识没有学到家，您所举的理由是错误的。为了表示我的看法，我也摘下一朵白玫瑰。\u003c/p>\n","text":"律师 （向萨穆塞特）除非我的法律知识没有学到家，您所举的理由是错误的。为了表示我的看法，我也摘下一朵白玫瑰。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00313","html":"\u003cp class=\"epub-calibre1\">普兰塔琪纳特 瞧，萨穆塞特，哪儿还有你的论点？\u003c/p>\n","text":"普兰塔琪纳特 瞧，萨穆塞特，哪儿还有你的论点？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00314","html":"\u003cp class=\"epub-calibre1\">萨穆塞特 我的论点藏在我的刀鞘里，它打算把你的白玫瑰染成血一般红。\u003c/p>\n","text":"萨穆塞特 我的论点藏在我的刀鞘里，它打算把你的白玫瑰染成血一般红。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00315","html":"\u003cp class=\"epub-calibre1\">普兰塔琪纳特 可是你的腮帮子也比得上我们的白玫瑰花了，大概是看到真理属于我这一边，吓得发白了吧。\u003c/p>\n","text":"普兰塔琪纳特 可是你的腮帮子也比得上我们的白玫瑰花了，大概是看到真理属于我这一边，吓得发白了吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00316","html":"\u003cp class=\"epub-calibre1\">萨穆塞特 不对，普兰塔琪纳特，不是吓得发白，是怒得发白，你的腮帮子羞得发红，也比得上我们的玫瑰花，可是你的舌头还不肯承认你的错误。\u003c/p>\n","text":"萨穆塞特 不对，普兰塔琪纳特，不是吓得发白，是怒得发白，你的腮帮子羞得发红，也比得上我们的玫瑰花，可是你的舌头还不肯承认你的错误。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00317","html":"\u003cp class=\"epub-calibre1\">普兰塔琪纳特 萨穆塞特，你的玫瑰树上不是生着烂皮疮吗？\u003c/p>\n","text":"普兰塔琪纳特 萨穆塞特，你的玫瑰树上不是生着烂皮疮吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00318","html":"\u003cp class=\"epub-calibre1\">萨穆塞特 普兰塔琪纳特，你的玫瑰树上不是长着刺吗？\u003c/p>\n","text":"萨穆塞特 普兰塔琪纳特，你的玫瑰树上不是长着刺吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00319","html":"\u003cp class=\"epub-calibre1\">普兰塔琪纳特 是呀，又尖又利的刺，为了更能维护真理；你的烂皮疮却把你的虚伪烂出来了。\u003c/p>\n","text":"普兰塔琪纳特 是呀，又尖又利的刺，为了更能维护真理；你的烂皮疮却把你的虚伪烂出来了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00320","html":"\u003cp class=\"epub-calibre1\">萨穆塞特 哼，我总有朋友替我佩戴这血红的玫瑰花，他们要在虚伪的普兰塔琪纳特不敢露面的地方，为我证明我说的全是事实。\u003c/p>\n","text":"萨穆塞特 哼，我总有朋友替我佩戴这血红的玫瑰花，他们要在虚伪的普兰塔琪纳特不敢露面的地方，为我证明我说的全是事实。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00321","html":"\u003cp class=\"epub-calibre1\">普兰塔琪纳特 不讲理的孩子，我用我手里的这朵处女花表示我对你和你的党羽的鄙视。\u003c/p>\n","text":"普兰塔琪纳特 不讲理的孩子，我用我手里的这朵处女花表示我对你和你的党羽的鄙视。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00322","html":"\u003cp class=\"epub-calibre1\">萨福克 不要把鄙视的话牵涉到我，普兰塔琪纳特。\u003c/p>\n","text":"萨福克 不要把鄙视的话牵涉到我，普兰塔琪纳特。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00323","html":"\u003cp class=\"epub-calibre1\">普兰塔琪纳特 骄傲的波勒\u003ca id=\"epub-part0022-w009\">\u003c/a>\u003ca href=\"#epub-part0022-m009\" data-source-anchor=\"m009\">\u003csup class=\"epub-calibre13\">[9]\u003c/sup>\u003c/a>，我偏要；我鄙视他，也鄙视你。\u003c/p>\n","text":"普兰塔琪纳特 骄傲的波勒[9]，我偏要；我鄙视他，也鄙视你。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00324","html":"\u003cp class=\"epub-calibre1\">萨福克 我要把你鄙视我的话塞回你的咽喉里去。\u003c/p>\n","text":"萨福克 我要把你鄙视我的话塞回你的咽喉里去。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00325","html":"\u003cp class=\"epub-calibre1\">萨穆塞特 走吧，走吧，我的好威廉·德·拉·波勒！我们跟平民说话，反而是抬高他的身价了。\u003c/p>\n","text":"萨穆塞特 走吧，走吧，我的好威廉·德·拉·波勒！我们跟平民说话，反而是抬高他的身价了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00326","html":"\u003cp class=\"epub-calibre1\">华列克 唔，凭上帝的旨意，你委屈了他了，萨穆塞特。他是英王爱德华三世陛下的第三子，克莱伦斯公爵的曾孙，他是有根有源的人，怎能说他是个没有身份的平民？\u003c/p>\n","text":"华列克 唔，凭上帝的旨意，你委屈了他了，萨穆塞特。他是英王爱德华三世陛下的第三子，克莱伦斯公爵的曾孙，他是有根有源的人，怎能说他是个没有身份的平民？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00327","html":"\u003cp class=\"epub-calibre1\">普兰塔琪纳特 他是沾着这个地方的光，否则像他那么个胆小鬼，是不敢说这话的。\u003c/p>\n","text":"普兰塔琪纳特 他是沾着这个地方的光，否则像他那么个胆小鬼，是不敢说这话的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00328","html":"\u003cp class=\"epub-calibre1\">萨穆塞特 凭着造物主，我在基督教国度里的任何地方，我都坚持我所说过的话。你能说老王在世的时候，你父亲剑桥伯爵不是犯了叛逆大罪，被执行死刑的吗？你父亲既是个叛逆，你不就是一个有罪的、堕落的、从古老的世家门第开除出来的人吗？他的罪恶还存留在你的血里。除非让你复袭世职，你就只是一个平民。\u003c/p>\n","text":"萨穆塞特 凭着造物主，我在基督教国度里的任何地方，我都坚持我所说过的话。你能说老王在世的时候，你父亲剑桥伯爵不是犯了叛逆大罪，被执行死刑的吗？你父亲既是个叛逆，你不就是一个有罪的、堕落的、从古老的世家门第开除出来的人吗？他的罪恶还存留在你的血里。除非让你复袭世职，你就只是一个平民。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00329","html":"\u003cp class=\"epub-calibre1\">普兰塔琪纳特 我父亲是被逮捕的，但并未证实他的罪名，他是被控为叛逆而判处死刑的，但他绝不是叛徒。等到形势好转，我更能称心如意的时候，我要把当年的事实向那些比萨穆塞特更有价值的人们详细说明。至于你的党羽波勒和你本人，你们这样诬蔑我父子，我定把你们记在心里，以后是要对付你们的。你们要小心些，不要说我没有预先给你警告。\u003c/p>\n","text":"普兰塔琪纳特 我父亲是被逮捕的，但并未证实他的罪名，他是被控为叛逆而判处死刑的，但他绝不是叛徒。等到形势好转，我更能称心如意的时候，我要把当年的事实向那些比萨穆塞特更有价值的人们详细说明。至于你的党羽波勒和你本人，你们这样诬蔑我父子，我定把你们记在心里，以后是要对付你们的。你们要小心些，不要说我没有预先给你警告。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00330","html":"\u003cp class=\"epub-calibre1\">萨穆塞特 嗯，我们会准备好等着你来的。我的朋友们为了反对你，都将佩戴着红玫瑰，所以你不难认出你的敌人。\u003c/p>\n","text":"萨穆塞特 嗯，我们会准备好等着你来的。我的朋友们为了反对你，都将佩戴着红玫瑰，所以你不难认出你的敌人。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00331","html":"\u003cp class=\"epub-calibre1\">普兰塔琪纳特 我凭我的灵魂起誓，我要和我的同道们永远佩戴这无色的、含怒的玫瑰，作为我的血海深仇的标记。如果我不幸死亡，它就和我一同枯萎；如果我的官阶步步高升，它就和我一同茂盛。\u003c/p>\n","text":"普兰塔琪纳特 我凭我的灵魂起誓，我要和我的同道们永远佩戴这无色的、含怒的玫瑰，作为我的血海深仇的标记。如果我不幸死亡，它就和我一同枯萎；如果我的官阶步步高升，它就和我一同茂盛。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00332","html":"\u003cp class=\"epub-calibre1\">萨福克 随你的便吧，小心别给你自己的野心噎死了！现在就此告别，我们后会有期。\u003cb class=\"epub-calibre3\">（下。）\u003c/b>\u003c/p>\n","text":"萨福克 随你的便吧，小心别给你自己的野心噎死了！现在就此告别，我们后会有期。（下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00333","html":"\u003cp class=\"epub-calibre1\">萨穆塞特 波勒，我和你同走。再见，野心的理查。\u003cb class=\"epub-calibre3\">（下。）\u003c/b>\u003c/p>\n","text":"萨穆塞特 波勒，我和你同走。再见，野心的理查。（下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00334","html":"\u003cp class=\"epub-calibre1\">普兰塔琪纳特 他们这样糟蹋我，而我还只能忍受！\u003c/p>\n","text":"普兰塔琪纳特 他们这样糟蹋我，而我还只能忍受！\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00335","html":"\u003cp class=\"epub-calibre1\">华列克 他们指摘你的关于家世的污点，到下届议会开会为温彻斯特和葛罗斯特进行调解的时候，就能替你洗刷干净。到那时，如果你还得不到约克公爵的封号，我就连我这华列克的爵位也不要了。为了表示我对你的爱护，也表示我对骄傲的萨穆塞特和威廉·波勒的敌意，我要佩戴你们一党的白玫瑰。我说一句预言在这里：今天在这议会花园里由争论而分裂成为红、白玫瑰的两派，不久将会使成千的人丢掉性命。\u003c/p>\n","text":"华列克 他们指摘你的关于家世的污点，到下届议会开会为温彻斯特和葛罗斯特进行调解的时候，就能替你洗刷干净。到那时，如果你还得不到约克公爵的封号，我就连我这华列克的爵位也不要了。为了表示我对你的爱护，也表示我对骄傲的萨穆塞特和威廉·波勒的敌意，我要佩戴你们一党的白玫瑰。我说一句预言在这里：今天在这议会花园里由争论而分裂成为红、白玫瑰的两派，不久将会使成千的人丢掉性命。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00336","html":"\u003cp class=\"epub-calibre1\">普兰塔琪纳特 凡农我的好先生，您赞助我，摘了一朵白玫瑰，我非常感激。\u003c/p>\n","text":"普兰塔琪纳特 凡农我的好先生，您赞助我，摘了一朵白玫瑰，我非常感激。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00337","html":"\u003cp class=\"epub-calibre1\">凡农 为了赞助您，我还要把白玫瑰佩戴在身上。\u003c/p>\n","text":"凡农 为了赞助您，我还要把白玫瑰佩戴在身上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00338","html":"\u003cp class=\"epub-calibre1\">律师 我也佩戴白玫瑰。\u003c/p>\n","text":"律师 我也佩戴白玫瑰。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00339","html":"\u003cp class=\"epub-calibre1\">普兰塔琪纳特 谢谢您，我的好先生。来吧，今天由我做东，我们四位一同吃饭去。我敢说，为了这场争端，此后是要洒出鲜血的。\u003cb class=\"epub-calibre3\">（同下。）\u003c/b>\u003c/p>\n","text":"普兰塔琪纳特 谢谢您，我的好先生。来吧，今天由我做东，我们四位一同吃饭去。我敢说，为了这场争端，此后是要洒出鲜血的。（同下。）\n","sourceAnchor":null,"tag":"p"}],"heading":"第四场 伦敦。国会花园","headingLevel":4,"sourceAnchor":"a470","actNumber":2,"sceneNumber":4},{"id":"part0022-section-013","label":"第二幕 · 第五场 同前。伦敦塔中一室","kind":"scene","blocks":[{"id":"part0022-00340","html":"\u003ch4 id=\"epub-part0022-a471\" class=\"epub-calibre12\">第五场 同前。伦敦塔中一室\u003c/h4>\n","text":"第五场 同前。伦敦塔中一室\n","sourceAnchor":"a471","tag":"h4"},{"id":"part0022-00341","html":"\u003cp class=\"epub-block1\">两狱卒用椅舁摩提默上。\u003c/p>\n","text":"两狱卒用椅舁摩提默上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00342","html":"\u003cp class=\"epub-calibre1\">摩提默 看守我这衰弱的老头子的好人们，让垂死的摩提默在这儿歇一歇吧。我由于长期监禁，肢体痛楚不堪，好像刚从刑架上拖下来的人一般。我这满头白发，是在苦难的岁月中折磨出来的，它预示着摩提默的死期不远了。我的眼睛，好比灯油耗尽的油灯，愈来愈模糊，快到尽头了。我的疲惫的双肩，被沉重的悲愁压得抬不起来；我这软弱的两臂，好比是一条枯藤，干枯的枝叶都已低垂到地上。我的脚已经麻痹，支撑不住我的身子，却恨不能急速地奔进坟墓，因为我除死以外，不能指望得到什么安慰了。不过请你告诉我，看守人，我的外甥能不能来？\u003c/p>\n","text":"摩提默 看守我这衰弱的老头子的好人们，让垂死的摩提默在这儿歇一歇吧。我由于长期监禁，肢体痛楚不堪，好像刚从刑架上拖下来的人一般。我这满头白发，是在苦难的岁月中折磨出来的，它预示着摩提默的死期不远了。我的眼睛，好比灯油耗尽的油灯，愈来愈模糊，快到尽头了。我的疲惫的双肩，被沉重的悲愁压得抬不起来；我这软弱的两臂，好比是一条枯藤，干枯的枝叶都已低垂到地上。我的脚已经麻痹，支撑不住我的身子，却恨不能急速地奔进坟墓，因为我除死以外，不能指望得到什么安慰了。不过请你告诉我，看守人，我的外甥能不能来？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00343","html":"\u003cp class=\"epub-calibre1\">狱卒甲 大人，理查·普兰塔琪纳特说准来。我们送信到议会里，送到他的办公室里，回话说他一定来。\u003c/p>\n","text":"狱卒甲 大人，理查·普兰塔琪纳特说准来。我们送信到议会里，送到他的办公室里，回话说他一定来。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00344","html":"\u003cp class=\"epub-calibre1\">摩提默 那就好，那我就心满意足了。可怜的好人儿，他遭受的冤枉跟我也相差无几了。我先前本是军功煊赫的风云人物，自从亨利·蒙穆斯当国以后，我就被抄了家，从那时起，理查也失了势，荣誉和世职都被剥夺了。现在，解救人类绝望、消除人们痛苦的死神，马上要把我从这苦难的人世解脱出去了。我希望他的灾难也能结束，他所失去的东西能够物归原主。\u003c/p>\n","text":"摩提默 那就好，那我就心满意足了。可怜的好人儿，他遭受的冤枉跟我也相差无几了。我先前本是军功煊赫的风云人物，自从亨利·蒙穆斯当国以后，我就被抄了家，从那时起，理查也失了势，荣誉和世职都被剥夺了。现在，解救人类绝望、消除人们痛苦的死神，马上要把我从这苦难的人世解脱出去了。我希望他的灾难也能结束，他所失去的东西能够物归原主。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00345","html":"\u003cp class=\"epub-block1\">理查·普兰塔琪纳特上。\u003c/p>\n","text":"理查·普兰塔琪纳特上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00346","html":"\u003cp class=\"epub-calibre1\">狱卒甲 大人，您的孝顺的外甥已经来到了。\u003c/p>\n","text":"狱卒甲 大人，您的孝顺的外甥已经来到了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00347","html":"\u003cp class=\"epub-calibre1\">摩提默 我的朋友，你说理查已经来了吗？\u003c/p>\n","text":"摩提默 我的朋友，你说理查已经来了吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00348","html":"\u003cp class=\"epub-calibre1\">普兰塔琪纳特 哎，尊贵的舅舅，您委屈了。您的外甥，就是新近受辱的理查，现在是在您的面前。\u003c/p>\n","text":"普兰塔琪纳特 哎，尊贵的舅舅，您委屈了。您的外甥，就是新近受辱的理查，现在是在您的面前。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00349","html":"\u003cp class=\"epub-calibre1\">摩提默 把我的胳膊放到他的脖子上，让我好拥抱他，让我在他的怀里喘我最后的一口气。啊，告诉我，我的嘴唇是不是碰上他的面颊了，我要慈爱地轻轻吻他一下。现在对我讲一讲，伟大的约克血统的嫩芽，你为什么说你新近受了辱？\u003c/p>\n","text":"摩提默 把我的胳膊放到他的脖子上，让我好拥抱他，让我在他的怀里喘我最后的一口气。啊，告诉我，我的嘴唇是不是碰上他的面颊了，我要慈爱地轻轻吻他一下。现在对我讲一讲，伟大的约克血统的嫩芽，你为什么说你新近受了辱？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00350","html":"\u003cp class=\"epub-calibre1\">普兰塔琪纳特 先把您的衰老的肩背倚在我的臂上，等您舒服一点，我再把我的怨愤说给您听。今天因为争论一桩事情，我和萨穆塞特斗了嘴。他用毒辣的舌头辱骂我，说我父亲死得不体面。这种辱骂堵住了我的嘴，使我不能用同样的话回骂他。因此，我的好舅舅，看在我父亲的分上，也是为了我们普兰塔琪纳特家族的荣誉和团结起见，请您告诉我，我父亲剑桥伯爵是为了什么事情丧失他的头颅的。\u003c/p>\n","text":"普兰塔琪纳特 先把您的衰老的肩背倚在我的臂上，等您舒服一点，我再把我的怨愤说给您听。今天因为争论一桩事情，我和萨穆塞特斗了嘴。他用毒辣的舌头辱骂我，说我父亲死得不体面。这种辱骂堵住了我的嘴，使我不能用同样的话回骂他。因此，我的好舅舅，看在我父亲的分上，也是为了我们普兰塔琪纳特家族的荣誉和团结起见，请您告诉我，我父亲剑桥伯爵是为了什么事情丧失他的头颅的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00351","html":"\u003cp class=\"epub-calibre1\">摩提默 贤甥，我同你父亲是在同一个案子里遭了毒手，我被关进了这座可恨的牢狱，虚掷了我的青春，在这里憔悴待死，你的父亲则送了性命。\u003c/p>\n","text":"摩提默 贤甥，我同你父亲是在同一个案子里遭了毒手，我被关进了这座可恨的牢狱，虚掷了我的青春，在这里憔悴待死，你的父亲则送了性命。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00352","html":"\u003cp class=\"epub-calibre1\">普兰塔琪纳特 请您把那案情说得更详细一些，因为我全不知道，而且也无从揣测。\u003c/p>\n","text":"普兰塔琪纳特 请您把那案情说得更详细一些，因为我全不知道，而且也无从揣测。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00353","html":"\u003cp class=\"epub-calibre1\">摩提默 我是要说的，如果我的一口气不断，还来得及把那桩案件说完的话。今王的祖父亨利四世把他的侄儿就是爱德华三世的长子和合法继承人爱德华的儿子理查废掉，自己坐上王位。当他在位的时候，北方的潘西家族不服他非法篡位，就起兵拥戴我继承王位。这些北方军人所持的理由是：理查幼王既已被废，他又没有留下亲生的嗣子，我在血统上就是他最亲的人。我在母系方面，是爱德华三世第三子克莱伦斯公爵的后裔，而亨利四世则是爱德华王第四子刚特公爵的子孙。按房份的顺序来说，我是在他之先的。你看，在这一场拥戴合法继承人嗣承王位的斗争中，我丧失了自由，他们牺牲了生命。之后，过了很久，亨利五世继承他父波林勃洛克登了基，这时你父剑桥伯爵——他是有名的约克公爵爱德蒙·兰格雷的儿子——娶了我的姐姐——那就是你的母亲。他同情我的不幸遭遇，又征集了一支人马，想把我救出牢狱，扶上王座，可是他和前人一样，又失败了，终于上了断头台。我们摩提默家族，本应享有继承权的，就这样硬被排挤掉了。\u003c/p>\n","text":"摩提默 我是要说的，如果我的一口气不断，还来得及把那桩案件说完的话。今王的祖父亨利四世把他的侄儿就是爱德华三世的长子和合法继承人爱德华的儿子理查废掉，自己坐上王位。当他在位的时候，北方的潘西家族不服他非法篡位，就起兵拥戴我继承王位。这些北方军人所持的理由是：理查幼王既已被废，他又没有留下亲生的嗣子，我在血统上就是他最亲的人。我在母系方面，是爱德华三世第三子克莱伦斯公爵的后裔，而亨利四世则是爱德华王第四子刚特公爵的子孙。按房份的顺序来说，我是在他之先的。你看，在这一场拥戴合法继承人嗣承王位的斗争中，我丧失了自由，他们牺牲了生命。之后，过了很久，亨利五世继承他父波林勃洛克登了基，这时你父剑桥伯爵——他是有名的约克公爵爱德蒙·兰格雷的儿子——娶了我的姐姐——那就是你的母亲。他同情我的不幸遭遇，又征集了一支人马，想把我救出牢狱，扶上王座，可是他和前人一样，又失败了，终于上了断头台。我们摩提默家族，本应享有继承权的，就这样硬被排挤掉了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00354","html":"\u003cp class=\"epub-calibre1\">普兰塔琪纳特 这样说来，我的舅舅，您是摩提默家族中最后一人了。\u003c/p>\n","text":"普兰塔琪纳特 这样说来，我的舅舅，您是摩提默家族中最后一人了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00355","html":"\u003cp class=\"epub-calibre1\">摩提默 是的，你知道我没有子嗣，我现在上气不接下气，眼看就要死了，我要你做我的嗣子，其余的事，你自己琢磨吧。不过在你策划的时候，务必处处留神。\u003c/p>\n","text":"摩提默 是的，你知道我没有子嗣，我现在上气不接下气，眼看就要死了，我要你做我的嗣子，其余的事，你自己琢磨吧。不过在你策划的时候，务必处处留神。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00356","html":"\u003cp class=\"epub-calibre1\">普兰塔琪纳特 您的郑重训诲我已经领会了，不过我心里总在想，我父亲被杀，对方实在太毒辣了。\u003c/p>\n","text":"普兰塔琪纳特 您的郑重训诲我已经领会了，不过我心里总在想，我父亲被杀，对方实在太毒辣了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00357","html":"\u003cp class=\"epub-calibre1\">摩提默 贤甥，你要少开口，多耍手腕。兰开斯特家族已经是根深蒂固的了，好比是一座推不翻的大山。现在你舅舅快要离开人世了，好像王爷们在一个地方住得太久了，感到腻烦，就将宫廷迁往别处一般。\u003c/p>\n","text":"摩提默 贤甥，你要少开口，多耍手腕。兰开斯特家族已经是根深蒂固的了，好比是一座推不翻的大山。现在你舅舅快要离开人世了，好像王爷们在一个地方住得太久了，感到腻烦，就将宫廷迁往别处一般。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00358","html":"\u003cp class=\"epub-calibre1\">普兰塔琪纳特 啊，舅舅，我恨不能将我的寿算拿出几个年头来替您延年益寿。\u003c/p>\n","text":"普兰塔琪纳特 啊，舅舅，我恨不能将我的寿算拿出几个年头来替您延年益寿。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00359","html":"\u003cp class=\"epub-calibre1\">摩提默 你如那样，反而是害了我了，我的刽子手正是用这个法子对付我的，明明一刀就可送命，却偏叫我活受零罪。你也不要伤心，你的悲伤不会对我有什么好处，我只要你替我把丧事料理好。再见了，祝你事事称心，祝你平时和战时的生活都能昌盛。\u003cb class=\"epub-calibre3\">（死。）\u003c/b>\u003c/p>\n","text":"摩提默 你如那样，反而是害了我了，我的刽子手正是用这个法子对付我的，明明一刀就可送命，却偏叫我活受零罪。你也不要伤心，你的悲伤不会对我有什么好处，我只要你替我把丧事料理好。再见了，祝你事事称心，祝你平时和战时的生活都能昌盛。（死。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00360","html":"\u003cp class=\"epub-calibre1\">普兰塔琪纳特 祝您离去的灵魂平安无事。您在牢狱里走完了天路历程，像一个虔修的隐士度过了一生。好，我要把他的训示深藏在心里，我的一切计谋都要暂时隐忍在心里。看守人，你们把他抬出去，我要亲自把他的葬礼安排妥帖，使他比生前更能受到应有的尊崇。\u003cb class=\"epub-calibre3\">（众狱卒抬摩提默尸体下）\u003c/b>摩提默家族的昏暗的火炬就这样熄灭了，是被一些比他低微的人们压灭的。至于萨穆塞特加在我的家族上的诬蔑和伤害，我一定能够洗刷得干干净净。我现在就赶到议会里去，要求恢复我的世职，把我的不利地位转为有利。\u003cb class=\"epub-calibre3\">（下。）\u003c/b>\u003c/p>\n","text":"普兰塔琪纳特 祝您离去的灵魂平安无事。您在牢狱里走完了天路历程，像一个虔修的隐士度过了一生。好，我要把他的训示深藏在心里，我的一切计谋都要暂时隐忍在心里。看守人，你们把他抬出去，我要亲自把他的葬礼安排妥帖，使他比生前更能受到应有的尊崇。（众狱卒抬摩提默尸体下）摩提默家族的昏暗的火炬就这样熄灭了，是被一些比他低微的人们压灭的。至于萨穆塞特加在我的家族上的诬蔑和伤害，我一定能够洗刷得干干净净。我现在就赶到议会里去，要求恢复我的世职，把我的不利地位转为有利。（下。）\n","sourceAnchor":null,"tag":"p"}],"heading":"第五场 同前。伦敦塔中一室","headingLevel":4,"sourceAnchor":"a471","actNumber":2,"sceneNumber":5},{"id":"part0022-section-014","label":"第三幕","kind":"act","blocks":[{"id":"part0022-00361","html":"\u003ch3 id=\"epub-part0022-a472\" class=\"epub-calibre11\">第三幕\u003c/h3>\n","text":"第三幕\n","sourceAnchor":"a472","tag":"h3"}],"heading":"第三幕","headingLevel":3,"sourceAnchor":"a472","actNumber":3},{"id":"part0022-section-015","label":"第三幕 · 第一场 伦敦。国会会场","kind":"scene","blocks":[{"id":"part0022-00362","html":"\u003ch4 id=\"epub-part0022-a473\" class=\"epub-calibre12\">第一场 伦敦。国会会场\u003c/h4>\n","text":"第一场 伦敦。国会会场\n","sourceAnchor":"a473","tag":"h4"},{"id":"part0022-00363","html":"\u003cp class=\"epub-block1\">喇叭奏花腔。亨利王、爱克塞特、葛罗斯特、华列克、萨穆塞特、萨福克、温彻斯特、理查·普兰塔琪纳特及余人上。葛罗斯特正拟宣读一个提案，温彻斯特将提案抢去撕碎。\u003c/p>\n","text":"喇叭奏花腔。亨利王、爱克塞特、葛罗斯特、华列克、萨穆塞特、萨福克、温彻斯特、理查·普兰塔琪纳特及余人上。葛罗斯特正拟宣读一个提案，温彻斯特将提案抢去撕碎。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00364","html":"\u003cp class=\"epub-calibre1\">温彻斯特 亨弗雷·葛罗斯特，你是预先做好文章、打好稿子，带到这儿来的吗？如果你敢控告我，加给我任何罪名，就不准预先写稿子，要临时随口说出来。不管你说我什么，我都能随口回答你。\u003c/p>\n","text":"温彻斯特 亨弗雷·葛罗斯特，你是预先做好文章、打好稿子，带到这儿来的吗？如果你敢控告我，加给我任何罪名，就不准预先写稿子，要临时随口说出来。不管你说我什么，我都能随口回答你。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00365","html":"\u003cp class=\"epub-calibre1\">葛罗斯特 狂悖的和尚！我在这地方不得不耐着点儿性子，要不然你就会发现你这样污辱我会有什么后果。不要以为我用书面列举你极恶的罪名就是出于捏造，也不要以为我笔底下写出的东西，我口里就背不出来。主教，你错了。你是如此罪恶昭彰，荒淫无耻，连三岁孩子也说你这人是惹不得的。你重利盘剥、刚愎自用、扰乱治安；你淫乱荒唐，辱没了你在教会中窃据的高位。至于你的阴险奸诈，那更是一望而知的。你在伦敦桥上和伦敦塔里，三番五次地想谋害我的性命。这还不算，如果把你心里想的摊出来看看，只怕你那愈来愈大的野心是连王上你也不肯饶过的。\u003c/p>\n","text":"葛罗斯特 狂悖的和尚！我在这地方不得不耐着点儿性子，要不然你就会发现你这样污辱我会有什么后果。不要以为我用书面列举你极恶的罪名就是出于捏造，也不要以为我笔底下写出的东西，我口里就背不出来。主教，你错了。你是如此罪恶昭彰，荒淫无耻，连三岁孩子也说你这人是惹不得的。你重利盘剥、刚愎自用、扰乱治安；你淫乱荒唐，辱没了你在教会中窃据的高位。至于你的阴险奸诈，那更是一望而知的。你在伦敦桥上和伦敦塔里，三番五次地想谋害我的性命。这还不算，如果把你心里想的摊出来看看，只怕你那愈来愈大的野心是连王上你也不肯饶过的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00366","html":"\u003cp class=\"epub-calibre1\">温彻斯特 葛罗斯特，我说你是满口胡言。众位大人，请容许我对他的控诉进行答辩。他说我贪财、狂悖，那么请问，为什么我至今还是一贫如洗？他说我野心勃勃，我又为什么守着本职，不求升迁？至于说我喜欢闹事，要不是有人对我挑衅，还有谁比我更爱好和平？不对的，众位大人，不是这些事情惹他生气，这不是公爵动怒的原因。真正的原因是他要一个人独揽大权，由他一人包围王上，他不能称心如愿，就不由得怒气填胸、咆哮如雷。但他应该知道我是一个好——\u003c/p>\n","text":"温彻斯特 葛罗斯特，我说你是满口胡言。众位大人，请容许我对他的控诉进行答辩。他说我贪财、狂悖，那么请问，为什么我至今还是一贫如洗？他说我野心勃勃，我又为什么守着本职，不求升迁？至于说我喜欢闹事，要不是有人对我挑衅，还有谁比我更爱好和平？不对的，众位大人，不是这些事情惹他生气，这不是公爵动怒的原因。真正的原因是他要一个人独揽大权，由他一人包围王上，他不能称心如愿，就不由得怒气填胸、咆哮如雷。但他应该知道我是一个好——\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00367","html":"\u003cp class=\"epub-calibre1\">葛罗斯特 好个鬼！你不过是我祖父的一个私生子罢了！\u003c/p>\n","text":"葛罗斯特 好个鬼！你不过是我祖父的一个私生子罢了！\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00368","html":"\u003cp class=\"epub-calibre1\">温彻斯特 嗳，大人，你又是个什么呢，我请问？不过是个依仗别人的王位，狐假虎威的角色罢了。\u003c/p>\n","text":"温彻斯特 嗳，大人，你又是个什么呢，我请问？不过是个依仗别人的王位，狐假虎威的角色罢了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00369","html":"\u003cp class=\"epub-calibre1\">葛罗斯特 难道我不是护国公吗，刁钻的和尚？\u003c/p>\n","text":"葛罗斯特 难道我不是护国公吗，刁钻的和尚？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00370","html":"\u003cp class=\"epub-calibre1\">温彻斯特 难道我不是教会里的一位主教吗？\u003c/p>\n","text":"温彻斯特 难道我不是教会里的一位主教吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00371","html":"\u003cp class=\"epub-calibre1\">葛罗斯特 是呀，你躲在教会里，好比是强盗躲在城堡里，只是为了便于掩护他的贼赃。\u003c/p>\n","text":"葛罗斯特 是呀，你躲在教会里，好比是强盗躲在城堡里，只是为了便于掩护他的贼赃。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00372","html":"\u003cp class=\"epub-calibre1\">温彻斯特 不敬畏上帝的葛罗斯特哟！\u003c/p>\n","text":"温彻斯特 不敬畏上帝的葛罗斯特哟！\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00373","html":"\u003cp class=\"epub-calibre1\">葛罗斯特 你也不过在职务上敬畏上帝，你在私生活上何尝敬畏上帝？\u003c/p>\n","text":"葛罗斯特 你也不过在职务上敬畏上帝，你在私生活上何尝敬畏上帝？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00374","html":"\u003cp class=\"epub-calibre1\">温彻斯特 我要向罗马申诉的。\u003c/p>\n","text":"温彻斯特 我要向罗马申诉的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00375","html":"\u003cp class=\"epub-calibre1\">华列克 那么你就骑着骡马去吧。\u003c/p>\n","text":"华列克 那么你就骑着骡马去吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00376","html":"\u003cp class=\"epub-calibre1\">萨穆塞特 大人，您该容忍一点才是。\u003c/p>\n","text":"萨穆塞特 大人，您该容忍一点才是。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00377","html":"\u003cp class=\"epub-calibre1\">华列克 是呀，不能叫主教过于难堪。\u003c/p>\n","text":"华列克 是呀，不能叫主教过于难堪。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00378","html":"\u003cp class=\"epub-calibre1\">萨穆塞特 我想您爵爷应该有点宗教意识，知道怎样对待教会里有职位的人。\u003c/p>\n","text":"萨穆塞特 我想您爵爷应该有点宗教意识，知道怎样对待教会里有职位的人。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00379","html":"\u003cp class=\"epub-calibre1\">华列克 我想咱们的主教也该谦逊一些，这样争辩是有失身份的。\u003c/p>\n","text":"华列克 我想咱们的主教也该谦逊一些，这样争辩是有失身份的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00380","html":"\u003cp class=\"epub-calibre1\">萨穆塞特 对啦，触动他的圣职地位，他不得不争。\u003c/p>\n","text":"萨穆塞特 对啦，触动他的圣职地位，他不得不争。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00381","html":"\u003cp class=\"epub-calibre1\">华列克 什么圣职不圣职，那有什么关系？难道公爷不是王上的护国公吗？\u003c/p>\n","text":"华列克 什么圣职不圣职，那有什么关系？难道公爷不是王上的护国公吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00382","html":"\u003cp class=\"epub-calibre1\">普兰塔琪纳特 \u003cb class=\"epub-calibre3\">（旁白）\u003c/b>我看我还是不开口的好，免得他们要说：“小伙子，等你该说话的时候再说吧，我们爵爷们在谈话，你能插嘴吗？”不然的话，我倒可以对准温彻斯特放一支冷箭。\u003c/p>\n","text":"普兰塔琪纳特 （旁白）我看我还是不开口的好，免得他们要说：“小伙子，等你该说话的时候再说吧，我们爵爷们在谈话，你能插嘴吗？”不然的话，我倒可以对准温彻斯特放一支冷箭。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00383","html":"\u003cp class=\"epub-calibre1\">亨利王 葛罗斯特叔父，温彻斯特叔公，你们都是我们英国的国家栋梁，我要恳求你们，如果恳求是有效的话，务必要和衷共济、言归于好才好。倘若两位重臣互相排挤，岂不是朝廷的耻辱？贤卿们，我虽然年事还轻，可我也知道，臣僚不和，好比是一条毒蛇，会把国家的心脏给啃掉的。\u003c/p>\n","text":"亨利王 葛罗斯特叔父，温彻斯特叔公，你们都是我们英国的国家栋梁，我要恳求你们，如果恳求是有效的话，务必要和衷共济、言归于好才好。倘若两位重臣互相排挤，岂不是朝廷的耻辱？贤卿们，我虽然年事还轻，可我也知道，臣僚不和，好比是一条毒蛇，会把国家的心脏给啃掉的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00384","html":"\u003cp class=\"epub-block1\">内喊声：“打倒穿褐色号衣的野种们！”\u003c/p>\n","text":"内喊声：“打倒穿褐色号衣的野种们！”\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00385","html":"\u003cp class=\"epub-calibre1\">亨利王 这是什么人在起哄？\u003c/p>\n","text":"亨利王 这是什么人在起哄？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00386","html":"\u003cp class=\"epub-calibre1\">华列克 我敢保证，这一定是主教手下的人，存心在闹事。\u003c/p>\n","text":"华列克 我敢保证，这一定是主教手下的人，存心在闹事。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00387","html":"\u003cp class=\"epub-block1\">内喊声又起：“扔石头呀！扔石头呀！”伦敦市长率随员上。\u003c/p>\n","text":"内喊声又起：“扔石头呀！扔石头呀！”伦敦市长率随员上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00388","html":"\u003cp class=\"epub-calibre1\">市长 啊呀，列位大人，吾王陛下，可怜可怜伦敦市吧，可怜可怜我们吧！主教和葛罗斯特公爵的手下人成群结队地打起架来啦。我曾禁止他们携带武器，他们就在衣袋里装满石子，用石子投击对方，已经有好些人的脑浆被砸出来了。每条街上的门窗都打坏了，铺子都吓得关了门啦。\u003c/p>\n","text":"市长 啊呀，列位大人，吾王陛下，可怜可怜伦敦市吧，可怜可怜我们吧！主教和葛罗斯特公爵的手下人成群结队地打起架来啦。我曾禁止他们携带武器，他们就在衣袋里装满石子，用石子投击对方，已经有好些人的脑浆被砸出来了。每条街上的门窗都打坏了，铺子都吓得关了门啦。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00389","html":"\u003cp class=\"epub-block1\">双方的亲兵们上，彼此混战，打得头破血流。\u003c/p>\n","text":"双方的亲兵们上，彼此混战，打得头破血流。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00390","html":"\u003cp class=\"epub-calibre1\">亨利王 你们既是我的忠顺臣民，我命令你们立即住手，维持秩序。葛罗斯特叔父，请你制止这场纷争。\u003c/p>\n","text":"亨利王 你们既是我的忠顺臣民，我命令你们立即住手，维持秩序。葛罗斯特叔父，请你制止这场纷争。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00391","html":"\u003cp class=\"epub-calibre1\">亲兵甲 不行，要是不准我们扔石头，我们就用牙咬。\u003c/p>\n","text":"亲兵甲 不行，要是不准我们扔石头，我们就用牙咬。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00392","html":"\u003cp class=\"epub-calibre1\">亲兵乙 你爱怎么干就怎么干，我们也不含糊。\u003cb class=\"epub-calibre3\">（混战又起。）\u003c/b>\u003c/p>\n","text":"亲兵乙 你爱怎么干就怎么干，我们也不含糊。（混战又起。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00393","html":"\u003cp class=\"epub-calibre1\">葛罗斯特 我方的弟兄们，别再闹了，不要再械斗了。\u003c/p>\n","text":"葛罗斯特 我方的弟兄们，别再闹了，不要再械斗了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00394","html":"\u003cp class=\"epub-calibre1\">亲兵丙 大人，我们知道您是一个公正、正直的人，除了王上陛下，您的身份最高贵。您是我们国家的仁慈的父亲，我们不能看着您这位贵人受一个书生的欺负，我们的妻儿老小和我们自己都愿意为您效死，纵然被您的敌人杀死也甘心。\u003c/p>\n","text":"亲兵丙 大人，我们知道您是一个公正、正直的人，除了王上陛下，您的身份最高贵。您是我们国家的仁慈的父亲，我们不能看着您这位贵人受一个书生的欺负，我们的妻儿老小和我们自己都愿意为您效死，纵然被您的敌人杀死也甘心。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00395","html":"\u003cp class=\"epub-calibre1\">亲兵甲 不错，我们死后，我们剪下的指甲也能聚成一队人马，再和他们交战。\u003cb class=\"epub-calibre3\">（重复交战。）\u003c/b>\u003c/p>\n","text":"亲兵甲 不错，我们死后，我们剪下的指甲也能聚成一队人马，再和他们交战。（重复交战。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00396","html":"\u003cp class=\"epub-calibre1\">葛罗斯特 住手，我说，住手呀！如果你们是爱护我的，你们已说过是爱护我的，就听从我的劝解，暂时忍耐一下。\u003c/p>\n","text":"葛罗斯特 住手，我说，住手呀！如果你们是爱护我的，你们已说过是爱护我的，就听从我的劝解，暂时忍耐一下。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00397","html":"\u003cp class=\"epub-calibre1\">亨利王 唉，这场争吵叫我心里好难受呀！温彻斯特贤卿，你看着我涕泪交流，竟是无动于衷吗？如果你没有恻隐之心，谁还有恻隐之心？如果供奉圣职的人爱争吵，还能教谁笃爱和平？\u003c/p>\n","text":"亨利王 唉，这场争吵叫我心里好难受呀！温彻斯特贤卿，你看着我涕泪交流，竟是无动于衷吗？如果你没有恻隐之心，谁还有恻隐之心？如果供奉圣职的人爱争吵，还能教谁笃爱和平？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00398","html":"\u003cp class=\"epub-calibre1\">华列克 让步吧，护国公大人，让步吧，温彻斯特主教。难道你们要固执到底，逼死你们的王上，摧毁你们的国家吗？你们看，由于你们两人互相仇视，已经酿成惨祸了。除非你们居心要想流血，就言归于好吧。\u003c/p>\n","text":"华列克 让步吧，护国公大人，让步吧，温彻斯特主教。难道你们要固执到底，逼死你们的王上，摧毁你们的国家吗？你们看，由于你们两人互相仇视，已经酿成惨祸了。除非你们居心要想流血，就言归于好吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00399","html":"\u003cp class=\"epub-calibre1\">温彻斯特 叫他先认错，否则我决不退让。\u003c/p>\n","text":"温彻斯特 叫他先认错，否则我决不退让。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00400","html":"\u003cp class=\"epub-calibre1\">葛罗斯特 看在王上的分上，我只得屈从，否则我要挖出那和尚的心肝，也不能让他占我的上风。\u003c/p>\n","text":"葛罗斯特 看在王上的分上，我只得屈从，否则我要挖出那和尚的心肝，也不能让他占我的上风。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00401","html":"\u003cp class=\"epub-calibre1\">华列克 温彻斯特主教，你看，公爷的怒火已经平息了，从他舒展的眉宇间可以看出来，您为什么还这样剑拔弩张呢？\u003c/p>\n","text":"华列克 温彻斯特主教，你看，公爷的怒火已经平息了，从他舒展的眉宇间可以看出来，您为什么还这样剑拔弩张呢？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00402","html":"\u003cp class=\"epub-calibre1\">葛罗斯特 来吧，温彻斯特，我向你伸出和解的手来。\u003c/p>\n","text":"葛罗斯特 来吧，温彻斯特，我向你伸出和解的手来。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00403","html":"\u003cp class=\"epub-calibre1\">亨利王 呸，波福叔公！我听你讲道时曾说过，害人之心是极恶的大罪。难道你言行不一，首先违犯你自己的训示吗？\u003c/p>\n","text":"亨利王 呸，波福叔公！我听你讲道时曾说过，害人之心是极恶的大罪。难道你言行不一，首先违犯你自己的训示吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00404","html":"\u003cp class=\"epub-calibre1\">华列克 王上说得真好！主教碰了一个软钉子啦。温彻斯特主教大人，不怕难为情吗？宽容点吧！嘿嘿，你要让一个孩子教导你怎样做人吗？\u003c/p>\n","text":"华列克 王上说得真好！主教碰了一个软钉子啦。温彻斯特主教大人，不怕难为情吗？宽容点吧！嘿嘿，你要让一个孩子教导你怎样做人吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00405","html":"\u003cp class=\"epub-calibre1\">温彻斯特 好吧，葛罗斯特公爵，我对你让步。我用好意回敬你的好意，我伸出手来回敬你伸出的手。\u003c/p>\n","text":"温彻斯特 好吧，葛罗斯特公爵，我对你让步。我用好意回敬你的好意，我伸出手来回敬你伸出的手。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00406","html":"\u003cp class=\"epub-calibre1\">葛罗斯特 \u003cb class=\"epub-calibre3\">（旁白）\u003c/b>哼，我看这都是虚情假意——我的朋友们，亲爱的同胞们，瞧吧，我们两人握手，这等于一面休战的旗子，表示我们两人和我们的一切手下人之间，已经和好了。上帝垂鉴，我决没有丝毫虚假。\u003c/p>\n","text":"葛罗斯特 （旁白）哼，我看这都是虚情假意——我的朋友们，亲爱的同胞们，瞧吧，我们两人握手，这等于一面休战的旗子，表示我们两人和我们的一切手下人之间，已经和好了。上帝垂鉴，我决没有丝毫虚假。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00407","html":"\u003cp class=\"epub-calibre1\">温彻斯特 \u003cb class=\"epub-calibre3\">（旁白）\u003c/b>上帝鉴察，我不是口不应心的！\u003c/p>\n","text":"温彻斯特 （旁白）上帝鉴察，我不是口不应心的！\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00408","html":"\u003cp class=\"epub-calibre1\">亨利王 啊，亲爱的叔父，慈爱的葛罗斯特公爵，你们讲了和，我真高兴呀！去吧，你们众人！不要再搅扰我们了。你们的主人已经讲和，你们也和好吧。\u003c/p>\n","text":"亨利王 啊，亲爱的叔父，慈爱的葛罗斯特公爵，你们讲了和，我真高兴呀！去吧，你们众人！不要再搅扰我们了。你们的主人已经讲和，你们也和好吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00409","html":"\u003cp class=\"epub-calibre1\">亲兵甲 我满意了，我到外科医生那里去医伤。\u003c/p>\n","text":"亲兵甲 我满意了，我到外科医生那里去医伤。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00410","html":"\u003cp class=\"epub-calibre1\">亲兵乙 我也去。\u003c/p>\n","text":"亲兵乙 我也去。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00411","html":"\u003cp class=\"epub-calibre1\">亲兵丙 我到酒店去看看有什么治伤的东西。\u003cb class=\"epub-calibre3\">（市长及众亲兵等下。）\u003c/b>\u003c/p>\n","text":"亲兵丙 我到酒店去看看有什么治伤的东西。（市长及众亲兵等下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00412","html":"\u003cp class=\"epub-calibre1\">华列克 吾王陛下，我们有一道奏章保荐理查·普兰塔琪纳特，敬请陛下赐阅。\u003c/p>\n","text":"华列克 吾王陛下，我们有一道奏章保荐理查·普兰塔琪纳特，敬请陛下赐阅。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00413","html":"\u003cp class=\"epub-calibre1\">葛罗斯特 华列克爵爷，保奏得好。我的好王上，您的恩泽无所不施，对于理查一定要加恩的。此中的原委，我在埃尔萨姆宫里已经奏明陛下了。\u003c/p>\n","text":"葛罗斯特 华列克爵爷，保奏得好。我的好王上，您的恩泽无所不施，对于理查一定要加恩的。此中的原委，我在埃尔萨姆宫里已经奏明陛下了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00414","html":"\u003cp class=\"epub-calibre1\">亨利王 叔父，你提到的那些情节是有道理的，因此，众位贤卿，我们决定让理查恢复世职。\u003c/p>\n","text":"亨利王 叔父，你提到的那些情节是有道理的，因此，众位贤卿，我们决定让理查恢复世职。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00415","html":"\u003cp class=\"epub-calibre1\">华列克 让理查恢复世职，他父亲的冤枉也得到昭雪了。\u003c/p>\n","text":"华列克 让理查恢复世职，他父亲的冤枉也得到昭雪了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00416","html":"\u003cp class=\"epub-calibre1\">温彻斯特 大家既然同意，我也同意。\u003c/p>\n","text":"温彻斯特 大家既然同意，我也同意。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00417","html":"\u003cp class=\"epub-calibre1\">亨利王 理查，只要你真心效忠，我不仅赏还你的世职，还要将你祖上约克家族的全部产业发还给你。\u003c/p>\n","text":"亨利王 理查，只要你真心效忠，我不仅赏还你的世职，还要将你祖上约克家族的全部产业发还给你。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00418","html":"\u003cp class=\"epub-calibre1\">普兰塔琪纳特 微臣立誓效忠，一定尽心竭力，死而后已。\u003c/p>\n","text":"普兰塔琪纳特 微臣立誓效忠，一定尽心竭力，死而后已。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00419","html":"\u003cp class=\"epub-calibre1\">亨利王 你可以跪到我的面前。为了酬庸你的忠心，我把约克的军剑赏你佩戴。站起来，理查，做一个真正的普兰塔琪纳特，你已被封为尊崇的约克公爵了。\u003c/p>\n","text":"亨利王 你可以跪到我的面前。为了酬庸你的忠心，我把约克的军剑赏你佩戴。站起来，理查，做一个真正的普兰塔琪纳特，你已被封为尊崇的约克公爵了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00420","html":"\u003cp class=\"epub-calibre1\">普兰塔琪纳特 只要理查在职一天，决不允许陛下的敌人猖獗；我一定鞠躬尽瘁，铲除一切对陛下心怀贰意的人！\u003c/p>\n","text":"普兰塔琪纳特 只要理查在职一天，决不允许陛下的敌人猖獗；我一定鞠躬尽瘁，铲除一切对陛下心怀贰意的人！\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00421","html":"\u003cp class=\"epub-calibre1\">众人 欢迎您，高贵的爵爷，威武的约克公爵！\u003c/p>\n","text":"众人 欢迎您，高贵的爵爷，威武的约克公爵！\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00422","html":"\u003cp class=\"epub-calibre1\">萨穆塞特 \u003cb class=\"epub-calibre3\">（旁白）\u003c/b>死亡吧，卑鄙的爵爷，下贱的约克公爵！\u003c/p>\n","text":"萨穆塞特 （旁白）死亡吧，卑鄙的爵爷，下贱的约克公爵！\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00423","html":"\u003cp class=\"epub-calibre1\">葛罗斯特 现在一切很好，就请吾王陛下渡海到法兰西，在那里举行加冕大典吧。国王临幸的地方，足以激发他的臣民和忠实朋友的爱戴之心，使他的敌人气馁。\u003c/p>\n","text":"葛罗斯特 现在一切很好，就请吾王陛下渡海到法兰西，在那里举行加冕大典吧。国王临幸的地方，足以激发他的臣民和忠实朋友的爱戴之心，使他的敌人气馁。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00424","html":"\u003cp class=\"epub-calibre1\">亨利王 凡是葛罗斯特叔父说的，本王无不照办，因为忠荩之言，可以消除许多隐患。\u003c/p>\n","text":"亨利王 凡是葛罗斯特叔父说的，本王无不照办，因为忠荩之言，可以消除许多隐患。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00425","html":"\u003cp class=\"epub-calibre1\">葛罗斯特 陛下的坐船已经准备好了。\u003cb class=\"epub-calibre3\">（内奏乐，喇叭奏花腔。除爱克塞特外，余人俱下。）\u003c/b>\u003c/p>\n","text":"葛罗斯特 陛下的坐船已经准备好了。（内奏乐，喇叭奏花腔。除爱克塞特外，余人俱下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00426","html":"\u003cp class=\"epub-calibre1\">爱克塞特 唉，我们尽管在英格兰或在法兰西耀武扬威，可是谁能预料大局怎样变化？现在朝内大臣，各立党派，表面上虽然假装和好，心里却燃烧着敌对的毒焰，总有一天要爆发出烈火来的。有如生着痈疽的肢体，慢慢溃烂下去，直到骨头和筋肉都一齐脱落，如今两派的恶意倾轧，也将会产生同样的结果。只怕当年亨利五世在位时的一句童谣现在要应验了。那童谣说：“出生在蒙穆斯的亨利赢得一切，出生在温莎的亨利毫无所得。”这苗头是越来越明显了，我但愿在那不幸的日子到来之前，我的寿命已经结束了才好。\u003cb class=\"epub-calibre3\">（下。）\u003c/b>\u003c/p>\n","text":"爱克塞特 唉，我们尽管在英格兰或在法兰西耀武扬威，可是谁能预料大局怎样变化？现在朝内大臣，各立党派，表面上虽然假装和好，心里却燃烧着敌对的毒焰，总有一天要爆发出烈火来的。有如生着痈疽的肢体，慢慢溃烂下去，直到骨头和筋肉都一齐脱落，如今两派的恶意倾轧，也将会产生同样的结果。只怕当年亨利五世在位时的一句童谣现在要应验了。那童谣说：“出生在蒙穆斯的亨利赢得一切，出生在温莎的亨利毫无所得。”这苗头是越来越明显了，我但愿在那不幸的日子到来之前，我的寿命已经结束了才好。（下。）\n","sourceAnchor":null,"tag":"p"}],"heading":"第一场 伦敦。国会会场","headingLevel":4,"sourceAnchor":"a473","actNumber":3,"sceneNumber":1},{"id":"part0022-section-016","label":"第三幕 · 第二场 法国。卢昂城前","kind":"scene","blocks":[{"id":"part0022-00427","html":"\u003ch4 id=\"epub-part0022-a474\" class=\"epub-calibre12\">第二场 法国。卢昂城前\u003c/h4>\n","text":"第二场 法国。卢昂城前\n","sourceAnchor":"a474","tag":"h4"},{"id":"part0022-00428","html":"\u003cp class=\"epub-block1\">贞德化装上，兵士们化装成农民，背麻袋随在后面。\u003c/p>\n","text":"贞德化装上，兵士们化装成农民，背麻袋随在后面。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00429","html":"\u003cp class=\"epub-calibre1\">贞德 前面已经是卢昂的城门了，我们现在要用计拿下这座城。你们行动要小心，说话要谨慎。你们要装作乡下人的口气，装作是进城卖玉米的。如果我们混进了城——我想我们是能混进去的——要是这些懒散的守兵们防卫不严，我就用暗号通知我们那边的人，请查理太子来攻城。\u003c/p>\n","text":"贞德 前面已经是卢昂的城门了，我们现在要用计拿下这座城。你们行动要小心，说话要谨慎。你们要装作乡下人的口气，装作是进城卖玉米的。如果我们混进了城——我想我们是能混进去的——要是这些懒散的守兵们防卫不严，我就用暗号通知我们那边的人，请查理太子来攻城。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00430","html":"\u003cp class=\"epub-calibre1\">兵士甲 我们背的是麻袋，我们就用它把这座城装起来。我们又将是卢昂的主人啦。现在就敲门吧。\u003cb class=\"epub-calibre3\">（敲门。）\u003c/b>\u003c/p>\n","text":"兵士甲 我们背的是麻袋，我们就用它把这座城装起来。我们又将是卢昂的主人啦。现在就敲门吧。（敲门。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00431","html":"\u003cp class=\"epub-calibre1\">守兵 \u003cb class=\"epub-calibre3\">（内白）\u003c/b>是谁？\u003c/p>\n","text":"守兵 （内白）是谁？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00432","html":"\u003cp class=\"epub-calibre1\">贞德 是老百姓，法兰西的穷苦老百姓。我们是到城里赶集卖玉米的。\u003c/p>\n","text":"贞德 是老百姓，法兰西的穷苦老百姓。我们是到城里赶集卖玉米的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00433","html":"\u003cp class=\"epub-calibre1\">守兵 \u003cb class=\"epub-calibre3\">（开城）\u003c/b>进来，进来吧，集上的钟声已经响了。\u003c/p>\n","text":"守兵 （开城）进来，进来吧，集上的钟声已经响了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00434","html":"\u003cp class=\"epub-calibre1\">贞德 嗨，卢昂，你的防御要被我摧毁了。\u003cb class=\"epub-calibre3\">（贞德等入城。）\u003c/b>\u003c/p>\n","text":"贞德 嗨，卢昂，你的防御要被我摧毁了。（贞德等入城。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00435","html":"\u003cp class=\"epub-block1\">查理、奥尔良庶子、阿朗松率军队上。\u003c/p>\n","text":"查理、奥尔良庶子、阿朗松率军队上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00436","html":"\u003cp class=\"epub-calibre1\">查理 愿圣丹尼斯保佑我们妙计成功！我们又可以在卢昂城里高枕无忧了。\u003c/p>\n","text":"查理 愿圣丹尼斯保佑我们妙计成功！我们又可以在卢昂城里高枕无忧了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00437","html":"\u003cp class=\"epub-calibre1\">庶子 贞德已经带着她的帮手们进了城。她到了那里以后，要用什么办法通知我们从哪里进攻最好呢？\u003c/p>\n","text":"庶子 贞德已经带着她的帮手们进了城。她到了那里以后，要用什么办法通知我们从哪里进攻最好呢？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00438","html":"\u003cp class=\"epub-calibre1\">阿朗松 她约好在城楼上举起一把火炬，一见火炬，就可以明白她的意思是：她进去的那个城门是全城防御最弱之处。\u003c/p>\n","text":"阿朗松 她约好在城楼上举起一把火炬，一见火炬，就可以明白她的意思是：她进去的那个城门是全城防御最弱之处。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00439","html":"\u003cp class=\"epub-block1\">贞德登上城头，高举火炬。\u003c/p>\n","text":"贞德登上城头，高举火炬。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00440","html":"\u003cp class=\"epub-calibre1\">贞德 瞧，这是一把幸福的结婚火炬，它把卢昂和它的同胞们结合起来，它把塔尔博的党徒烧得片甲不留。\u003cb class=\"epub-calibre3\">（下。）\u003c/b>\u003c/p>\n","text":"贞德 瞧，这是一把幸福的结婚火炬，它把卢昂和它的同胞们结合起来，它把塔尔博的党徒烧得片甲不留。（下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00441","html":"\u003cp class=\"epub-calibre1\">庶子 看哪，尊贵的查理殿下，我们的朋友已经把火炬插上城楼啦！\u003c/p>\n","text":"庶子 看哪，尊贵的查理殿下，我们的朋友已经把火炬插上城楼啦！\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00442","html":"\u003cp class=\"epub-calibre1\">查理 让这火炬像复仇的彗星一样散发光辉吧！让它预兆我们敌人的全部崩溃吧！\u003c/p>\n","text":"查理 让这火炬像复仇的彗星一样散发光辉吧！让它预兆我们敌人的全部崩溃吧！\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00443","html":"\u003cp class=\"epub-calibre1\">阿朗松 不能耽搁了，迁延会误事的。马上攻城，大家呐喊：“太子万岁！”把守兵们立刻干掉。\u003cb class=\"epub-calibre3\">（全体入城。）\u003c/b>\u003c/p>\n","text":"阿朗松 不能耽搁了，迁延会误事的。马上攻城，大家呐喊：“太子万岁！”把守兵们立刻干掉。（全体入城。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00444","html":"\u003cp class=\"epub-block1\">鼓角声。塔尔博在混战中上场。\u003c/p>\n","text":"鼓角声。塔尔博在混战中上场。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00445","html":"\u003cp class=\"epub-calibre1\">塔尔博 法兰西呀，你施用诡计，不要自鸣得意，只要塔尔博还活着，以后你要懊悔不迭、痛哭流涕的。那贞德巫婆，趁我们冷不防，搞了一个鬼鬼祟祟的把戏，我们几乎落到法国人的手里了。\u003cb class=\"epub-calibre3\">（下。）\u003c/b>\u003c/p>\n","text":"塔尔博 法兰西呀，你施用诡计，不要自鸣得意，只要塔尔博还活着，以后你要懊悔不迭、痛哭流涕的。那贞德巫婆，趁我们冷不防，搞了一个鬼鬼祟祟的把戏，我们几乎落到法国人的手里了。（下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00446","html":"\u003cp class=\"epub-block1\">鼓角声。两军交锋。培福病笃，卧椅中，由众兵自城中舁出。塔尔博及勃艮第率英军至城外。贞德、查理、奥尔良庶子、阿朗松及余人上城头。\u003c/p>\n","text":"鼓角声。两军交锋。培福病笃，卧椅中，由众兵自城中舁出。塔尔博及勃艮第率英军至城外。贞德、查理、奥尔良庶子、阿朗松及余人上城头。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00447","html":"\u003cp class=\"epub-calibre1\">贞德 英雄们，早安！你们要玉米粉蒸馍馍吃吗？我知道勃艮第爵爷宁可饿着肚子，决不肯再花这么大的价钱买我们的玉米。上次卖给你们的，稗子太多了。你们觉得味道如何？\u003c/p>\n","text":"贞德 英雄们，早安！你们要玉米粉蒸馍馍吃吗？我知道勃艮第爵爷宁可饿着肚子，决不肯再花这么大的价钱买我们的玉米。上次卖给你们的，稗子太多了。你们觉得味道如何？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00448","html":"\u003cp class=\"epub-calibre1\">勃艮第 恶鬼，尽你讥笑吧，不要脸的婊子！我不久就要用你自己的玉米堵住你的嘴，叫你咒骂你自己种的庄稼。\u003c/p>\n","text":"勃艮第 恶鬼，尽你讥笑吧，不要脸的婊子！我不久就要用你自己的玉米堵住你的嘴，叫你咒骂你自己种的庄稼。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00449","html":"\u003cp class=\"epub-calibre1\">查理 只怕你爵爷还没来得及那样做，先就饿死啦。\u003c/p>\n","text":"查理 只怕你爵爷还没来得及那样做，先就饿死啦。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00450","html":"\u003cp class=\"epub-calibre1\">培福 哼，我们不用空话，我们要用实际行动来报复你们的诡计。\u003c/p>\n","text":"培福 哼，我们不用空话，我们要用实际行动来报复你们的诡计。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00451","html":"\u003cp class=\"epub-calibre1\">贞德 你想干什么，老头儿？你想比枪吗？你想躺在椅子上冲锋吗？\u003c/p>\n","text":"贞德 你想干什么，老头儿？你想比枪吗？你想躺在椅子上冲锋吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00452","html":"\u003cp class=\"epub-calibre1\">塔尔博 法兰西的恶鬼呀，该死的骚货呀，你给你的姘头们缠昏啦！人家已经上了年纪，况且又病到这个样子，你还挖苦他，是应该的吗？雌儿，我要和你再较量一次，不然的话，塔尔博是死不瞑目的。\u003c/p>\n","text":"塔尔博 法兰西的恶鬼呀，该死的骚货呀，你给你的姘头们缠昏啦！人家已经上了年纪，况且又病到这个样子，你还挖苦他，是应该的吗？雌儿，我要和你再较量一次，不然的话，塔尔博是死不瞑目的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00453","html":"\u003cp class=\"epub-calibre1\">贞德 将军，你何必发这么大脾气？你看贞德还是心平气和的。塔尔博一发雷霆，跟着就要来倾盆大雨啦。\u003cb class=\"epub-calibre3\">（塔尔博和英军将领互相耳语，商量对策。）\u003c/b>\u003c/p>\n","text":"贞德 将军，你何必发这么大脾气？你看贞德还是心平气和的。塔尔博一发雷霆，跟着就要来倾盆大雨啦。（塔尔博和英军将领互相耳语，商量对策。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00454","html":"\u003cp class=\"epub-calibre1\">贞德 祝你们的议会顺利进行！你们当中谁要发言？\u003c/p>\n","text":"贞德 祝你们的议会顺利进行！你们当中谁要发言？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00455","html":"\u003cp class=\"epub-calibre1\">塔尔博 你敢出城和我们交战吗？\u003c/p>\n","text":"塔尔博 你敢出城和我们交战吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00456","html":"\u003cp class=\"epub-calibre1\">贞德 你这位大人大概把我们都当作傻子，一定要掂一掂我们的分量。\u003c/p>\n","text":"贞德 你这位大人大概把我们都当作傻子，一定要掂一掂我们的分量。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00457","html":"\u003cp class=\"epub-calibre1\">塔尔博 我不跟那贫嘴的女妖说话，我是对你，阿朗松，和其余的人说的。你们敢不敢像堂堂的军人那样，出城和我们决一死战？\u003c/p>\n","text":"塔尔博 我不跟那贫嘴的女妖说话，我是对你，阿朗松，和其余的人说的。你们敢不敢像堂堂的军人那样，出城和我们决一死战？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00458","html":"\u003cp class=\"epub-calibre1\">阿朗松 回禀大人，我们不来。\u003c/p>\n","text":"阿朗松 回禀大人，我们不来。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00459","html":"\u003cp class=\"epub-calibre1\">塔尔博 大人，上吊吧！下流的法国骡夫们！你们只能躲在城里装蒜，没有胆量做上等人，和我们比一比高低。\u003c/p>\n","text":"塔尔博 大人，上吊吧！下流的法国骡夫们！你们只能躲在城里装蒜，没有胆量做上等人，和我们比一比高低。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00460","html":"\u003cp class=\"epub-calibre1\">贞德 走吧，将军们！我们下城去。看塔尔博的样子，是不怀好意的。大人，愿上帝保佑你。我们跟你见面，不过是告诉你，我们已经在这儿了。\u003cb class=\"epub-calibre3\">（从城头同下。）\u003c/b>\u003c/p>\n","text":"贞德 走吧，将军们！我们下城去。看塔尔博的样子，是不怀好意的。大人，愿上帝保佑你。我们跟你见面，不过是告诉你，我们已经在这儿了。（从城头同下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00461","html":"\u003cp class=\"epub-calibre1\">塔尔博 你放心，我们不久也要来的，要不然，塔尔博就枉有盖世的英名了！勃艮第，请你用你家族的荣誉起誓，为了报复你在法国受到的公开侮辱，一定要拼着命把这座城池夺回来。至于我，我发誓一定要拼着命把这座城池夺回来，我的誓言就像亨利王好端端地活着、先王是这片国土的征服者、伟大的狮心王理查的遗骸埋葬在这座新近丧失的城池内一样真实，没有一点儿虚假。\u003c/p>\n","text":"塔尔博 你放心，我们不久也要来的，要不然，塔尔博就枉有盖世的英名了！勃艮第，请你用你家族的荣誉起誓，为了报复你在法国受到的公开侮辱，一定要拼着命把这座城池夺回来。至于我，我发誓一定要拼着命把这座城池夺回来，我的誓言就像亨利王好端端地活着、先王是这片国土的征服者、伟大的狮心王理查的遗骸埋葬在这座新近丧失的城池内一样真实，没有一点儿虚假。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00462","html":"\u003cp class=\"epub-calibre1\">勃艮第 你说的誓言也就是我们两人说的。\u003c/p>\n","text":"勃艮第 你说的誓言也就是我们两人说的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00463","html":"\u003cp class=\"epub-calibre1\">塔尔博 我们开仗以前，让我先把这位垂危的老将军培福公爵安顿一下。老公爷，我想把您送到一个比较舒适的地方，好让您安心养病。\u003c/p>\n","text":"塔尔博 我们开仗以前，让我先把这位垂危的老将军培福公爵安顿一下。老公爷，我想把您送到一个比较舒适的地方，好让您安心养病。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00464","html":"\u003cp class=\"epub-calibre1\">培福 塔尔博将军，你那样是跟我过不去了。我决定坐在卢昂城的前面，和你们同生共死。\u003c/p>\n","text":"培福 塔尔博将军，你那样是跟我过不去了。我决定坐在卢昂城的前面，和你们同生共死。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00465","html":"\u003cp class=\"epub-calibre1\">勃艮第 英勇的爵爷，还是请您俯允我们的请求吧。\u003c/p>\n","text":"勃艮第 英勇的爵爷，还是请您俯允我们的请求吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00466","html":"\u003cp class=\"epub-calibre1\">培福 我决不离开这里。我在史书上读到过，从前亚瑟王的父亲彭德拉贡曾抱病来到阵前，打败敌人。我想我平日和士兵们情同骨肉，我留在这里，一定能鼓舞士气。\u003c/p>\n","text":"培福 我决不离开这里。我在史书上读到过，从前亚瑟王的父亲彭德拉贡曾抱病来到阵前，打败敌人。我想我平日和士兵们情同骨肉，我留在这里，一定能鼓舞士气。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00467","html":"\u003cp class=\"epub-calibre1\">塔尔博 好一位视死如归的老英雄！就这么办吧。愿上天保佑培福爵爷平安无事！勇敢的勃艮第将军，现在没有别的，马上集合队伍，发动进攻。\u003cb class=\"epub-calibre3\">（只培福及其侍从留在场上，余人同下。）\u003c/b>\u003c/p>\n","text":"塔尔博 好一位视死如归的老英雄！就这么办吧。愿上天保佑培福爵爷平安无事！勇敢的勃艮第将军，现在没有别的，马上集合队伍，发动进攻。（只培福及其侍从留在场上，余人同下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00468","html":"\u003cp class=\"epub-block1\">鼓角声。两军混战。在混战中约翰·福斯托夫及队长上。\u003c/p>\n","text":"鼓角声。两军混战。在混战中约翰·福斯托夫及队长上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00469","html":"\u003cp class=\"epub-calibre1\">队长 福斯托夫爵士，您急急忙忙往哪儿去？\u003c/p>\n","text":"队长 福斯托夫爵士，您急急忙忙往哪儿去？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00470","html":"\u003cp class=\"epub-calibre1\">福斯托夫 往哪儿去！逃命要紧，我们又要吃败仗了。\u003c/p>\n","text":"福斯托夫 往哪儿去！逃命要紧，我们又要吃败仗了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00471","html":"\u003cp class=\"epub-calibre1\">队长 什么！您想逃，撇下塔尔博爵爷不管？\u003c/p>\n","text":"队长 什么！您想逃，撇下塔尔博爵爷不管？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00472","html":"\u003cp class=\"epub-calibre1\">福斯托夫 是的，不论有多少个塔尔博爵爷，我也管不了，保住我自己的性命是第一。\u003cb class=\"epub-calibre3\">（下。）\u003c/b>\u003c/p>\n","text":"福斯托夫 是的，不论有多少个塔尔博爵爷，我也管不了，保住我自己的性命是第一。（下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00473","html":"\u003cp class=\"epub-calibre1\">队长 胆小的骑士呵！但愿你到处碰壁！\u003cb class=\"epub-calibre3\">（下。）\u003c/b>\u003c/p>\n","text":"队长 胆小的骑士呵！但愿你到处碰壁！（下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00474","html":"\u003cp class=\"epub-block1\">吹退军号。兵士混战。贞德、阿朗松及查理等自城中逃出，过场下。\u003c/p>\n","text":"吹退军号。兵士混战。贞德、阿朗松及查理等自城中逃出，过场下。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00475","html":"\u003cp class=\"epub-calibre1\">培福 平静的灵魂，现在可以遵从天意，离去尘世了。我已经看到敌人的失败。愚而好自用，有什么结果？不久以前还说大话、挖苦别人的人，现在也急于逃命了。\u003cb class=\"epub-calibre3\">（培福死于椅中，两人舁下。）\u003c/b>\u003c/p>\n","text":"培福 平静的灵魂，现在可以遵从天意，离去尘世了。我已经看到敌人的失败。愚而好自用，有什么结果？不久以前还说大话、挖苦别人的人，现在也急于逃命了。（培福死于椅中，两人舁下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00476","html":"\u003cp class=\"epub-block1\">鼓角声。塔尔博、勃艮第及余人重上。\u003c/p>\n","text":"鼓角声。塔尔博、勃艮第及余人重上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00477","html":"\u003cp class=\"epub-calibre1\">塔尔博 一天之内，失而复得！这是双倍的荣誉，勃艮第。这次的胜利，真是托天之福。\u003c/p>\n","text":"塔尔博 一天之内，失而复得！这是双倍的荣誉，勃艮第。这次的胜利，真是托天之福。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00478","html":"\u003cp class=\"epub-calibre1\">勃艮第 骁勇善战的塔尔博，我对你是五体投地，不胜敬佩，我要将你的崇高业绩，永铭心版。\u003c/p>\n","text":"勃艮第 骁勇善战的塔尔博，我对你是五体投地，不胜敬佩，我要将你的崇高业绩，永铭心版。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00479","html":"\u003cp class=\"epub-calibre1\">塔尔博 谢谢，温良的公爵。那贞德哪里去了？我想她的老相好大概是睡着了。奥尔良庶子的俏皮话、查理的刻薄话，怎么都不响了？怎么，都没精打采了吗？那一帮好汉们都已逃之夭夭，害得卢昂伤心得抬不起头了。现在我们留下几名干练的官员，把城里的秩序整顿一下，随后就前往巴黎去见王上，因为我们的幼主和他的廷臣们都已驻扎在那里了。\u003c/p>\n","text":"塔尔博 谢谢，温良的公爵。那贞德哪里去了？我想她的老相好大概是睡着了。奥尔良庶子的俏皮话、查理的刻薄话，怎么都不响了？怎么，都没精打采了吗？那一帮好汉们都已逃之夭夭，害得卢昂伤心得抬不起头了。现在我们留下几名干练的官员，把城里的秩序整顿一下，随后就前往巴黎去见王上，因为我们的幼主和他的廷臣们都已驻扎在那里了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00480","html":"\u003cp class=\"epub-calibre1\">勃艮第 塔尔博爵爷怎么说，就怎么办。\u003c/p>\n","text":"勃艮第 塔尔博爵爷怎么说，就怎么办。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00481","html":"\u003cp class=\"epub-calibre1\">塔尔博 不过在我们动身以前，不要忘了新近逝世的培福公爵，我们得把他的丧礼在卢昂举行。他生前确是一位杰出的军人，一位心地和善的大臣，可是王侯将相总不免一死，悲惨的人生，总是如此结局的呵。\u003cb class=\"epub-calibre3\">（同下。）\u003c/b>\u003c/p>\n","text":"塔尔博 不过在我们动身以前，不要忘了新近逝世的培福公爵，我们得把他的丧礼在卢昂举行。他生前确是一位杰出的军人，一位心地和善的大臣，可是王侯将相总不免一死，悲惨的人生，总是如此结局的呵。（同下。）\n","sourceAnchor":null,"tag":"p"}],"heading":"第二场 法国。卢昂城前","headingLevel":4,"sourceAnchor":"a474","actNumber":3,"sceneNumber":2},{"id":"part0022-section-017","label":"第三幕 · 第三场 同前。卢昂附近平原","kind":"scene","blocks":[{"id":"part0022-00482","html":"\u003ch4 id=\"epub-part0022-a475\" class=\"epub-calibre12\">第三场 同前。卢昂附近平原\u003c/h4>\n","text":"第三场 同前。卢昂附近平原\n","sourceAnchor":"a475","tag":"h4"},{"id":"part0022-00483","html":"\u003cp class=\"epub-block1\">查理、奥尔良庶子、阿朗松、贞德率队伍上。\u003c/p>\n","text":"查理、奥尔良庶子、阿朗松、贞德率队伍上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00484","html":"\u003cp class=\"epub-calibre1\">贞德 兵家偶然胜败，不足挂怀。众位贵人，不必因为卢昂一城的得失，就心灰意懒。对于已成之局，徒然悲伤，非但无益，而且有损。别看狂妄的塔尔博暂时趾高气扬，像一只孔雀摇晃着尾巴，我们不久就要拔掉他的羽毛，剪除他的羽翼。只要太子和诸公慎重行事，定能成功。\u003c/p>\n","text":"贞德 兵家偶然胜败，不足挂怀。众位贵人，不必因为卢昂一城的得失，就心灰意懒。对于已成之局，徒然悲伤，非但无益，而且有损。别看狂妄的塔尔博暂时趾高气扬，像一只孔雀摇晃着尾巴，我们不久就要拔掉他的羽毛，剪除他的羽翼。只要太子和诸公慎重行事，定能成功。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00485","html":"\u003cp class=\"epub-calibre1\">查理 我们一向都是依从贤卿的策划的，你足智多谋，我们完全信赖。决不因为一次失利，就有所怀疑。\u003c/p>\n","text":"查理 我们一向都是依从贤卿的策划的，你足智多谋，我们完全信赖。决不因为一次失利，就有所怀疑。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00486","html":"\u003cp class=\"epub-calibre1\">庶子 请你再定下巧计，我们一定使你名扬天下。\u003c/p>\n","text":"庶子 请你再定下巧计，我们一定使你名扬天下。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00487","html":"\u003cp class=\"epub-calibre1\">阿朗松 我们要选一处俗尘不染的地方，为你建立雕像，把你当作一位圣贤，向你膜拜顶礼。贤德的贞女，望你为我们多多造福。\u003c/p>\n","text":"阿朗松 我们要选一处俗尘不染的地方，为你建立雕像，把你当作一位圣贤，向你膜拜顶礼。贤德的贞女，望你为我们多多造福。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00488","html":"\u003cp class=\"epub-calibre1\">贞德 既蒙列位大人谆谆嘱托，我自当竭力效劳。有一计策在此，不知是否符合尊意。要想削弱塔尔博的势力，必须使他和勃艮第分离，我想用甜言蜜语，把勃艮第拉拢过来，塔尔博就孤立无援了。\u003c/p>\n","text":"贞德 既蒙列位大人谆谆嘱托，我自当竭力效劳。有一计策在此，不知是否符合尊意。要想削弱塔尔博的势力，必须使他和勃艮第分离，我想用甜言蜜语，把勃艮第拉拢过来，塔尔博就孤立无援了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00489","html":"\u003cp class=\"epub-calibre1\">查理 真是一条妙计。如果勃艮第归顺过来，亨利的军队在法国一定站不住脚，他就休想吞并我们的国土，我们一定能把他赶出国境。\u003c/p>\n","text":"查理 真是一条妙计。如果勃艮第归顺过来，亨利的军队在法国一定站不住脚，他就休想吞并我们的国土，我们一定能把他赶出国境。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00490","html":"\u003cp class=\"epub-calibre1\">阿朗松 我们要将他们永远赶走，即便他们想在法国得到一块采邑，我们也断断不能答应。\u003c/p>\n","text":"阿朗松 我们要将他们永远赶走，即便他们想在法国得到一块采邑，我们也断断不能答应。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00491","html":"\u003cp class=\"epub-calibre1\">贞德 列位大人等着看吧，我一定使这条计策圆满成功。\u003cb class=\"epub-calibre3\">（远处鼓声）\u003c/b>听，从这鼓声里可以听得出英国军队是向巴黎进发。\u003c/p>\n","text":"贞德 列位大人等着看吧，我一定使这条计策圆满成功。（远处鼓声）听，从这鼓声里可以听得出英国军队是向巴黎进发。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00492","html":"\u003cp class=\"epub-block1\">内吹英军进军号。塔尔博率队上，在远处绕场下。\u003c/p>\n","text":"内吹英军进军号。塔尔博率队上，在远处绕场下。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00493","html":"\u003cp class=\"epub-calibre1\">贞德 塔尔博走过去了，那是他的军旗在飘扬，后面走的是他全部的英国军队。\u003c/p>\n","text":"贞德 塔尔博走过去了，那是他的军旗在飘扬，后面走的是他全部的英国军队。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00494","html":"\u003cp class=\"epub-block1\">内吹法国进军号。勃艮第率队上。\u003c/p>\n","text":"内吹法国进军号。勃艮第率队上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00495","html":"\u003cp class=\"epub-calibre1\">贞德 这后面的队伍是勃艮第和他的部属。他的队伍落在后边，真是天假其便。赶快吹起召开谈判的号音，我们要和他会谈。\u003cb class=\"epub-calibre3\">（内吹召开谈判的号音。）\u003c/b>\u003c/p>\n","text":"贞德 这后面的队伍是勃艮第和他的部属。他的队伍落在后边，真是天假其便。赶快吹起召开谈判的号音，我们要和他会谈。（内吹召开谈判的号音。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00496","html":"\u003cp class=\"epub-calibre1\">查理 我们要求和勃艮第公爵会谈！\u003c/p>\n","text":"查理 我们要求和勃艮第公爵会谈！\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00497","html":"\u003cp class=\"epub-calibre1\">勃艮第 谁要和我会谈？\u003c/p>\n","text":"勃艮第 谁要和我会谈？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00498","html":"\u003cp class=\"epub-calibre1\">贞德 是法国查理太子，你的同胞。\u003c/p>\n","text":"贞德 是法国查理太子，你的同胞。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00499","html":"\u003cp class=\"epub-calibre1\">勃艮第 查理，你有什么话要说？我要向别处出发了。\u003c/p>\n","text":"勃艮第 查理，你有什么话要说？我要向别处出发了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00500","html":"\u003cp class=\"epub-calibre1\">查理 贞德，你说呀，快用言语打动他。\u003c/p>\n","text":"查理 贞德，你说呀，快用言语打动他。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00501","html":"\u003cp class=\"epub-calibre1\">贞德 英勇的勃艮第将军，法兰西的救星哟！请你暂停一会儿，容许你的卑微的侍婢向你说几句话。\u003c/p>\n","text":"贞德 英勇的勃艮第将军，法兰西的救星哟！请你暂停一会儿，容许你的卑微的侍婢向你说几句话。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00502","html":"\u003cp class=\"epub-calibre1\">勃艮第 有话快说，不要过于絮叨。\u003c/p>\n","text":"勃艮第 有话快说，不要过于絮叨。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00503","html":"\u003cp class=\"epub-calibre1\">贞德 请你看看你的祖国，看看富饶的法兰西，这许多名城大邑，被残暴的敌人践踏到什么地步了。你好比是一位母亲，眼见自己的无辜的婴儿，命在旦夕，不久即将合上幼嫩的眼睛，你心里不觉得难过吗？你看，颠连困苦的法兰西，现在已经遍体鳞伤，最可叹的是，这些创伤，有许多是你亲手造成的。唉，倒转你的矛头吧。你要分清敌我，不要把亲人当作仇人呀。从祖国胸怀刺出的一滴血，会比千万个外国人的血流成河，更使人触目惊心。回到祖国怀抱里来吧。用你如同涌泉一般的泪水，洗净祖国身上的污痕吧。\u003c/p>\n","text":"贞德 请你看看你的祖国，看看富饶的法兰西，这许多名城大邑，被残暴的敌人践踏到什么地步了。你好比是一位母亲，眼见自己的无辜的婴儿，命在旦夕，不久即将合上幼嫩的眼睛，你心里不觉得难过吗？你看，颠连困苦的法兰西，现在已经遍体鳞伤，最可叹的是，这些创伤，有许多是你亲手造成的。唉，倒转你的矛头吧。你要分清敌我，不要把亲人当作仇人呀。从祖国胸怀刺出的一滴血，会比千万个外国人的血流成河，更使人触目惊心。回到祖国怀抱里来吧。用你如同涌泉一般的泪水，洗净祖国身上的污痕吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00504","html":"\u003cp class=\"epub-calibre1\">勃艮第 我是怎么的？是她这番话使我着了魔吗？还是我的爱国天性使我动摇了呢？\u003c/p>\n","text":"勃艮第 我是怎么的？是她这番话使我着了魔吗？还是我的爱国天性使我动摇了呢？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00505","html":"\u003cp class=\"epub-calibre1\">贞德 我还要告诉你，整个法兰西，全体法国人民，都在奇怪，你到底是哪一国的人。你甘心为它服务的那个国家，无非是利用你来增进它的利益，它却对你毫无信任之心。现在塔尔博把你当作逞凶的工具，可是一旦他在法国立定脚跟，法国成为英王亨利的天下，他就会把你一脚踢出去的。我提醒你一件事，这桩事可以证明我的话。那奥尔良公爵不是你的仇人吗？他原先不是被英国人拘禁着的吗？可是英国人一听说他是你的仇人，就立即将他释放，连赎金都不要，这不是有心对你和你的朋友过不去吗？想一想吧，你何苦自绝于祖国，反替异族效劳？只怕有一天鸟尽弓藏，你自己也不免受他人宰割。来吧，归来吧！迷途的将军，急速归来，查理太子和所有的法国官兵都等候着和你拥抱呢。\u003c/p>\n","text":"贞德 我还要告诉你，整个法兰西，全体法国人民，都在奇怪，你到底是哪一国的人。你甘心为它服务的那个国家，无非是利用你来增进它的利益，它却对你毫无信任之心。现在塔尔博把你当作逞凶的工具，可是一旦他在法国立定脚跟，法国成为英王亨利的天下，他就会把你一脚踢出去的。我提醒你一件事，这桩事可以证明我的话。那奥尔良公爵不是你的仇人吗？他原先不是被英国人拘禁着的吗？可是英国人一听说他是你的仇人，就立即将他释放，连赎金都不要，这不是有心对你和你的朋友过不去吗？想一想吧，你何苦自绝于祖国，反替异族效劳？只怕有一天鸟尽弓藏，你自己也不免受他人宰割。来吧，归来吧！迷途的将军，急速归来，查理太子和所有的法国官兵都等候着和你拥抱呢。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00506","html":"\u003cp class=\"epub-calibre1\">勃艮第 我被征服了，她这些义正辞严的话攻进我的心坎，比强烈的炮火更加厉害，使我几乎要匍匐在地了。祖国呀，亲爱的同胞呀，宽恕我吧；列位大人，接受我的衷心拥抱吧。我率领全部军队听候你们指挥。再会，塔尔博，我不再信赖你了。\u003c/p>\n","text":"勃艮第 我被征服了，她这些义正辞严的话攻进我的心坎，比强烈的炮火更加厉害，使我几乎要匍匐在地了。祖国呀，亲爱的同胞呀，宽恕我吧；列位大人，接受我的衷心拥抱吧。我率领全部军队听候你们指挥。再会，塔尔博，我不再信赖你了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00507","html":"\u003cp class=\"epub-calibre1\">贞德 真像一个法国人干的，今天吃东家，明天吃西家，说变卦，就变卦。\u003c/p>\n","text":"贞德 真像一个法国人干的，今天吃东家，明天吃西家，说变卦，就变卦。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00508","html":"\u003cp class=\"epub-calibre1\">查理 欢迎你，勇敢的公爵！你的友谊给我们以极大鼓舞。\u003c/p>\n","text":"查理 欢迎你，勇敢的公爵！你的友谊给我们以极大鼓舞。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00509","html":"\u003cp class=\"epub-calibre1\">庶子 使我们的心头平添了一股勇气。\u003c/p>\n","text":"庶子 使我们的心头平添了一股勇气。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00510","html":"\u003cp class=\"epub-calibre1\">阿朗松 这件事贞德办得真出色，若是赐给她一顶金冠，她也可受之无愧。\u003c/p>\n","text":"阿朗松 这件事贞德办得真出色，若是赐给她一顶金冠，她也可受之无愧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00511","html":"\u003cp class=\"epub-calibre1\">查理 众位贤卿，发动我们的队伍，和勃艮第一同进军，彻底击败敌人。\u003cb class=\"epub-calibre3\">（同下。）\u003c/b>\u003c/p>\n","text":"查理 众位贤卿，发动我们的队伍，和勃艮第一同进军，彻底击败敌人。（同下。）\n","sourceAnchor":null,"tag":"p"}],"heading":"第三场 同前。卢昂附近平原","headingLevel":4,"sourceAnchor":"a475","actNumber":3,"sceneNumber":3},{"id":"part0022-section-018","label":"第三幕 · 第四场 巴黎。宫中一室","kind":"scene","blocks":[{"id":"part0022-00512","html":"\u003ch4 id=\"epub-part0022-a476\" class=\"epub-calibre12\">第四场 巴黎。宫中一室\u003c/h4>\n","text":"第四场 巴黎。宫中一室\n","sourceAnchor":"a476","tag":"h4"},{"id":"part0022-00513","html":"\u003cp class=\"epub-block1\">亨利王、葛罗斯特、温彻斯特、约克、萨福克、萨穆塞特、华列克、爱克塞特；凡农、巴塞特及余人上。塔尔博率兵士来见。\u003c/p>\n","text":"亨利王、葛罗斯特、温彻斯特、约克、萨福克、萨穆塞特、华列克、爱克塞特；凡农、巴塞特及余人上。塔尔博率兵士来见。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00514","html":"\u003cp class=\"epub-calibre1\">塔尔博 吾王陛下，列位大人。我听到您来到这里的消息，就把战事暂时停止，特地赶来向陛下致敬。我曾用这条臂膊替吾王克服了五十座城堡，十二个城市，七处坚强的城池，还俘获了五百名高级将领。为了表示我的敬意，我用同一条臂膊将我的佩剑放到王上的脚前，\u003cb class=\"epub-calibre3\">（跪）\u003c/b>并以恭顺的忠忱，将战绩的光荣，献给上帝和吾王陛下。\u003c/p>\n","text":"塔尔博 吾王陛下，列位大人。我听到您来到这里的消息，就把战事暂时停止，特地赶来向陛下致敬。我曾用这条臂膊替吾王克服了五十座城堡，十二个城市，七处坚强的城池，还俘获了五百名高级将领。为了表示我的敬意，我用同一条臂膊将我的佩剑放到王上的脚前，（跪）并以恭顺的忠忱，将战绩的光荣，献给上帝和吾王陛下。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00515","html":"\u003cp class=\"epub-calibre1\">亨利王 葛罗斯特叔父，这位将军就是长期转战在法兰西的塔尔博勋爵吗？\u003c/p>\n","text":"亨利王 葛罗斯特叔父，这位将军就是长期转战在法兰西的塔尔博勋爵吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00516","html":"\u003cp class=\"epub-calibre1\">葛罗斯特 吾王鉴察，这就是他。\u003c/p>\n","text":"葛罗斯特 吾王鉴察，这就是他。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00517","html":"\u003cp class=\"epub-calibre1\">亨利王 欢迎你，百战百胜的将军！我现在还年轻，但我从小就听我父王说你是一员超群绝伦的名将。近年来，我们更确实知道，你是赤忱为国，劳苦功高。只因迄今尚未和你见面，未能给你以应得的封赏。现在请你站起来，为了酬庸你的功绩，特封你为索鲁斯伯雷伯爵，并准你参加我的加冕典礼。\u003cb class=\"epub-calibre3\">（喇叭奏花腔。除凡农及巴塞特外俱下。）\u003c/b>\u003c/p>\n","text":"亨利王 欢迎你，百战百胜的将军！我现在还年轻，但我从小就听我父王说你是一员超群绝伦的名将。近年来，我们更确实知道，你是赤忱为国，劳苦功高。只因迄今尚未和你见面，未能给你以应得的封赏。现在请你站起来，为了酬庸你的功绩，特封你为索鲁斯伯雷伯爵，并准你参加我的加冕典礼。（喇叭奏花腔。除凡农及巴塞特外俱下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00518","html":"\u003cp class=\"epub-calibre1\">凡农 我对你说，你在渡海的时候对我那样无礼，竟敢糟蹋我为表示对约克公爵的敬意而佩戴的花朵，你那时说过的话，现在还敢坚持吗？\u003c/p>\n","text":"凡农 我对你说，你在渡海的时候对我那样无礼，竟敢糟蹋我为表示对约克公爵的敬意而佩戴的花朵，你那时说过的话，现在还敢坚持吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00519","html":"\u003cp class=\"epub-calibre1\">巴塞特 当然坚持。你那天用你刁滑的舌头，说了我的主人萨穆塞特爵爷许多坏话。你不改口，我为什么要改口？\u003c/p>\n","text":"巴塞特 当然坚持。你那天用你刁滑的舌头，说了我的主人萨穆塞特爵爷许多坏话。你不改口，我为什么要改口？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00520","html":"\u003cp class=\"epub-calibre1\">凡农 你的东家是个什么样的人，我就按照什么样子对待他。\u003c/p>\n","text":"凡农 你的东家是个什么样的人，我就按照什么样子对待他。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00521","html":"\u003cp class=\"epub-calibre1\">巴塞特 你说他是什么样的人？我东家总不见得比不上约克。\u003c/p>\n","text":"巴塞特 你说他是什么样的人？我东家总不见得比不上约克。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00522","html":"\u003cp class=\"epub-calibre1\">凡农 你听着，我说他比不上。为了证明我的话，叫你吃一拳。\u003cb class=\"epub-calibre3\">（打巴塞特。）\u003c/b>\u003c/p>\n","text":"凡农 你听着，我说他比不上。为了证明我的话，叫你吃一拳。（打巴塞特。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00523","html":"\u003cp class=\"epub-calibre1\">巴塞特 混账东西，你知道宫廷里的规矩，不准比剑，违者立即处死，不然的话，我一剑就砍出你的血来。我要去见王上，请他批准我雪耻的权利，到那时我们再碰头，叫你知道我的厉害。\u003c/p>\n","text":"巴塞特 混账东西，你知道宫廷里的规矩，不准比剑，违者立即处死，不然的话，我一剑就砍出你的血来。我要去见王上，请他批准我雪耻的权利，到那时我们再碰头，叫你知道我的厉害。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00524","html":"\u003cp class=\"epub-calibre1\">凡农 好吧，恶棍，我也去见王上，以后要碰头，我比你更早到。\u003cb class=\"epub-calibre3\">（各下。）\u003c/b>\u003c/p>\n","text":"凡农 好吧，恶棍，我也去见王上，以后要碰头，我比你更早到。（各下。）\n","sourceAnchor":null,"tag":"p"}],"heading":"第四场 巴黎。宫中一室","headingLevel":4,"sourceAnchor":"a476","actNumber":3,"sceneNumber":4},{"id":"part0022-section-019","label":"第四幕","kind":"act","blocks":[{"id":"part0022-00525","html":"\u003ch3 id=\"epub-part0022-a477\" class=\"epub-calibre11\">第四幕\u003c/h3>\n","text":"第四幕\n","sourceAnchor":"a477","tag":"h3"}],"heading":"第四幕","headingLevel":3,"sourceAnchor":"a477","actNumber":4},{"id":"part0022-section-020","label":"第四幕 · 第一场 巴黎。宫中正殿","kind":"scene","blocks":[{"id":"part0022-00526","html":"\u003ch4 id=\"epub-part0022-a478\" class=\"epub-calibre12\">第一场 巴黎。宫中正殿\u003c/h4>\n","text":"第一场 巴黎。宫中正殿\n","sourceAnchor":"a478","tag":"h4"},{"id":"part0022-00527","html":"\u003cp class=\"epub-block1\">亨利王、葛罗斯特、爱克塞特、约克、萨福克、萨穆塞特、温彻斯特主教、华列克、塔尔博、巴黎市长及余人上。\u003c/p>\n","text":"亨利王、葛罗斯特、爱克塞特、约克、萨福克、萨穆塞特、温彻斯特主教、华列克、塔尔博、巴黎市长及余人上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00528","html":"\u003cp class=\"epub-calibre1\">葛罗斯特 主教大人，请为王上加冕。\u003c/p>\n","text":"葛罗斯特 主教大人，请为王上加冕。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00529","html":"\u003cp class=\"epub-calibre1\">温彻斯特 愿上帝保佑吾王亨利六世！\u003c/p>\n","text":"温彻斯特 愿上帝保佑吾王亨利六世！\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00530","html":"\u003cp class=\"epub-calibre1\">葛罗斯特 来，巴黎市长，你来宣誓。\u003cb class=\"epub-calibre3\">（市长跪）\u003c/b>你要立誓除亨利六世陛下以外，决不拥戴别人为王；凡是拥护他的，就是你的朋友，凡是阴谋背叛他的政权的，就是你的敌人。你必须恪遵誓言，上帝就赐福给你。\u003cb class=\"epub-calibre3\">（市长及随员下。）\u003c/b>\u003c/p>\n","text":"葛罗斯特 来，巴黎市长，你来宣誓。（市长跪）你要立誓除亨利六世陛下以外，决不拥戴别人为王；凡是拥护他的，就是你的朋友，凡是阴谋背叛他的政权的，就是你的敌人。你必须恪遵誓言，上帝就赐福给你。（市长及随员下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00531","html":"\u003cp class=\"epub-block1\">约翰·福斯托夫上。\u003c/p>\n","text":"约翰·福斯托夫上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00532","html":"\u003cp class=\"epub-calibre1\">福斯托夫 吾王陛下，我从卡莱赶来参加您的加冕大典，在路上接到一封信，是勃艮第公爵写给您的。\u003c/p>\n","text":"福斯托夫 吾王陛下，我从卡莱赶来参加您的加冕大典，在路上接到一封信，是勃艮第公爵写给您的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00533","html":"\u003cp class=\"epub-calibre1\">塔尔博 你和勃艮第两个不顾廉耻的人！我已经立过誓，卑鄙的骑士，我若碰到你，定要把你骑士职位的绶带从你这懦夫的腿上剥下来。\u003cb class=\"epub-calibre3\">（扯去其绶带）\u003c/b>因为你不配享有这种高贵的头衔，所以我剥下它。陛下，众位大人，请恕我鲁莽，只因这个胆小鬼，在帕台开仗的时候，我军只有六千人，法军人数比我方多十倍，双方还未交锋，还未动手打，这家伙就逃得不知去向了。这一仗我军损失了一千二百人，我本人和好几位其他将领受到袭击，成了俘虏。众位大人，请你们公断，我该不该这样做，像他这样的懦夫有没有资格佩戴骑士的绶带。\u003c/p>\n","text":"塔尔博 你和勃艮第两个不顾廉耻的人！我已经立过誓，卑鄙的骑士，我若碰到你，定要把你骑士职位的绶带从你这懦夫的腿上剥下来。（扯去其绶带）因为你不配享有这种高贵的头衔，所以我剥下它。陛下，众位大人，请恕我鲁莽，只因这个胆小鬼，在帕台开仗的时候，我军只有六千人，法军人数比我方多十倍，双方还未交锋，还未动手打，这家伙就逃得不知去向了。这一仗我军损失了一千二百人，我本人和好几位其他将领受到袭击，成了俘虏。众位大人，请你们公断，我该不该这样做，像他这样的懦夫有没有资格佩戴骑士的绶带。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00534","html":"\u003cp class=\"epub-calibre1\">葛罗斯特 说实话，这种行为，即便出自一个寻常的老百姓，也是可耻的，何况他是一个骑士，还是一个带队的军官。\u003c/p>\n","text":"葛罗斯特 说实话，这种行为，即便出自一个寻常的老百姓，也是可耻的，何况他是一个骑士，还是一个带队的军官。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00535","html":"\u003cp class=\"epub-calibre1\">塔尔博 列位大人，当初建立这个制度的时候，佩戴绶带的骑士都是出身高贵、勇敢正直的人，他们都是身经百战、建功立业、具有豪迈的气概，他们都能临危不惧，临难不苟，在极端困苦之中，勇往直前。如果有人缺乏这种品质，混进骑士的行列，这种人就是盗窃名位，亵渎骑士的高贵称号，依我看来，我们对于这样的人，应该像对待一个冒充世家子弟的村夫那样，褫夺他的职衔。\u003c/p>\n","text":"塔尔博 列位大人，当初建立这个制度的时候，佩戴绶带的骑士都是出身高贵、勇敢正直的人，他们都是身经百战、建功立业、具有豪迈的气概，他们都能临危不惧，临难不苟，在极端困苦之中，勇往直前。如果有人缺乏这种品质，混进骑士的行列，这种人就是盗窃名位，亵渎骑士的高贵称号，依我看来，我们对于这样的人，应该像对待一个冒充世家子弟的村夫那样，褫夺他的职衔。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00536","html":"\u003cp class=\"epub-calibre1\">亨利王 你这英国人的败类，听候我们对你的宣判吧！我们革去你的骑士职衔，驱逐你出境，你如敢逗留，定杀不赦。\u003cb class=\"epub-calibre3\">（福斯托夫下）\u003c/b>护国公，现在请你把勃艮第公爵的来信读一下。\u003c/p>\n","text":"亨利王 你这英国人的败类，听候我们对你的宣判吧！我们革去你的骑士职衔，驱逐你出境，你如敢逗留，定杀不赦。（福斯托夫下）护国公，现在请你把勃艮第公爵的来信读一下。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00537","html":"\u003cp class=\"epub-calibre1\">葛罗斯特 \u003cb class=\"epub-calibre3\">（看到信上开头的称呼）\u003c/b>这封信的格式怎么改了，公爵的用意何在？这信一开头就是突突兀兀的一句话：“致书于英王”，没有一句恭顺的辞藻，难道他忘了他是以臣下的身份上书给君王的吗？这种粗鲁的称呼是不是表示他有反侧之意？啊呀，他写的是些什么话？\u003cb class=\"epub-calibre3\">（读信）\u003c/b>“鉴于我的国家惨遭蹂躏，你们的残暴行为已引起人民的怨愤，我决定和你们的恶势力断绝关系，归附我法国的合法国王查理。”啊呀，毫无人性的奸贼！竟有这样的事！那时的海誓山盟，竟都是一片虚情假意！\u003c/p>\n","text":"葛罗斯特 （看到信上开头的称呼）这封信的格式怎么改了，公爵的用意何在？这信一开头就是突突兀兀的一句话：“致书于英王”，没有一句恭顺的辞藻，难道他忘了他是以臣下的身份上书给君王的吗？这种粗鲁的称呼是不是表示他有反侧之意？啊呀，他写的是些什么话？（读信）“鉴于我的国家惨遭蹂躏，你们的残暴行为已引起人民的怨愤，我决定和你们的恶势力断绝关系，归附我法国的合法国王查理。”啊呀，毫无人性的奸贼！竟有这样的事！那时的海誓山盟，竟都是一片虚情假意！\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00538","html":"\u003cp class=\"epub-calibre1\">亨利王 什么！勃艮第反了吗？\u003c/p>\n","text":"亨利王 什么！勃艮第反了吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00539","html":"\u003cp class=\"epub-calibre1\">葛罗斯特 反了，陛下，他成为您的敌人了。\u003c/p>\n","text":"葛罗斯特 反了，陛下，他成为您的敌人了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00540","html":"\u003cp class=\"epub-calibre1\">亨利王 信里还有什么更坏的话吗？\u003c/p>\n","text":"亨利王 信里还有什么更坏的话吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00541","html":"\u003cp class=\"epub-calibre1\">葛罗斯特 没有了，陛下，他说的坏话就是这些。\u003c/p>\n","text":"葛罗斯特 没有了，陛下，他说的坏话就是这些。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00542","html":"\u003cp class=\"epub-calibre1\">亨利王 既然如此，我们就派遣塔尔博伯爵前去讨伐，质问他反复无常之罪。将军，你有什么意见，你愿去吗？\u003c/p>\n","text":"亨利王 既然如此，我们就派遣塔尔博伯爵前去讨伐，质问他反复无常之罪。将军，你有什么意见，你愿去吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00543","html":"\u003cp class=\"epub-calibre1\">塔尔博 愿去，陛下！若不是王上先已下了谕旨，我也要向王上讨这差使的。\u003c/p>\n","text":"塔尔博 愿去，陛下！若不是王上先已下了谕旨，我也要向王上讨这差使的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00544","html":"\u003cp class=\"epub-calibre1\">亨利王 那么你就立即集合人马前往声讨吧。你此番前去，要叫他知道，背叛朝廷，出卖朋友，该当何罪。\u003c/p>\n","text":"亨利王 那么你就立即集合人马前往声讨吧。你此番前去，要叫他知道，背叛朝廷，出卖朋友，该当何罪。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00545","html":"\u003cp class=\"epub-calibre1\">塔尔博 我这就去，陛下，我希望此番出征，仍和以往一样，把敌人杀得豕突狼奔。\u003cb class=\"epub-calibre3\">（下。）\u003c/b>\u003c/p>\n","text":"塔尔博 我这就去，陛下，我希望此番出征，仍和以往一样，把敌人杀得豕突狼奔。（下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00546","html":"\u003cp class=\"epub-block1\">凡农及巴塞特上。\u003c/p>\n","text":"凡农及巴塞特上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00547","html":"\u003cp class=\"epub-calibre1\">凡农 陛下，请批准我进行决斗。\u003c/p>\n","text":"凡农 陛下，请批准我进行决斗。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00548","html":"\u003cp class=\"epub-calibre1\">巴塞特 陛下，也请批准我进行决斗。\u003c/p>\n","text":"巴塞特 陛下，也请批准我进行决斗。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00549","html":"\u003cp class=\"epub-calibre1\">约克 这人是我的仆人，陛下，请垂听他的陈诉。\u003c/p>\n","text":"约克 这人是我的仆人，陛下，请垂听他的陈诉。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00550","html":"\u003cp class=\"epub-calibre1\">萨穆塞特 这人是我的仆人，陛下，请您赐以恩宠。\u003c/p>\n","text":"萨穆塞特 这人是我的仆人，陛下，请您赐以恩宠。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00551","html":"\u003cp class=\"epub-calibre1\">亨利王 等一等，两位贤卿，让他们说说是为了什么事。说吧，先生们，你们的争执是为了何事？你们为什么要求决斗？跟谁决斗？\u003c/p>\n","text":"亨利王 等一等，两位贤卿，让他们说说是为了什么事。说吧，先生们，你们的争执是为了何事？你们为什么要求决斗？跟谁决斗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00552","html":"\u003cp class=\"epub-calibre1\">凡农 跟他决斗，陛下，因为他得罪我了。\u003c/p>\n","text":"凡农 跟他决斗，陛下，因为他得罪我了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00553","html":"\u003cp class=\"epub-calibre1\">巴塞特 我要跟他决斗，因为他得罪我了。\u003c/p>\n","text":"巴塞特 我要跟他决斗，因为他得罪我了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00554","html":"\u003cp class=\"epub-calibre1\">亨利王 你们两人都说被得罪了，到底是为了什么事？你们先说给我听，然后我再替你们判断。\u003c/p>\n","text":"亨利王 你们两人都说被得罪了，到底是为了什么事？你们先说给我听，然后我再替你们判断。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00555","html":"\u003cp class=\"epub-calibre1\">巴塞特 我们从英国渡海到法国的时候，这个人用他刻薄的舌头，讥笑我佩戴的这朵玫瑰花。他说这红色的花瓣好比是我主人发赤的面颊，因为我主人和约克公爵曾为法律上一个理论问题争持不下，我主人曾气得面红耳赤。他还说了许多恶毒刺耳的话。为了驳斥他的无耻谰言，捍卫我主人的尊严，我要求使用比剑的权利。\u003c/p>\n","text":"巴塞特 我们从英国渡海到法国的时候，这个人用他刻薄的舌头，讥笑我佩戴的这朵玫瑰花。他说这红色的花瓣好比是我主人发赤的面颊，因为我主人和约克公爵曾为法律上一个理论问题争持不下，我主人曾气得面红耳赤。他还说了许多恶毒刺耳的话。为了驳斥他的无耻谰言，捍卫我主人的尊严，我要求使用比剑的权利。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00556","html":"\u003cp class=\"epub-calibre1\">凡农 我也正是为了请求使用比剑的权利而来，陛下。他虽然花言巧语，推诿责任，其实是他先向我挑衅的。是他首先责备我不该佩戴白花，他说这朵花惨白的颜色透露出我主人心头的怯弱。\u003c/p>\n","text":"凡农 我也正是为了请求使用比剑的权利而来，陛下。他虽然花言巧语，推诿责任，其实是他先向我挑衅的。是他首先责备我不该佩戴白花，他说这朵花惨白的颜色透露出我主人心头的怯弱。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00557","html":"\u003cp class=\"epub-calibre1\">约克 萨穆塞特，你对我的怀恨，不能和解吗？\u003c/p>\n","text":"约克 萨穆塞特，你对我的怀恨，不能和解吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00558","html":"\u003cp class=\"epub-calibre1\">萨穆塞特 我的约克爵爷，你对我何尝不恨之切骨？你虽然巧于掩饰，但是终究会暴露的。\u003c/p>\n","text":"萨穆塞特 我的约克爵爷，你对我何尝不恨之切骨？你虽然巧于掩饰，但是终究会暴露的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00559","html":"\u003cp class=\"epub-calibre1\">亨利王 我的主啊，脑筋不清的人够多么糊涂，为了一些无聊琐屑的小事，竟会闹到这样地步！约克和萨穆塞特两位好堂兄，请你们冷静一下，和和气气的吧！\u003c/p>\n","text":"亨利王 我的主啊，脑筋不清的人够多么糊涂，为了一些无聊琐屑的小事，竟会闹到这样地步！约克和萨穆塞特两位好堂兄，请你们冷静一下，和和气气的吧！\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00560","html":"\u003cp class=\"epub-calibre1\">约克 先让他们用决斗解决争端，然后再请陛下下令和解。\u003c/p>\n","text":"约克 先让他们用决斗解决争端，然后再请陛下下令和解。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00561","html":"\u003cp class=\"epub-calibre1\">萨穆塞特 这场争闹是我们两人的私事，让我们两人亲自来解决。\u003c/p>\n","text":"萨穆塞特 这场争闹是我们两人的私事，让我们两人亲自来解决。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00562","html":"\u003cp class=\"epub-calibre1\">约克 好，这是我挑战的信物，萨穆塞特，你接受我的挑战吧。\u003c/p>\n","text":"约克 好，这是我挑战的信物，萨穆塞特，你接受我的挑战吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00563","html":"\u003cp class=\"epub-calibre1\">凡农 不，谁最先要求决斗，就让谁去执行。\u003c/p>\n","text":"凡农 不，谁最先要求决斗，就让谁去执行。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00564","html":"\u003cp class=\"epub-calibre1\">巴塞特 请您同意这样办，我的尊贵的主人。\u003c/p>\n","text":"巴塞特 请您同意这样办，我的尊贵的主人。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00565","html":"\u003cp class=\"epub-calibre1\">葛罗斯特 同意这样办！闭上你争吵不休的嘴！带着你爱说大话的舌头死去吧！僭越职分的陪臣们，你们这样喧哗无礼，闹得王上和大臣们都不得安静，你们不觉得羞愧吗？两位爵爷，你们放纵家臣胡闹，我很不以为然，况且你们听了他俩的挑唆，自己也吵闹起来，那就更不成体统了。我奉劝你们不要如此。\u003c/p>\n","text":"葛罗斯特 同意这样办！闭上你争吵不休的嘴！带着你爱说大话的舌头死去吧！僭越职分的陪臣们，你们这样喧哗无礼，闹得王上和大臣们都不得安静，你们不觉得羞愧吗？两位爵爷，你们放纵家臣胡闹，我很不以为然，况且你们听了他俩的挑唆，自己也吵闹起来，那就更不成体统了。我奉劝你们不要如此。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00566","html":"\u003cp class=\"epub-calibre1\">爱克塞特 这件事叫王上不安了，两位大人，言归于好吧。\u003c/p>\n","text":"爱克塞特 这件事叫王上不安了，两位大人，言归于好吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00567","html":"\u003cp class=\"epub-calibre1\">亨利王 到这边来，你们两个要求决斗的人，你们如果希望得到我的恩遇，今后就要遵照我的谕旨，把这场争吵和引起争吵的原因，置之度外，永不再提。两位贤卿，我请你们不要忘记我们所处的环境。我们是在法兰西境内，我们的周围是一个反复无常、变化多端的民族。如果他们察言观色，知道我们内部不和，他们的叛志就会炽旺起来，进而还会兴兵作乱！还有各国的诸侯，如果他们听到英国的亲贵大臣，为了无关紧要的琐事，互相倾轧，以至丧失我们在法兰西的领土，岂不要引为笑谈！唉，望你们顾念先王创业不易，顾念我尚在冲龄，不要把先人血汗换来的基业，视同儿戏。让我把这场无谓的纠纷，替你们秉公处理。比如我戴上这一朵玫瑰。\u003cb class=\"epub-calibre3\">（戴上一朵红玫瑰）\u003c/b>我看任何人也没有理由，因此就可以揣测我是偏袒萨穆塞特，而薄视约克。你们两家都是皇族，我和你们都是骨肉至亲。犹如我这里戴上王冠，不能因为苏格兰王也戴王冠，就说我做的不对。不过我想你们都是明理之人，无须我谆谆劝导，你们自己也会省悟的。我们来的时候既是和谐无间，就让我们继续保持和谐吧。约克堂兄，我派你继任总管法国事务大臣。萨穆塞特爱卿，派你率领骑兵协助他的步兵，共同驻扎法境。望你们尽忠报国，发扬祖德。尤其要消除宿怨，戮力同心，如果你们还有余怒未息，就发泄在敌人的身上吧。我和护国公以及群臣，稍稍休息以后，就要取道卡莱回国。我希望你们不久就能生擒查理、阿朗松和其他叛贼，向我献俘。\u003cb class=\"epub-calibre3\">（喇叭奏花腔。除约克、华列克、爱克塞特、凡农外均下。）\u003c/b>\u003c/p>\n","text":"亨利王 到这边来，你们两个要求决斗的人，你们如果希望得到我的恩遇，今后就要遵照我的谕旨，把这场争吵和引起争吵的原因，置之度外，永不再提。两位贤卿，我请你们不要忘记我们所处的环境。我们是在法兰西境内，我们的周围是一个反复无常、变化多端的民族。如果他们察言观色，知道我们内部不和，他们的叛志就会炽旺起来，进而还会兴兵作乱！还有各国的诸侯，如果他们听到英国的亲贵大臣，为了无关紧要的琐事，互相倾轧，以至丧失我们在法兰西的领土，岂不要引为笑谈！唉，望你们顾念先王创业不易，顾念我尚在冲龄，不要把先人血汗换来的基业，视同儿戏。让我把这场无谓的纠纷，替你们秉公处理。比如我戴上这一朵玫瑰。（戴上一朵红玫瑰）我看任何人也没有理由，因此就可以揣测我是偏袒萨穆塞特，而薄视约克。你们两家都是皇族，我和你们都是骨肉至亲。犹如我这里戴上王冠，不能因为苏格兰王也戴王冠，就说我做的不对。不过我想你们都是明理之人，无须我谆谆劝导，你们自己也会省悟的。我们来的时候既是和谐无间，就让我们继续保持和谐吧。约克堂兄，我派你继任总管法国事务大臣。萨穆塞特爱卿，派你率领骑兵协助他的步兵，共同驻扎法境。望你们尽忠报国，发扬祖德。尤其要消除宿怨，戮力同心，如果你们还有余怒未息，就发泄在敌人的身上吧。我和护国公以及群臣，稍稍休息以后，就要取道卡莱回国。我希望你们不久就能生擒查理、阿朗松和其他叛贼，向我献俘。（喇叭奏花腔。除约克、华列克、爱克塞特、凡农外均下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00568","html":"\u003cp class=\"epub-calibre1\">华列克 约克公爵，王上这篇演说，可算得情辞并茂了。\u003c/p>\n","text":"华列克 约克公爵，王上这篇演说，可算得情辞并茂了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00569","html":"\u003cp class=\"epub-calibre1\">约克 话说得确是好，不过他为什么佩戴萨穆塞特的标记，我看了有些不受用。\u003c/p>\n","text":"约克 话说得确是好，不过他为什么佩戴萨穆塞特的标记，我看了有些不受用。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00570","html":"\u003cp class=\"epub-calibre1\">华列克 唏，那不过是出于偶然，你不要介意，我看他并无歹意。\u003c/p>\n","text":"华列克 唏，那不过是出于偶然，你不要介意，我看他并无歹意。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00571","html":"\u003cp class=\"epub-calibre1\">约克 如果我知道他有什么深意——算了，不谈吧，我们还有别的事情需要料理。\u003cb class=\"epub-calibre3\">（除爱克塞特外均下。）\u003c/b>\u003c/p>\n","text":"约克 如果我知道他有什么深意——算了，不谈吧，我们还有别的事情需要料理。（除爱克塞特外均下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00572","html":"\u003cp class=\"epub-calibre1\">爱克塞特 理查，你不说下去也好；你若把心事尽情吐露出来，只怕其中所包藏的深仇积恨，有许多是出人意表的哩。无论如何，任何普通人也看得出来，亲贵们意见分歧，互相排挤，还纵容各自的亲信遇事生风，日后总要闹出大祸来的。目今幼主在位，人心已是惶惶不安，再加上大臣们争权结党，我看分崩离析的局面，是势所难免的了。\u003cb class=\"epub-calibre3\">（下。）\u003c/b>\u003c/p>\n","text":"爱克塞特 理查，你不说下去也好；你若把心事尽情吐露出来，只怕其中所包藏的深仇积恨，有许多是出人意表的哩。无论如何，任何普通人也看得出来，亲贵们意见分歧，互相排挤，还纵容各自的亲信遇事生风，日后总要闹出大祸来的。目今幼主在位，人心已是惶惶不安，再加上大臣们争权结党，我看分崩离析的局面，是势所难免的了。（下。）\n","sourceAnchor":null,"tag":"p"}],"heading":"第一场 巴黎。宫中正殿","headingLevel":4,"sourceAnchor":"a478","actNumber":4,"sceneNumber":1},{"id":"part0022-section-021","label":"第四幕 · 第二场 波尔多城前","kind":"scene","blocks":[{"id":"part0022-00573","html":"\u003ch4 id=\"epub-part0022-a479\" class=\"epub-calibre12\">第二场 波尔多城前\u003c/h4>\n","text":"第二场 波尔多城前\n","sourceAnchor":"a479","tag":"h4"},{"id":"part0022-00574","html":"\u003cp class=\"epub-block1\">塔尔博率军队上。\u003c/p>\n","text":"塔尔博率军队上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00575","html":"\u003cp class=\"epub-calibre1\">塔尔博 号手，你去到波尔多城门口，召唤他们的统帅上城答话。\u003c/p>\n","text":"塔尔博 号手，你去到波尔多城门口，召唤他们的统帅上城答话。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00576","html":"\u003cp class=\"epub-block1\">号角吹会谈信号。法国统帅及余人上至城头。\u003c/p>\n","text":"号角吹会谈信号。法国统帅及余人上至城头。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00577","html":"\u003cp class=\"epub-calibre1\">塔尔博 将军们，现在是英王亨利陛下的司令官塔尔博向你们训话。我命令你们：敞开你们的城门，向我们俯首纳降，承认我们英国国王为你们的王上，并向他表示臣服之礼。如果你们件件依从，我就撤退我的兵马；如果你们拒绝这些议和的条款，你们就将激怒我的三个侍从：饥饿、刀兵和烈火，它们在俄顷之间就能将你们的深沟高垒夷为平地。\u003c/p>\n","text":"塔尔博 将军们，现在是英王亨利陛下的司令官塔尔博向你们训话。我命令你们：敞开你们的城门，向我们俯首纳降，承认我们英国国王为你们的王上，并向他表示臣服之礼。如果你们件件依从，我就撤退我的兵马；如果你们拒绝这些议和的条款，你们就将激怒我的三个侍从：饥饿、刀兵和烈火，它们在俄顷之间就能将你们的深沟高垒夷为平地。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00578","html":"\u003cp class=\"epub-calibre1\">统 帅 你这预兆死亡的恶毒的枭鸟，你是我们国家的灾殃！你对我们肆虐的日子快完结了。你想攻进我们的城池，你只能自取灭亡。我们不但防御坚强，我们还有强大的兵力出城和你交战。你想撤退也难逃脱，因为我们的太子，料事如神，早已设下埋伏，等你自投陷阱。四面八方全有我们的部队，赛如天罗地网，准备将你擒拿。你已大难临头，死在眼前，无论如何也不能幸免。一万名法军已在领圣餐时宣誓，他们的强烈炮火不打任何别的基督徒，专打你这英国人塔尔博。瞧，你此刻站在那里，还是一个雄赳赳、气昂昂、不可一世的英雄！可是这句颂扬的话，是我作为你的敌人最后奉送给你的，因为现在已开始运行的沙漏，在它没有走完一个时辰的行程以前，我所看到的肤色红润的你，就要变成一个干瘪瘪的、血淋淋的、面色惨白的尸体了。\u003cb class=\"epub-calibre3\">（远处战鼓声）\u003c/b>听，听！这是法国太子的战鼓，它是对你怯弱的灵魂敲起警钟，等到我的战鼓一敲响，那就是为你送终的丧钟了。\u003cb class=\"epub-calibre3\">（法国统帅及余人同下。）\u003c/b>\u003c/p>\n","text":"统 帅 你这预兆死亡的恶毒的枭鸟，你是我们国家的灾殃！你对我们肆虐的日子快完结了。你想攻进我们的城池，你只能自取灭亡。我们不但防御坚强，我们还有强大的兵力出城和你交战。你想撤退也难逃脱，因为我们的太子，料事如神，早已设下埋伏，等你自投陷阱。四面八方全有我们的部队，赛如天罗地网，准备将你擒拿。你已大难临头，死在眼前，无论如何也不能幸免。一万名法军已在领圣餐时宣誓，他们的强烈炮火不打任何别的基督徒，专打你这英国人塔尔博。瞧，你此刻站在那里，还是一个雄赳赳、气昂昂、不可一世的英雄！可是这句颂扬的话，是我作为你的敌人最后奉送给你的，因为现在已开始运行的沙漏，在它没有走完一个时辰的行程以前，我所看到的肤色红润的你，就要变成一个干瘪瘪的、血淋淋的、面色惨白的尸体了。（远处战鼓声）听，听！这是法国太子的战鼓，它是对你怯弱的灵魂敲起警钟，等到我的战鼓一敲响，那就是为你送终的丧钟了。（法国统帅及余人同下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00579","html":"\u003cp class=\"epub-calibre1\">塔尔博 他说的不是假话，我已听到敌人的行动。派几名骑兵出去侦察一下敌人两翼的情况。嗳哟，我们是失算了！我们已经陷入重重包围，好像一小群英国的驯鹿，被一窝狂吠的法国恶犬吓得胆战心惊。即使我们是英国的麋鹿，我们也要做个壮实的鹿，不能像瘦弱的麋鹿那样，不堪一击；我们要像被逼得发了蛮劲的雄鹿那样，掉转头来，面对着猎犬，用尖利的鹿角去触它们，使那胆怯的猎犬不敢进攻。我的朋友们，只要你们能像我一样肯硬拼，敌人即便拿下我们这群鹿，也得付出重大代价。上帝跟圣乔治、塔尔博跟英格兰的权利，在这场恶斗中，把我们的旗帜举得更高吧！\u003cb class=\"epub-calibre3\">（同下。）\u003c/b>\u003c/p>\n","text":"塔尔博 他说的不是假话，我已听到敌人的行动。派几名骑兵出去侦察一下敌人两翼的情况。嗳哟，我们是失算了！我们已经陷入重重包围，好像一小群英国的驯鹿，被一窝狂吠的法国恶犬吓得胆战心惊。即使我们是英国的麋鹿，我们也要做个壮实的鹿，不能像瘦弱的麋鹿那样，不堪一击；我们要像被逼得发了蛮劲的雄鹿那样，掉转头来，面对着猎犬，用尖利的鹿角去触它们，使那胆怯的猎犬不敢进攻。我的朋友们，只要你们能像我一样肯硬拼，敌人即便拿下我们这群鹿，也得付出重大代价。上帝跟圣乔治、塔尔博跟英格兰的权利，在这场恶斗中，把我们的旗帜举得更高吧！（同下。）\n","sourceAnchor":null,"tag":"p"}],"heading":"第二场 波尔多城前","headingLevel":4,"sourceAnchor":"a479","actNumber":4,"sceneNumber":2},{"id":"part0022-section-022","label":"第四幕 · 第三场 加斯堪尼平原","kind":"scene","blocks":[{"id":"part0022-00580","html":"\u003ch4 id=\"epub-part0022-a480\" class=\"epub-calibre12\">第三场 加斯堪尼平原\u003c/h4>\n","text":"第三场 加斯堪尼平原\n","sourceAnchor":"a480","tag":"h4"},{"id":"part0022-00581","html":"\u003cp class=\"epub-block1\">约克率军队上。一名使者来见。\u003c/p>\n","text":"约克率军队上。一名使者来见。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00582","html":"\u003cp class=\"epub-calibre1\">约克 派去尾随法国太子率领的大军的侦察兵回来没有？\u003c/p>\n","text":"约克 派去尾随法国太子率领的大军的侦察兵回来没有？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00583","html":"\u003cp class=\"epub-calibre1\">使者 大人，他们已经回来，据他们报告，法国太子已经率领他的军队前往波尔多，准备和塔尔博交战。正当他们进军的时候，我们的侦察兵又见到两支更强大的队伍和他们会合，一起向波尔多进发。\u003c/p>\n","text":"使者 大人，他们已经回来，据他们报告，法国太子已经率领他的军队前往波尔多，准备和塔尔博交战。正当他们进军的时候，我们的侦察兵又见到两支更强大的队伍和他们会合，一起向波尔多进发。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00584","html":"\u003cp class=\"epub-calibre1\">约克 该死的萨穆塞特，我征调他的骑兵去支援塔尔博，并且已和塔尔博约定，他怎么迟迟不去！鼎鼎大名的塔尔博正在渴望我的支援，我却被那奸贼误了事，不能给我们崇高的将军以及时的援助。在他的急难之中，愿上帝赐以慰藉吧！万一他作战失利，法国的战局就完蛋了。\u003c/p>\n","text":"约克 该死的萨穆塞特，我征调他的骑兵去支援塔尔博，并且已和塔尔博约定，他怎么迟迟不去！鼎鼎大名的塔尔博正在渴望我的支援，我却被那奸贼误了事，不能给我们崇高的将军以及时的援助。在他的急难之中，愿上帝赐以慰藉吧！万一他作战失利，法国的战局就完蛋了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00585","html":"\u003cp class=\"epub-block1\">威廉·路西上。\u003c/p>\n","text":"威廉·路西上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00586","html":"\u003cp class=\"epub-calibre1\">路西 我们英军的最高统帅大人，在这空前紧急关头，请您迅速派队伍驰援塔尔博将军吧！他现在好比是被一条铁箍紧紧束住了腰膂，受困在险恶的毁灭之中。英勇的公爵，快往波尔多去吧！快去吧！要不然，塔尔博、法兰西以及英国的荣誉，全都完了。\u003c/p>\n","text":"路西 我们英军的最高统帅大人，在这空前紧急关头，请您迅速派队伍驰援塔尔博将军吧！他现在好比是被一条铁箍紧紧束住了腰膂，受困在险恶的毁灭之中。英勇的公爵，快往波尔多去吧！快去吧！要不然，塔尔博、法兰西以及英国的荣誉，全都完了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00587","html":"\u003cp class=\"epub-calibre1\">约克 上帝呵，我恨不能用这个跋扈不听号令的萨穆塞特去代替塔尔博的地位！那样倒可以去掉一个懦夫和奸贼，保全一位骁勇的将军。如今是好人牺牲，恶人稳卧，真使我怒火中烧，涕泗交流。\u003c/p>\n","text":"约克 上帝呵，我恨不能用这个跋扈不听号令的萨穆塞特去代替塔尔博的地位！那样倒可以去掉一个懦夫和奸贼，保全一位骁勇的将军。如今是好人牺牲，恶人稳卧，真使我怒火中烧，涕泗交流。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00588","html":"\u003cp class=\"epub-calibre1\">路西 快派部队去支援那位四面受敌的将军吧！\u003c/p>\n","text":"路西 快派部队去支援那位四面受敌的将军吧！\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00589","html":"\u003cp class=\"epub-calibre1\">约克 他死亡，我们失败；我背弃军人的诺言；我们悲伤，法兰西微笑；我们失败，他们得意；这一切都是万恶的萨穆塞特造成的。\u003c/p>\n","text":"约克 他死亡，我们失败；我背弃军人的诺言；我们悲伤，法兰西微笑；我们失败，他们得意；这一切都是万恶的萨穆塞特造成的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00590","html":"\u003cp class=\"epub-calibre1\">路西 那么恳求上帝垂怜勇敢的塔尔博的灵魂，垂怜他的幼子约翰吧！两个小时以前我遇到小塔尔博，他正赶往他的父亲那里。他们父子已经分离七年，不想今日重逢，却将同归于尽。\u003c/p>\n","text":"路西 那么恳求上帝垂怜勇敢的塔尔博的灵魂，垂怜他的幼子约翰吧！两个小时以前我遇到小塔尔博，他正赶往他的父亲那里。他们父子已经分离七年，不想今日重逢，却将同归于尽。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00591","html":"\u003cp class=\"epub-calibre1\">约克 想不到塔尔博刚见到儿子就同进坟墓，叫他的崇高的胸怀能有什么欢乐？久别的朋友重逢在死亡的时刻，我心中不胜烦忧，我忍不住喉头哽咽。别了，路西，别指望我能做什么，我束手无策，徒唤奈何。缅因、布罗亚、波亚叠和都尔相继沦亡，都由于萨穆塞特迁延之罪，由于他的荒唐。\u003cb class=\"epub-calibre3\">（率兵士下。）\u003c/b>\u003c/p>\n","text":"约克 想不到塔尔博刚见到儿子就同进坟墓，叫他的崇高的胸怀能有什么欢乐？久别的朋友重逢在死亡的时刻，我心中不胜烦忧，我忍不住喉头哽咽。别了，路西，别指望我能做什么，我束手无策，徒唤奈何。缅因、布罗亚、波亚叠和都尔相继沦亡，都由于萨穆塞特迁延之罪，由于他的荒唐。（率兵士下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00592","html":"\u003cp class=\"epub-calibre1\">路西 当悖逆的鹫鸟啄食大将的胸膛的时候，却有人高枕而卧，无动于衷。深得民心的亨利五世老王，他的尸骨未寒，他挣下的基业却将轻轻断送。将军们争吵不休，生命、荣誉和土地都付诸东流。\u003cb class=\"epub-calibre3\">（下。）\u003c/b>\u003c/p>\n","text":"路西 当悖逆的鹫鸟啄食大将的胸膛的时候，却有人高枕而卧，无动于衷。深得民心的亨利五世老王，他的尸骨未寒，他挣下的基业却将轻轻断送。将军们争吵不休，生命、荣誉和土地都付诸东流。（下。）\n","sourceAnchor":null,"tag":"p"}],"heading":"第三场 加斯堪尼平原","headingLevel":4,"sourceAnchor":"a480","actNumber":4,"sceneNumber":3},{"id":"part0022-section-023","label":"第四幕 · 第四场 加斯堪尼另一平原","kind":"scene","blocks":[{"id":"part0022-00593","html":"\u003ch4 id=\"epub-part0022-a481\" class=\"epub-calibre12\">第四场 加斯堪尼另一平原\u003c/h4>\n","text":"第四场 加斯堪尼另一平原\n","sourceAnchor":"a481","tag":"h4"},{"id":"part0022-00594","html":"\u003cp class=\"epub-block1\">萨穆塞特率军队上。塔尔博部下一军官随上。\u003c/p>\n","text":"萨穆塞特率军队上。塔尔博部下一军官随上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00595","html":"\u003cp class=\"epub-calibre1\">萨穆塞特 已经太迟了，我现在已没法派出队伍。这次约克和塔尔博定下的进军计划过于鲁莽，我们用主力部队去攻城，本就有被包围的危险。好大喜功的塔尔博，这一次冒险轻进，使他过去的辉煌战绩，蒙上一层阴影。约克怂恿他作战，是别有用心的，他希望塔尔博战败而死，以便独享盛名。\u003c/p>\n","text":"萨穆塞特 已经太迟了，我现在已没法派出队伍。这次约克和塔尔博定下的进军计划过于鲁莽，我们用主力部队去攻城，本就有被包围的危险。好大喜功的塔尔博，这一次冒险轻进，使他过去的辉煌战绩，蒙上一层阴影。约克怂恿他作战，是别有用心的，他希望塔尔博战败而死，以便独享盛名。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00596","html":"\u003cp class=\"epub-calibre1\">军官 威廉·路西爵士来了，我们二人都是在我们的部队受到严重压迫时被派来求援的。\u003c/p>\n","text":"军官 威廉·路西爵士来了，我们二人都是在我们的部队受到严重压迫时被派来求援的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00597","html":"\u003cp class=\"epub-block1\">威廉·路西上。\u003c/p>\n","text":"威廉·路西上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00598","html":"\u003cp class=\"epub-calibre1\">萨穆塞特 怎么啦，威廉爵士！你从哪里来的？\u003c/p>\n","text":"萨穆塞特 怎么啦，威廉爵士！你从哪里来的？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00599","html":"\u003cp class=\"epub-calibre1\">路西 问我从哪里来，大人？我是从受人玩弄的塔尔博将军那里来的。他受到强大敌人的包围，向尊贵的约克和萨穆塞特呼吁，请你们帮助他的削弱了的军队，击退死亡的进攻。当这位忠义的将军流着血汗，死守阵地，力战待援的时候，您身膺国家重寄，却辜负了他的信赖，为了一些无聊的争执，竟然按兵不动，袖手旁观。请您不要因为私人的嫌隙，就把应受征调的援兵扣留不遣，坐视那位名将在众寡悬殊的形势之下丧失生命。如今奥尔良庶子、查理、勃艮第、阿朗松、瑞尼埃从四面八方将他紧紧包围，塔尔博命在旦夕，这都是由于您失约之过啊。\u003c/p>\n","text":"路西 问我从哪里来，大人？我是从受人玩弄的塔尔博将军那里来的。他受到强大敌人的包围，向尊贵的约克和萨穆塞特呼吁，请你们帮助他的削弱了的军队，击退死亡的进攻。当这位忠义的将军流着血汗，死守阵地，力战待援的时候，您身膺国家重寄，却辜负了他的信赖，为了一些无聊的争执，竟然按兵不动，袖手旁观。请您不要因为私人的嫌隙，就把应受征调的援兵扣留不遣，坐视那位名将在众寡悬殊的形势之下丧失生命。如今奥尔良庶子、查理、勃艮第、阿朗松、瑞尼埃从四面八方将他紧紧包围，塔尔博命在旦夕，这都是由于您失约之过啊。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00600","html":"\u003cp class=\"epub-calibre1\">萨穆塞特 约克怂恿他去，就应由约克派兵驰援。\u003c/p>\n","text":"萨穆塞特 约克怂恿他去，就应由约克派兵驰援。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00601","html":"\u003cp class=\"epub-calibre1\">路西 约克也会向您反唇相讥，他发誓说他特地为这次战役征调的人马被您耽误了。\u003c/p>\n","text":"路西 约克也会向您反唇相讥，他发誓说他特地为这次战役征调的人马被您耽误了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00602","html":"\u003cp class=\"epub-calibre1\">萨穆塞特 那他是在说谎，他为什么不直接派骑兵去？我对他没有什么义务，更谈不上有什么感情；我断不屑于借派兵来讨他的好。\u003c/p>\n","text":"萨穆塞特 那他是在说谎，他为什么不直接派骑兵去？我对他没有什么义务，更谈不上有什么感情；我断不屑于借派兵来讨他的好。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00603","html":"\u003cp class=\"epub-calibre1\">路西 忠勇高义的塔尔博，不是陷在法国军队的手里，而是陷在英国人的尔虞我诈之中。他一定不能生还英国了，他的命是被你们的内讧断送的。\u003c/p>\n","text":"路西 忠勇高义的塔尔博，不是陷在法国军队的手里，而是陷在英国人的尔虞我诈之中。他一定不能生还英国了，他的命是被你们的内讧断送的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00604","html":"\u003cp class=\"epub-calibre1\">萨穆塞特 好，去，我立即派骑兵去，六个小时以内就能到达。\u003c/p>\n","text":"萨穆塞特 好，去，我立即派骑兵去，六个小时以内就能到达。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00605","html":"\u003cp class=\"epub-calibre1\">路西 救兵已经太迟了，他如没有被俘，就一定阵亡了；他即便想逃，也是逃不脱的，但他即便能逃，他也断不肯逃。\u003c/p>\n","text":"路西 救兵已经太迟了，他如没有被俘，就一定阵亡了；他即便想逃，也是逃不脱的，但他即便能逃，他也断不肯逃。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00606","html":"\u003cp class=\"epub-calibre1\">萨穆塞特 万一他死了，那么，勇敢的塔尔博，愿你和上帝在一起！\u003c/p>\n","text":"萨穆塞特 万一他死了，那么，勇敢的塔尔博，愿你和上帝在一起！\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00607","html":"\u003cp class=\"epub-calibre1\">路西 他的英名将永垂于世，他的败亡则必须归咎于你。\u003cb class=\"epub-calibre3\">（同下。）\u003c/b>\u003c/p>\n","text":"路西 他的英名将永垂于世，他的败亡则必须归咎于你。（同下。）\n","sourceAnchor":null,"tag":"p"}],"heading":"第四场 加斯堪尼另一平原","headingLevel":4,"sourceAnchor":"a481","actNumber":4,"sceneNumber":4},{"id":"part0022-section-024","label":"第四幕 · 第五场 波尔多附近英军营地","kind":"scene","blocks":[{"id":"part0022-00608","html":"\u003ch4 id=\"epub-part0022-a482\" class=\"epub-calibre12\">第五场 波尔多附近英军营地\u003c/h4>\n","text":"第五场 波尔多附近英军营地\n","sourceAnchor":"a482","tag":"h4"},{"id":"part0022-00609","html":"\u003cp class=\"epub-block1\">塔尔博及其子约翰上。\u003c/p>\n","text":"塔尔博及其子约翰上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00610","html":"\u003cp class=\"epub-calibre1\">塔尔博 唉，年轻的约翰！我召唤你到这儿来，原想让你随在我的身旁，学习一些韬略；今后我年老力衰，退归林下，指望你重振家声。唉，预兆不祥的星宿呵！谁料到你赶到这里，恰恰遇到形势险恶、命在旦夕的时节。现在事不宜迟，亲爱的孩子，赶快骑上我的快马，我指点你怎样冲出重围。来，不要耽搁，快走，快走。\u003c/p>\n","text":"塔尔博 唉，年轻的约翰！我召唤你到这儿来，原想让你随在我的身旁，学习一些韬略；今后我年老力衰，退归林下，指望你重振家声。唉，预兆不祥的星宿呵！谁料到你赶到这里，恰恰遇到形势险恶、命在旦夕的时节。现在事不宜迟，亲爱的孩子，赶快骑上我的快马，我指点你怎样冲出重围。来，不要耽搁，快走，快走。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00611","html":"\u003cp class=\"epub-calibre1\">约翰 我的姓氏是不是塔尔博？我是不是您的儿子？叫我逃吗？啊，如果您是爱我母亲的，就请不要叫我变成一个私生子，变成一个奴才，来玷辱她的清白的名字吧！因为世人都会说，这人一定不是塔尔博的亲骨血，他高贵的父亲还在苦战，他怎么狼狈而逃？\u003c/p>\n","text":"约翰 我的姓氏是不是塔尔博？我是不是您的儿子？叫我逃吗？啊，如果您是爱我母亲的，就请不要叫我变成一个私生子，变成一个奴才，来玷辱她的清白的名字吧！因为世人都会说，这人一定不是塔尔博的亲骨血，他高贵的父亲还在苦战，他怎么狼狈而逃？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00612","html":"\u003cp class=\"epub-calibre1\">塔尔博 逃吧，如果我被杀，你替我报仇雪恨。\u003c/p>\n","text":"塔尔博 逃吧，如果我被杀，你替我报仇雪恨。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00613","html":"\u003cp class=\"epub-calibre1\">约翰 一个人处在这样的局面，若是肯逃，他根本就负不起复仇的责任。\u003c/p>\n","text":"约翰 一个人处在这样的局面，若是肯逃，他根本就负不起复仇的责任。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00614","html":"\u003cp class=\"epub-calibre1\">塔尔博 如果我们两人都不走，两人都必死无疑。\u003c/p>\n","text":"塔尔博 如果我们两人都不走，两人都必死无疑。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00615","html":"\u003cp class=\"epub-calibre1\">约翰 那就让我留下；父亲，你速走莫迟。您身系国家安危，您的生死关系非轻；我若死了却不算什么损失，因为我尚未成名。法国人杀了我，并不能借此来夸张战绩；您如遭到不幸，他们就会大肆吹嘘，而我们的一切希望也将成为泡影了。您的盖世勋名不会因为一次退却就受到玷辱；我还寸功未立，若是离开阵地，就成为莫大污点。您如撤退，人人都能谅解，说是出于战略的要求；我若退让一步，大家定将骂我胆怯。如果我第一次遇到危险就逃避不遑，以后就再也不能指望我坚持到底了。我这里跪告苍天，唯求一死，决不肯含羞忍耻，苟且偷生。\u003c/p>\n","text":"约翰 那就让我留下；父亲，你速走莫迟。您身系国家安危，您的生死关系非轻；我若死了却不算什么损失，因为我尚未成名。法国人杀了我，并不能借此来夸张战绩；您如遭到不幸，他们就会大肆吹嘘，而我们的一切希望也将成为泡影了。您的盖世勋名不会因为一次退却就受到玷辱；我还寸功未立，若是离开阵地，就成为莫大污点。您如撤退，人人都能谅解，说是出于战略的要求；我若退让一步，大家定将骂我胆怯。如果我第一次遇到危险就逃避不遑，以后就再也不能指望我坚持到底了。我这里跪告苍天，唯求一死，决不肯含羞忍耻，苟且偷生。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00616","html":"\u003cp class=\"epub-calibre1\">塔尔博 难道叫你母亲的一切亲人同归于尽？\u003c/p>\n","text":"塔尔博 难道叫你母亲的一切亲人同归于尽？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00617","html":"\u003cp class=\"epub-calibre1\">约翰 哎，宁可如此，也不能叫她死后蒙羞，九泉抱恨。\u003c/p>\n","text":"约翰 哎，宁可如此，也不能叫她死后蒙羞，九泉抱恨。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00618","html":"\u003cp class=\"epub-calibre1\">塔尔博 我为你祝福，我命令你赶快逃生。\u003c/p>\n","text":"塔尔博 我为你祝福，我命令你赶快逃生。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00619","html":"\u003cp class=\"epub-calibre1\">约翰 叫我作战，我愿意；叫我逃命，万万不能。\u003c/p>\n","text":"约翰 叫我作战，我愿意；叫我逃命，万万不能。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00620","html":"\u003cp class=\"epub-calibre1\">塔尔博 你有活命，你父亲就通过你而部分得救。\u003c/p>\n","text":"塔尔博 你有活命，你父亲就通过你而部分得救。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00621","html":"\u003cp class=\"epub-calibre1\">约翰 那并不足百世流芳，只能万年遗臭。\u003c/p>\n","text":"约翰 那并不足百世流芳，只能万年遗臭。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00622","html":"\u003cp class=\"epub-calibre1\">塔尔博 你还没有建立勋名，所以不至于声名扫地。\u003c/p>\n","text":"塔尔博 你还没有建立勋名，所以不至于声名扫地。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00623","html":"\u003cp class=\"epub-calibre1\">约翰 是呀，您既已功名盖世，退却一次又何足芥蒂？\u003c/p>\n","text":"约翰 是呀，您既已功名盖世，退却一次又何足芥蒂？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00624","html":"\u003cp class=\"epub-calibre1\">塔尔博 你逃生是出于父命，人家不能对你苛求。\u003c/p>\n","text":"塔尔博 你逃生是出于父命，人家不能对你苛求。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00625","html":"\u003cp class=\"epub-calibre1\">约翰 可是您已为国捐躯，谁来为我证明原由？既然死亡迫在眉睫，我父子就一同逃走吧。\u003c/p>\n","text":"约翰 可是您已为国捐躯，谁来为我证明原由？既然死亡迫在眉睫，我父子就一同逃走吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00626","html":"\u003cp class=\"epub-calibre1\">塔尔博 难道留下我的官兵，叫他们作战至死吗？我活了这把年纪，从未做过这样丢人的事。\u003c/p>\n","text":"塔尔博 难道留下我的官兵，叫他们作战至死吗？我活了这把年纪，从未做过这样丢人的事。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00627","html":"\u003cp class=\"epub-calibre1\">约翰 难道我这年轻小伙子反而不顾羞耻？无论情况如何，我决不离开您的身畔，犹如您自己不能把自己劈成两半。留也罢，走也罢，您怎么办，我也怎么办；您如果献身报国，我也决不苟延残喘。\u003c/p>\n","text":"约翰 难道我这年轻小伙子反而不顾羞耻？无论情况如何，我决不离开您的身畔，犹如您自己不能把自己劈成两半。留也罢，走也罢，您怎么办，我也怎么办；您如果献身报国，我也决不苟延残喘。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00628","html":"\u003cp class=\"epub-calibre1\">塔尔博 那么，别了，我的好儿子。你生不逢辰，今天下午就是你授命之日。好，我们肩并肩，臂靠臂，同生同死；在这法兰西的土地上，我们父子的灵魂要一同飞上天庭。\u003cb class=\"epub-calibre3\">（同下。）\u003c/b>\u003c/p>\n","text":"塔尔博 那么，别了，我的好儿子。你生不逢辰，今天下午就是你授命之日。好，我们肩并肩，臂靠臂，同生同死；在这法兰西的土地上，我们父子的灵魂要一同飞上天庭。（同下。）\n","sourceAnchor":null,"tag":"p"}],"heading":"第五场 波尔多附近英军营地","headingLevel":4,"sourceAnchor":"a482","actNumber":4,"sceneNumber":5},{"id":"part0022-section-025","label":"第四幕 · 第六场 战场","kind":"scene","blocks":[{"id":"part0022-00629","html":"\u003ch4 id=\"epub-part0022-a483\" class=\"epub-calibre12\">第六场 战场\u003c/h4>\n","text":"第六场 战场\n","sourceAnchor":"a483","tag":"h4"},{"id":"part0022-00630","html":"\u003cp class=\"epub-block1\">号角声，两军交战，塔尔博之子四面受敌，塔尔博赴援。\u003c/p>\n","text":"号角声，两军交战，塔尔博之子四面受敌，塔尔博赴援。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00631","html":"\u003cp class=\"epub-calibre1\">塔尔博 圣乔治保佑我们胜利！杀呀，兵士们，杀呀！那总管大臣，他对我失约，救兵不到，我们只得奋勇作战，抵挡法国人的凶猛的枪刀。我儿约翰在哪里？啊，你歇一歇，喘口气吧。你的生命是我给你的，我又从死亡中救出你来。\u003c/p>\n","text":"塔尔博 圣乔治保佑我们胜利！杀呀，兵士们，杀呀！那总管大臣，他对我失约，救兵不到，我们只得奋勇作战，抵挡法国人的凶猛的枪刀。我儿约翰在哪里？啊，你歇一歇，喘口气吧。你的生命是我给你的，我又从死亡中救出你来。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00632","html":"\u003cp class=\"epub-calibre1\">约翰 哎呀，您是我再度的父亲，我是您再度的儿子了。您第一次给我的生命已经丧失了，多亏您挥舞神勇的宝剑才挽回颓局，赐给我再生之日。\u003c/p>\n","text":"约翰 哎呀，您是我再度的父亲，我是您再度的儿子了。您第一次给我的生命已经丧失了，多亏您挥舞神勇的宝剑才挽回颓局，赐给我再生之日。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00633","html":"\u003cp class=\"epub-calibre1\">塔尔博 我看到你用剑砍下法国太子的盔缨，你那英俊的雄姿暖了你老父的心，使我决心争取最后的胜利。在我年迈的胸膛里燃起少年般的烈火，我击退了阿朗松和勃艮第那一群虏酋，把你从法国的精锐部队中救了出来。凶恶的奥尔良庶子欺负你年轻，叫你挂了彩；我随即和他交手，砍得那私生子流出血来。我用鄙薄的口吻骂他：“下流的杂种，从你身上淌出的卑污的血，怎能和我儿纯洁的血相比！”我奋勇救你，也想趁此把那庶子剪除。我的爱子啊，告诉我，你困乏了吗？你身子怎样？你已显示过你的身手，不愧为将门之子，现在你总可以离开阵地了吧。快走，等我死后，你替我报仇。多留下一个帮手在这里，对我也无益。若把全体的生命都载在一只小舟上去和风浪搏斗，那真是愚不可及。我年已老迈，即便今天不死在法国人的手里，也没有多少时候好活。我留在这里，法国人占不到什么便宜，最多不过叫我少活一两天罢了。可是你和我不同，在你身上寄托着你母亲的遗志，我们家族的声名，为我复仇的重任，你自己的青春，以及英国的威望。如果你留，这一切都将付之流水；如果你走，这一切就赖以保全。\u003c/p>\n","text":"塔尔博 我看到你用剑砍下法国太子的盔缨，你那英俊的雄姿暖了你老父的心，使我决心争取最后的胜利。在我年迈的胸膛里燃起少年般的烈火，我击退了阿朗松和勃艮第那一群虏酋，把你从法国的精锐部队中救了出来。凶恶的奥尔良庶子欺负你年轻，叫你挂了彩；我随即和他交手，砍得那私生子流出血来。我用鄙薄的口吻骂他：“下流的杂种，从你身上淌出的卑污的血，怎能和我儿纯洁的血相比！”我奋勇救你，也想趁此把那庶子剪除。我的爱子啊，告诉我，你困乏了吗？你身子怎样？你已显示过你的身手，不愧为将门之子，现在你总可以离开阵地了吧。快走，等我死后，你替我报仇。多留下一个帮手在这里，对我也无益。若把全体的生命都载在一只小舟上去和风浪搏斗，那真是愚不可及。我年已老迈，即便今天不死在法国人的手里，也没有多少时候好活。我留在这里，法国人占不到什么便宜，最多不过叫我少活一两天罢了。可是你和我不同，在你身上寄托着你母亲的遗志，我们家族的声名，为我复仇的重任，你自己的青春，以及英国的威望。如果你留，这一切都将付之流水；如果你走，这一切就赖以保全。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00634","html":"\u003cp class=\"epub-calibre1\">约翰 奥尔良的宝剑并未叫我吃惊。您这一番话却使我心头滴血。为了那一点儿便宜，就出卖廉耻；为了保全一条卑微的生命，就毁弃令名；如果我竟做出这等事来，就叫我这懦夫骑的马在举步以前，颠踬而亡！就把我比作法国的村童，叫我受尽一切耻辱的讪谤，遭遇一切的灾殃！有您这样一位顶天立地的父亲，如果我逃走，我就不配做塔尔博之子。别再提逃走二字吧，那是丝毫没用的。我是塔尔博之子，我一定死在塔尔博的跟前。\u003c/p>\n","text":"约翰 奥尔良的宝剑并未叫我吃惊。您这一番话却使我心头滴血。为了那一点儿便宜，就出卖廉耻；为了保全一条卑微的生命，就毁弃令名；如果我竟做出这等事来，就叫我这懦夫骑的马在举步以前，颠踬而亡！就把我比作法国的村童，叫我受尽一切耻辱的讪谤，遭遇一切的灾殃！有您这样一位顶天立地的父亲，如果我逃走，我就不配做塔尔博之子。别再提逃走二字吧，那是丝毫没用的。我是塔尔博之子，我一定死在塔尔博的跟前。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00635","html":"\u003cp class=\"epub-calibre1\">塔尔博 既然如此，你就学着伊卡洛斯的榜样，紧跟在他父亲代达罗斯的身边\u003ca id=\"epub-part0022-w010\">\u003c/a>\u003ca href=\"#epub-part0022-m010\" data-source-anchor=\"m010\">\u003csup class=\"epub-calibre13\">[10]\u003c/sup>\u003c/a>。你是我最最疼爱的爱子，让我们寸步不离，一同作战，表现出我们高贵的品质，光荣地献出我们的生命。\u003cb class=\"epub-calibre3\">（同下。）\u003c/b>\u003c/p>\n","text":"塔尔博 既然如此，你就学着伊卡洛斯的榜样，紧跟在他父亲代达罗斯的身边[10]。你是我最最疼爱的爱子，让我们寸步不离，一同作战，表现出我们高贵的品质，光荣地献出我们的生命。（同下。）\n","sourceAnchor":null,"tag":"p"}],"heading":"第六场 战场","headingLevel":4,"sourceAnchor":"a483","actNumber":4,"sceneNumber":6},{"id":"part0022-section-026","label":"第四幕 · 第七场 战场的另一处","kind":"scene","blocks":[{"id":"part0022-00636","html":"\u003ch4 id=\"epub-part0022-a484\" class=\"epub-calibre12\">第七场 战场的另一处\u003c/h4>\n","text":"第七场 战场的另一处\n","sourceAnchor":"a484","tag":"h4"},{"id":"part0022-00637","html":"\u003cp class=\"epub-block1\">号角声，两军对战。塔尔博负伤，由仆人扶上。\u003c/p>\n","text":"号角声，两军对战。塔尔博负伤，由仆人扶上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00638","html":"\u003cp class=\"epub-calibre1\">塔尔博 我的另一条生命在哪儿？我自己的生命是完结了。啊，小塔尔博在哪儿？英勇的约翰在哪儿？赢得胜利的死神哟，我浴血死战，身负重伤，即将落到你的掌握之中，但我儿子的英勇表现，使我能对你微笑了。我儿约翰看到我力不能支，就挥动他涂满血污的宝剑为我掩护，他那生龙活虎的雄姿，使敌人望风披靡。当他独自站在我的跟前看护我的伤痕的时候，他怒火中烧，目眦欲裂，突然从我的身旁冲到法军最密集的地方，以无比的威力沐浴在敌人的血海之中，我的伊卡洛斯，我的生命的英华，就这样光荣牺牲了。\u003c/p>\n","text":"塔尔博 我的另一条生命在哪儿？我自己的生命是完结了。啊，小塔尔博在哪儿？英勇的约翰在哪儿？赢得胜利的死神哟，我浴血死战，身负重伤，即将落到你的掌握之中，但我儿子的英勇表现，使我能对你微笑了。我儿约翰看到我力不能支，就挥动他涂满血污的宝剑为我掩护，他那生龙活虎的雄姿，使敌人望风披靡。当他独自站在我的跟前看护我的伤痕的时候，他怒火中烧，目眦欲裂，突然从我的身旁冲到法军最密集的地方，以无比的威力沐浴在敌人的血海之中，我的伊卡洛斯，我的生命的英华，就这样光荣牺牲了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00639","html":"\u003cp class=\"epub-block1\">众兵士舁小塔尔博尸体上。\u003c/p>\n","text":"众兵士舁小塔尔博尸体上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00640","html":"\u003cp class=\"epub-calibre1\">仆人 我的亲爱的主人，瞧，他们把您的儿子抬来了。\u003c/p>\n","text":"仆人 我的亲爱的主人，瞧，他们把您的儿子抬来了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00641","html":"\u003cp class=\"epub-calibre1\">塔尔博 你这爱扮鬼脸的死神，不要带着讥讽的恶意对我狂笑，我们父子马上就要不受你的压制，摆脱你的牢笼，插上双翼，飞向柔和的天空，再也不在尘世里忍受折磨了。我的儿呵，你负伤而死，不失勇士的气概，在你停止呼吸以前，对你父亲说句话呀！你说一句话，就足以表示你对死神的蔑视；我要你把死神当作一个法国人，当作你的仇敌。可怜的孩子，他微笑了，他似乎在说：“如果死神果真是个法国人，那么死神今天已经死去了。”请你们帮个忙，把他放到他父亲的怀里来，我已经精神恍惚，支撑不住了。兵士们，我向你们告别了！我能用我这老年人的怀抱作为我爱子的坟墓，我已心满意足了。\u003cb class=\"epub-calibre3\">（死。）\u003c/b>\u003c/p>\n","text":"塔尔博 你这爱扮鬼脸的死神，不要带着讥讽的恶意对我狂笑，我们父子马上就要不受你的压制，摆脱你的牢笼，插上双翼，飞向柔和的天空，再也不在尘世里忍受折磨了。我的儿呵，你负伤而死，不失勇士的气概，在你停止呼吸以前，对你父亲说句话呀！你说一句话，就足以表示你对死神的蔑视；我要你把死神当作一个法国人，当作你的仇敌。可怜的孩子，他微笑了，他似乎在说：“如果死神果真是个法国人，那么死神今天已经死去了。”请你们帮个忙，把他放到他父亲的怀里来，我已经精神恍惚，支撑不住了。兵士们，我向你们告别了！我能用我这老年人的怀抱作为我爱子的坟墓，我已心满意足了。（死。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00642","html":"\u003cp class=\"epub-block1\">阵阵鼓角声。兵士及仆人下，留下塔尔博父子尸体。查理、阿朗松、勃艮第、奥尔良庶子、贞德率军队上。\u003c/p>\n","text":"阵阵鼓角声。兵士及仆人下，留下塔尔博父子尸体。查理、阿朗松、勃艮第、奥尔良庶子、贞德率军队上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00643","html":"\u003cp class=\"epub-calibre1\">查理 倘若约克和萨穆塞特及时派到救兵，今天这场血战一定是够惨烈的。\u003c/p>\n","text":"查理 倘若约克和萨穆塞特及时派到救兵，今天这场血战一定是够惨烈的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00644","html":"\u003cp class=\"epub-calibre1\">庶子 那小塔尔博狗崽子像发了疯，他用法国人的血来试他的剑锋。\u003c/p>\n","text":"庶子 那小塔尔博狗崽子像发了疯，他用法国人的血来试他的剑锋。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00645","html":"\u003cp class=\"epub-calibre1\">贞德 我曾和他遭遇，我对他说：“乳臭未干的小伙子，叫你败在姑娘的手里。”他却昂然不屑地回答我：“天生我堂堂男子，岂肯和你这浪妇交锋！”说完他就冲到我军的垓心里去，傲慢地离开了我，似乎我是不值他一顾的。\u003c/p>\n","text":"贞德 我曾和他遭遇，我对他说：“乳臭未干的小伙子，叫你败在姑娘的手里。”他却昂然不屑地回答我：“天生我堂堂男子，岂肯和你这浪妇交锋！”说完他就冲到我军的垓心里去，傲慢地离开了我，似乎我是不值他一顾的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00646","html":"\u003cp class=\"epub-calibre1\">勃艮第 有他那样的骁勇，他是不难成为一员高贵的骑士的。瞧，他现在躺在他老子的怀里，他这般凶横都是那嗜杀的老子教出来的。\u003c/p>\n","text":"勃艮第 有他那样的骁勇，他是不难成为一员高贵的骑士的。瞧，他现在躺在他老子的怀里，他这般凶横都是那嗜杀的老子教出来的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00647","html":"\u003cp class=\"epub-calibre1\">庶子 他们父子活着的时候，是英国的荣光，却是我们法国的灾殃，现在他们死了，我要把他们剁成肉酱。\u003c/p>\n","text":"庶子 他们父子活着的时候，是英国的荣光，却是我们法国的灾殃，现在他们死了，我要把他们剁成肉酱。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00648","html":"\u003cp class=\"epub-calibre1\">查理 不可如此！他们生前既为我们所畏惧，他们死后我们也别加以糟蹋。\u003c/p>\n","text":"查理 不可如此！他们生前既为我们所畏惧，他们死后我们也别加以糟蹋。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00649","html":"\u003cp class=\"epub-block1\">威廉·路西由法军传令官导引，率随从等上。\u003c/p>\n","text":"威廉·路西由法军传令官导引，率随从等上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00650","html":"\u003cp class=\"epub-calibre1\">路西 传令官，领我到太子的营帐里，我要知道今天的光荣是属于谁的。\u003c/p>\n","text":"路西 传令官，领我到太子的营帐里，我要知道今天的光荣是属于谁的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00651","html":"\u003cp class=\"epub-calibre1\">查理 谁派你来投递降书的？\u003c/p>\n","text":"查理 谁派你来投递降书的？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00652","html":"\u003cp class=\"epub-calibre1\">路西 什么降不降，太子！只有你们法国才有这个字眼，我们英国军人不懂得这个字的意思。我来见你，是为了调查一下哪些人被你俘获，还要看一看我方阵亡将士的尸体。\u003c/p>\n","text":"路西 什么降不降，太子！只有你们法国才有这个字眼，我们英国军人不懂得这个字的意思。我来见你，是为了调查一下哪些人被你俘获，还要看一看我方阵亡将士的尸体。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00653","html":"\u003cp class=\"epub-calibre1\">查理 你要打听俘虏吗？你只能到地狱去找他们了。你干脆告诉我，你要打听的是谁。\u003c/p>\n","text":"查理 你要打听俘虏吗？你只能到地狱去找他们了。你干脆告诉我，你要打听的是谁。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00654","html":"\u003cp class=\"epub-calibre1\">路西 我说给你，我要打听的是今天战场上的天字第一号英雄，就是那位英勇的塔尔博将军，由于卓越的战功，他已晋封为索鲁斯伯雷伯爵、兼瓦虚福及凡仑司伯爵、兼古德立及欧钦菲勋爵、兼白拉克米勋爵、兼阿尔顿勋爵、兼温菲勋爵、兼舍菲勋爵、兼联捷三次的福康勃立琪勋爵，加授圣乔治、圣米迦勒及金羊毛骑士称号，实授亨利六世驾前统领法境英军大元帅——这位将军在哪里？\u003c/p>\n","text":"路西 我说给你，我要打听的是今天战场上的天字第一号英雄，就是那位英勇的塔尔博将军，由于卓越的战功，他已晋封为索鲁斯伯雷伯爵、兼瓦虚福及凡仑司伯爵、兼古德立及欧钦菲勋爵、兼白拉克米勋爵、兼阿尔顿勋爵、兼温菲勋爵、兼舍菲勋爵、兼联捷三次的福康勃立琪勋爵，加授圣乔治、圣米迦勒及金羊毛骑士称号，实授亨利六世驾前统领法境英军大元帅——这位将军在哪里？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00655","html":"\u003cp class=\"epub-calibre1\">贞德 好一串嘟嘟囔囔的头衔！占有五十二个国家的土耳其可汗也没有这样噜苏的衔名。你用那么多的官衔来表示的那个人，现在正躺在我们的脚前，被苍蝇叮着，发出恶臭。\u003c/p>\n","text":"贞德 好一串嘟嘟囔囔的头衔！占有五十二个国家的土耳其可汗也没有这样噜苏的衔名。你用那么多的官衔来表示的那个人，现在正躺在我们的脚前，被苍蝇叮着，发出恶臭。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00656","html":"\u003cp class=\"epub-calibre1\">路西 哎呀，那位威震法国、作为惩罚法国人的鞭子的塔尔博将军，他遇害了吗？如果我能叫我的眼珠变成子弹，在我的愤怒之下，我定把它们射到你们的脸上！我恨不能叫他父子死而复生，只要有他父子，就能叫你们全国的人颤栗不止！不，只须把他的画像悬在这里，就足使你们中间最骄傲的人心惊胆战。把他父子的尸体交还给我，我要把他们运还本土，以礼安葬。\u003c/p>\n","text":"路西 哎呀，那位威震法国、作为惩罚法国人的鞭子的塔尔博将军，他遇害了吗？如果我能叫我的眼珠变成子弹，在我的愤怒之下，我定把它们射到你们的脸上！我恨不能叫他父子死而复生，只要有他父子，就能叫你们全国的人颤栗不止！不，只须把他的画像悬在这里，就足使你们中间最骄傲的人心惊胆战。把他父子的尸体交还给我，我要把他们运还本土，以礼安葬。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00657","html":"\u003cp class=\"epub-calibre1\">贞德 这个莽汉一定有老塔尔博的鬼魂附在身上，你听他说起话来，好大的口气。看在上帝的分上，把尸体给他吧，留在这里，只能发臭，把空气都弄得污浊了。\u003c/p>\n","text":"贞德 这个莽汉一定有老塔尔博的鬼魂附在身上，你听他说起话来，好大的口气。看在上帝的分上，把尸体给他吧，留在这里，只能发臭，把空气都弄得污浊了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00658","html":"\u003cp class=\"epub-calibre1\">查理 算了，把尸体带走吧。\u003c/p>\n","text":"查理 算了，把尸体带走吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00659","html":"\u003cp class=\"epub-calibre1\">路西 我是要把他们运走的。等我将他们火化以后，从他们的尸灰里会生出一只凤凰，使你们整个法国不得安生。\u003c/p>\n","text":"路西 我是要把他们运走的。等我将他们火化以后，从他们的尸灰里会生出一只凤凰，使你们整个法国不得安生。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00660","html":"\u003cp class=\"epub-calibre1\">查理 只要你把他们带走，随便你怎么办都行。现在趁着此番胜利，我们要一鼓作气，直取巴黎。塔尔博已死，我们可以为所欲为了。\u003cb class=\"epub-calibre3\">（同下。）\u003c/b>\u003c/p>\n","text":"查理 只要你把他们带走，随便你怎么办都行。现在趁着此番胜利，我们要一鼓作气，直取巴黎。塔尔博已死，我们可以为所欲为了。（同下。）\n","sourceAnchor":null,"tag":"p"}],"heading":"第七场 战场的另一处","headingLevel":4,"sourceAnchor":"a484","actNumber":4,"sceneNumber":7},{"id":"part0022-section-027","label":"第五幕","kind":"act","blocks":[{"id":"part0022-00661","html":"\u003ch3 id=\"epub-part0022-a485\" class=\"epub-calibre11\">第五幕\u003c/h3>\n","text":"第五幕\n","sourceAnchor":"a485","tag":"h3"}],"heading":"第五幕","headingLevel":3,"sourceAnchor":"a485","actNumber":5},{"id":"part0022-section-028","label":"第五幕 · 第一场 伦敦。宫廷","kind":"scene","blocks":[{"id":"part0022-00662","html":"\u003ch4 id=\"epub-part0022-a486\" class=\"epub-calibre12\">第一场 伦敦。宫廷\u003c/h4>\n","text":"第一场 伦敦。宫廷\n","sourceAnchor":"a486","tag":"h4"},{"id":"part0022-00663","html":"\u003cp class=\"epub-block1\">礼号声。亨利王，葛罗斯特及爱克塞特上。\u003c/p>\n","text":"礼号声。亨利王，葛罗斯特及爱克塞特上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00664","html":"\u003cp class=\"epub-calibre1\">亨利王 教皇、罗马皇帝和阿玛涅克伯爵的来信，你看过了没有？\u003c/p>\n","text":"亨利王 教皇、罗马皇帝和阿玛涅克伯爵的来信，你看过了没有？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00665","html":"\u003cp class=\"epub-calibre1\">葛罗斯特 我都看过了，陛下。信里的大意是：他们恳求陛下和法国议和。\u003c/p>\n","text":"葛罗斯特 我都看过了，陛下。信里的大意是：他们恳求陛下和法国议和。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00666","html":"\u003cp class=\"epub-calibre1\">亨利王 贤卿的意见如何？\u003c/p>\n","text":"亨利王 贤卿的意见如何？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00667","html":"\u003cp class=\"epub-calibre1\">葛罗斯特 这个——陛下。为了不再叫基督徒们流血，恢复各方面的安宁，只有议和才是个办法。\u003c/p>\n","text":"葛罗斯特 这个——陛下。为了不再叫基督徒们流血，恢复各方面的安宁，只有议和才是个办法。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00668","html":"\u003cp class=\"epub-calibre1\">亨利王 哎，真的，叔父。我素来认为，我们两国人民都奉行同一的宗教，如果互相残杀，那是既违天意，又悖人情。\u003c/p>\n","text":"亨利王 哎，真的，叔父。我素来认为，我们两国人民都奉行同一的宗教，如果互相残杀，那是既违天意，又悖人情。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00669","html":"\u003cp class=\"epub-calibre1\">葛罗斯特 此外，陛下，还有一桩有利的条件，可使和议早日达成，和议达成以后，也可得到更好的保证：法国太子查理的亲密盟友，阿玛涅克伯爵，在法国是一个握有实力的人，他愿将他的独生女儿嫁给王上，并赠送一笔丰厚的妆奁。\u003c/p>\n","text":"葛罗斯特 此外，陛下，还有一桩有利的条件，可使和议早日达成，和议达成以后，也可得到更好的保证：法国太子查理的亲密盟友，阿玛涅克伯爵，在法国是一个握有实力的人，他愿将他的独生女儿嫁给王上，并赠送一笔丰厚的妆奁。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00670","html":"\u003cp class=\"epub-calibre1\">亨利王 嫁给我！叔父，我还年轻呀！我现在专心读书才是正理，还不到谈情说爱的时期。不过，依着贤卿的意见，我们就召见各国使臣，给他们一个答复吧。只要能为上帝增光，为社稷谋福，任何建议，我都可以嘉纳的。\u003c/p>\n","text":"亨利王 嫁给我！叔父，我还年轻呀！我现在专心读书才是正理，还不到谈情说爱的时期。不过，依着贤卿的意见，我们就召见各国使臣，给他们一个答复吧。只要能为上帝增光，为社稷谋福，任何建议，我都可以嘉纳的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00671","html":"\u003cp class=\"epub-block1\">温彻斯特穿红衣主教服饰偕一教廷使臣及两大使上。\u003c/p>\n","text":"温彻斯特穿红衣主教服饰偕一教廷使臣及两大使上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00672","html":"\u003cp class=\"epub-calibre1\">爱克塞特 \u003cb class=\"epub-calibre3\">（旁白）\u003c/b>怎么！温彻斯特升了官了，他什么时候升为红衣主教的？我看亨利五世老王的一句预言果真要应验了。他曾说过：“他一旦当上了红衣主教，他就想和国王分庭抗礼了。”\u003c/p>\n","text":"爱克塞特 （旁白）怎么！温彻斯特升了官了，他什么时候升为红衣主教的？我看亨利五世老王的一句预言果真要应验了。他曾说过：“他一旦当上了红衣主教，他就想和国王分庭抗礼了。”\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00673","html":"\u003cp class=\"epub-calibre1\">亨利王 各位使臣，你们递来的国书，我们已经慎重考虑过了。你们的来意很好，所提办法，也很合理，因此，我们决定提出议和的条款，特派温彻斯特钦差赍往法国。\u003c/p>\n","text":"亨利王 各位使臣，你们递来的国书，我们已经慎重考虑过了。你们的来意很好，所提办法，也很合理，因此，我们决定提出议和的条款，特派温彻斯特钦差赍往法国。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00674","html":"\u003cp class=\"epub-calibre1\">葛罗斯特 \u003cb class=\"epub-calibre3\">（向一使臣）\u003c/b>至于您的主人阿玛涅克伯爵的提议，我已经详细奏明王上。关于你们郡主的淑德美貌，以及妆奁的价值，都已一一奏明。王上听了甚为中意，决定娶你家郡主为我国王后。\u003c/p>\n","text":"葛罗斯特 （向一使臣）至于您的主人阿玛涅克伯爵的提议，我已经详细奏明王上。关于你们郡主的淑德美貌，以及妆奁的价值，都已一一奏明。王上听了甚为中意，决定娶你家郡主为我国王后。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00675","html":"\u003cp class=\"epub-calibre1\">亨利王 这里有一份珠宝，请你带去，作为订婚礼物，并借以表示我对她的倾慕之忱。护国公贤卿，你派人护送这几位使臣前往多佛，在那里搭船归国，并祝他们海上平安。\u003cb class=\"epub-calibre3\">（除温彻斯特及教廷使臣外均下。）\u003c/b>\u003c/p>\n","text":"亨利王 这里有一份珠宝，请你带去，作为订婚礼物，并借以表示我对她的倾慕之忱。护国公贤卿，你派人护送这几位使臣前往多佛，在那里搭船归国，并祝他们海上平安。（除温彻斯特及教廷使臣外均下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00676","html":"\u003cp class=\"epub-calibre1\">温彻斯特 请等一等，钦差大人。这次承蒙教皇提拔，使我能够穿上这身庄严的服饰，不胜感激。我曾约定奉呈一笔款项，聊表寸心，在您动身回国以前，请将这项银子代为收纳。\u003c/p>\n","text":"温彻斯特 请等一等，钦差大人。这次承蒙教皇提拔，使我能够穿上这身庄严的服饰，不胜感激。我曾约定奉呈一笔款项，聊表寸心，在您动身回国以前，请将这项银子代为收纳。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00677","html":"\u003cp class=\"epub-calibre1\">教使 等您闲暇的时候，我来领教。\u003c/p>\n","text":"教使 等您闲暇的时候，我来领教。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00678","html":"\u003cp class=\"epub-calibre1\">温彻斯特 \u003cb class=\"epub-calibre3\">（旁白）\u003c/b>从今以后，我温彻斯特站在爵位最高的贵族面前，也不寒伧了。葛罗斯特哟，我要叫你知道，无论讲到身世，无论讲到权力，本主教再也不受你的欺负了。除非你低头认罪，我定要把我们的国家闹得天翻地覆。\u003cb class=\"epub-calibre3\">（同下。）\u003c/b>\u003c/p>\n","text":"温彻斯特 （旁白）从今以后，我温彻斯特站在爵位最高的贵族面前，也不寒伧了。葛罗斯特哟，我要叫你知道，无论讲到身世，无论讲到权力，本主教再也不受你的欺负了。除非你低头认罪，我定要把我们的国家闹得天翻地覆。（同下。）\n","sourceAnchor":null,"tag":"p"}],"heading":"第一场 伦敦。宫廷","headingLevel":4,"sourceAnchor":"a486","actNumber":5,"sceneNumber":1},{"id":"part0022-section-029","label":"第五幕 · 第二场 法国。安佐平原","kind":"scene","blocks":[{"id":"part0022-00679","html":"\u003ch4 id=\"epub-part0022-a487\" class=\"epub-calibre12\">第二场 法国。安佐平原\u003c/h4>\n","text":"第二场 法国。安佐平原\n","sourceAnchor":"a487","tag":"h4"},{"id":"part0022-00680","html":"\u003cp class=\"epub-block1\">查理、勃艮第、阿朗松、贞德率兵士列队行进。\u003c/p>\n","text":"查理、勃艮第、阿朗松、贞德率兵士列队行进。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00681","html":"\u003cp class=\"epub-calibre1\">查理 众位贤卿，我们得到振奋人心的消息。据报告，坚强的巴黎人民已经叛离英国，回到我们法国方面来了。\u003c/p>\n","text":"查理 众位贤卿，我们得到振奋人心的消息。据报告，坚强的巴黎人民已经叛离英国，回到我们法国方面来了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00682","html":"\u003cp class=\"epub-calibre1\">阿朗松 那么，殿下，我们就立刻进军巴黎，不要耽搁吧。\u003c/p>\n","text":"阿朗松 那么，殿下，我们就立刻进军巴黎，不要耽搁吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00683","html":"\u003cp class=\"epub-calibre1\">贞德 若是巴黎人民归顺我国，就祝福他们共享太平；如若不然，就叫那里的楼台殿阁，化为灰烬！\u003c/p>\n","text":"贞德 若是巴黎人民归顺我国，就祝福他们共享太平；如若不然，就叫那里的楼台殿阁，化为灰烬！\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00684","html":"\u003cp class=\"epub-block1\">侦察兵上。\u003c/p>\n","text":"侦察兵上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00685","html":"\u003cp class=\"epub-calibre1\">侦察兵 愿我主马到成功，各位大人政躬安泰！\u003c/p>\n","text":"侦察兵 愿我主马到成功，各位大人政躬安泰！\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00686","html":"\u003cp class=\"epub-calibre1\">查理 你带来什么消息？快说吧。\u003c/p>\n","text":"查理 你带来什么消息？快说吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00687","html":"\u003cp class=\"epub-calibre1\">侦察兵 英国军队本是分裂为两派的，现在他们又联合起来，马上就要对您开仗。\u003c/p>\n","text":"侦察兵 英国军队本是分裂为两派的，现在他们又联合起来，马上就要对您开仗。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00688","html":"\u003cp class=\"epub-calibre1\">查理 众位贤卿，这警报来得过于仓促了，我们必须立即应敌。\u003c/p>\n","text":"查理 众位贤卿，这警报来得过于仓促了，我们必须立即应敌。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00689","html":"\u003cp class=\"epub-calibre1\">勃艮第 殿下，反正塔尔博已死，他的鬼魂不会出现，我们不必惊慌。\u003c/p>\n","text":"勃艮第 殿下，反正塔尔博已死，他的鬼魂不会出现，我们不必惊慌。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00690","html":"\u003cp class=\"epub-calibre1\">贞德 在一切卑劣的情感之中，恐惧是最最要不得的。殿下，只要您号召一声，说是非胜不可，胜利就是您的。我们要叫亨利坐立不安，要叫全世界都为他气沮。\u003c/p>\n","text":"贞德 在一切卑劣的情感之中，恐惧是最最要不得的。殿下，只要您号召一声，说是非胜不可，胜利就是您的。我们要叫亨利坐立不安，要叫全世界都为他气沮。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00691","html":"\u003cp class=\"epub-calibre1\">查理 那么，干他一下吧，贤卿们！祝我法兰西幸运无疆！\u003cb class=\"epub-calibre3\">（同下。）\u003c/b>\u003c/p>\n","text":"查理 那么，干他一下吧，贤卿们！祝我法兰西幸运无疆！（同下。）\n","sourceAnchor":null,"tag":"p"}],"heading":"第二场 法国。安佐平原","headingLevel":4,"sourceAnchor":"a487","actNumber":5,"sceneNumber":2},{"id":"part0022-section-030","label":"第五幕 · 第三场 同前。安及尔斯城前","kind":"scene","blocks":[{"id":"part0022-00692","html":"\u003ch4 id=\"epub-part0022-a488\" class=\"epub-calibre12\">第三场 同前。安及尔斯城前\u003c/h4>\n","text":"第三场 同前。安及尔斯城前\n","sourceAnchor":"a488","tag":"h4"},{"id":"part0022-00693","html":"\u003cp class=\"epub-block1\">号角声。两军对战。贞德上。\u003c/p>\n","text":"号角声。两军对战。贞德上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00694","html":"\u003cp class=\"epub-calibre1\">贞德 英国总管得胜了，法国军队崩溃了。各种各样的符箓咒语，你们救救我吧；向我预报未来事件的鬼魂们，救救我吧。\u003cb class=\"epub-calibre3\">（雷声）\u003c/b>北方鬼王的大小神差们，你们是能救苦救难的，快来解救我这次的危机吧。\u003c/p>\n","text":"贞德 英国总管得胜了，法国军队崩溃了。各种各样的符箓咒语，你们救救我吧；向我预报未来事件的鬼魂们，救救我吧。（雷声）北方鬼王的大小神差们，你们是能救苦救难的，快来解救我这次的危机吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00695","html":"\u003cp class=\"epub-block1\">众幽灵上。\u003c/p>\n","text":"众幽灵上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00696","html":"\u003cp class=\"epub-calibre1\">贞德 你们听我召唤，立刻就来，可见你们还和往常一样，是愿意为我出力的。众位熟识的精灵们，你们都是从地下王国精选出来的，请再帮一次忙，使法国获胜。\u003cb class=\"epub-calibre3\">（幽灵等来往走动，默不作声）\u003c/b>哎呀，别老不开口呀！我以前用我的血供养你们，我这一次要砍下一条胳膊送给你们，来换取你们对我更大的帮助，请你们俯允，救我一救吧。\u003cb class=\"epub-calibre3\">（幽灵等将头低垂）\u003c/b>无法挽救吗？如果你们答应我的请求，我愿将我的身子送给你们作为酬谢。\u003cb class=\"epub-calibre3\">（幽灵等摇头）\u003c/b>难道用我的身子、用我的鲜血作为祭品，都不能博得你们素常给我的援助吗？那么就把我的灵魂，我的躯体，我的一切，统统拿去，可千万别叫法国挫败在英军的手中。\u003cb class=\"epub-calibre3\">（幽灵等离去）\u003c/b>不好了，他们把我抛弃了！看起来是运数已到，法兰西必须卸下她颤巍巍的盔缨，向英格兰屈膝了。我往日使用的咒语都已不灵，我无法抵挡来自地狱的强大势力。法兰西哟，你定是一败涂地了。\u003cb class=\"epub-calibre3\">（下。）\u003c/b>\u003c/p>\n","text":"贞德 你们听我召唤，立刻就来，可见你们还和往常一样，是愿意为我出力的。众位熟识的精灵们，你们都是从地下王国精选出来的，请再帮一次忙，使法国获胜。（幽灵等来往走动，默不作声）哎呀，别老不开口呀！我以前用我的血供养你们，我这一次要砍下一条胳膊送给你们，来换取你们对我更大的帮助，请你们俯允，救我一救吧。（幽灵等将头低垂）无法挽救吗？如果你们答应我的请求，我愿将我的身子送给你们作为酬谢。（幽灵等摇头）难道用我的身子、用我的鲜血作为祭品，都不能博得你们素常给我的援助吗？那么就把我的灵魂，我的躯体，我的一切，统统拿去，可千万别叫法国挫败在英军的手中。（幽灵等离去）不好了，他们把我抛弃了！看起来是运数已到，法兰西必须卸下她颤巍巍的盔缨，向英格兰屈膝了。我往日使用的咒语都已不灵，我无法抵挡来自地狱的强大势力。法兰西哟，你定是一败涂地了。（下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00697","html":"\u003cp class=\"epub-block1\">鼓角声。两军对战。贞德重上，与约克交战，贞德被擒，法军溃退。\u003c/p>\n","text":"鼓角声。两军对战。贞德重上，与约克交战，贞德被擒，法军溃退。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00698","html":"\u003cp class=\"epub-calibre1\">约克 法国娘儿，我想我是把你牢牢地捉住了。你不妨再念念咒语试试，看能不能唤来妖精，把你救走。这次的战利品确是不坏，就是献给魔鬼也一定能蒙他赏收。瞧，那丑巫婆低下头来，怕是想用什么魔法把我变成不知怎么个模样儿呢！\u003c/p>\n","text":"约克 法国娘儿，我想我是把你牢牢地捉住了。你不妨再念念咒语试试，看能不能唤来妖精，把你救走。这次的战利品确是不坏，就是献给魔鬼也一定能蒙他赏收。瞧，那丑巫婆低下头来，怕是想用什么魔法把我变成不知怎么个模样儿呢！\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00699","html":"\u003cp class=\"epub-calibre1\">贞德 你的模样已经够坏了，没法再变得更坏了。\u003c/p>\n","text":"贞德 你的模样已经够坏了，没法再变得更坏了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00700","html":"\u003cp class=\"epub-calibre1\">约克 哦，查理太子才最中你的意，除了他的模样儿，你是谁也看不上眼的。\u003c/p>\n","text":"约克 哦，查理太子才最中你的意，除了他的模样儿，你是谁也看不上眼的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00701","html":"\u003cp class=\"epub-calibre1\">贞德 叫你和查理都遭殃！愿你们两个睡在床上都被血手掐死！\u003c/p>\n","text":"贞德 叫你和查理都遭殃！愿你们两个睡在床上都被血手掐死！\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00702","html":"\u003cp class=\"epub-calibre1\">约克 开口就咒人的泼妇，住口！\u003c/p>\n","text":"约克 开口就咒人的泼妇，住口！\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00703","html":"\u003cp class=\"epub-calibre1\">贞德 对不起，我还要咒骂一会儿。\u003c/p>\n","text":"贞德 对不起，我还要咒骂一会儿。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00704","html":"\u003cp class=\"epub-calibre1\">约克 恶贼，你要咒骂，等把你绑在火刑柱上再咒骂吧。\u003cb class=\"epub-calibre3\">（同下。）\u003c/b>\u003c/p>\n","text":"约克 恶贼，你要咒骂，等把你绑在火刑柱上再咒骂吧。（同下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00705","html":"\u003cp class=\"epub-block1\">号角声。萨福克牵玛格莱特上。\u003c/p>\n","text":"号角声。萨福克牵玛格莱特上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00706","html":"\u003cp class=\"epub-calibre1\">萨福克 不管你要怎样，你已是我的俘虏了。\u003cb class=\"epub-calibre3\">（向她注视）\u003c/b>呀，美人儿，不用害怕，不要逃跑。我除了向你施礼，决不碰你一下。我吻你的纤指，是为了预祝永久和平，你看，我又温存地把它们放到你的轻盈的腰肢那边了。你是谁家的闺秀？告诉我，我才好馨香供养呀。\u003c/p>\n","text":"萨福克 不管你要怎样，你已是我的俘虏了。（向她注视）呀，美人儿，不用害怕，不要逃跑。我除了向你施礼，决不碰你一下。我吻你的纤指，是为了预祝永久和平，你看，我又温存地把它们放到你的轻盈的腰肢那边了。你是谁家的闺秀？告诉我，我才好馨香供养呀。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00707","html":"\u003cp class=\"epub-calibre1\">玛格莱特 不管你是谁，我名叫玛格莱特，我是国王的女儿，我父亲是那不勒斯国王。\u003c/p>\n","text":"玛格莱特 不管你是谁，我名叫玛格莱特，我是国王的女儿，我父亲是那不勒斯国王。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00708","html":"\u003cp class=\"epub-calibre1\">萨福克 我也不寒伧，我是一位伯爵，萨福克是我的封号。世间稀有的宝贝儿，不要见怪，我们是前生有缘，才使你落到我的手中。我要像母天鹅保护她的小天鹅那样，把你藏在我的翅膀底下，虽说是俘虏，却是非常疼爱的。如果这样你还不称心，那你就作为萨福克的朋友，爱到哪里就到哪里去吧。\u003cb class=\"epub-calibre3\">（玛格莱特欲走开）\u003c/b>啊，等一等！我怎能放她走？我的手肯放，但我的心不肯放呀。她那昳丽的姿容，照得我眼花缭乱，好似太阳抚弄着平滑的水面，折射回来的波光炫人眼目。我很想向她求爱，但我不敢开口。我要拿过笔墨，写出我热恋的心情。呀，呸，波勒哟，你为什么这样瞧不起自己？你不是惯会甜言蜜语的吗？她不是落在你的手掌之中了吗？你见到一个娘儿们就弄得手足无措了吗？哎，的确，一张标致的面庞，真能使人神魂颠倒，连舌头也不听使唤了。\u003c/p>\n","text":"萨福克 我也不寒伧，我是一位伯爵，萨福克是我的封号。世间稀有的宝贝儿，不要见怪，我们是前生有缘，才使你落到我的手中。我要像母天鹅保护她的小天鹅那样，把你藏在我的翅膀底下，虽说是俘虏，却是非常疼爱的。如果这样你还不称心，那你就作为萨福克的朋友，爱到哪里就到哪里去吧。（玛格莱特欲走开）啊，等一等！我怎能放她走？我的手肯放，但我的心不肯放呀。她那昳丽的姿容，照得我眼花缭乱，好似太阳抚弄着平滑的水面，折射回来的波光炫人眼目。我很想向她求爱，但我不敢开口。我要拿过笔墨，写出我热恋的心情。呀，呸，波勒哟，你为什么这样瞧不起自己？你不是惯会甜言蜜语的吗？她不是落在你的手掌之中了吗？你见到一个娘儿们就弄得手足无措了吗？哎，的确，一张标致的面庞，真能使人神魂颠倒，连舌头也不听使唤了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00709","html":"\u003cp class=\"epub-calibre1\">玛格莱特 请问你，萨福克伯爵——如果我没有弄错你的名字——你要多少赎金才肯放我？我这样问你，因为看光景我已是你的俘虏了。\u003c/p>\n","text":"玛格莱特 请问你，萨福克伯爵——如果我没有弄错你的名字——你要多少赎金才肯放我？我这样问你，因为看光景我已是你的俘虏了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00710","html":"\u003cp class=\"epub-calibre1\">萨福克 \u003cb class=\"epub-calibre3\">（旁白）\u003c/b>你还没有试一试向她求爱，你怎能断定她会拒绝你？\u003c/p>\n","text":"萨福克 （旁白）你还没有试一试向她求爱，你怎能断定她会拒绝你？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00711","html":"\u003cp class=\"epub-calibre1\">玛格莱特 你为什么不回答我？要我出多少赎金？\u003c/p>\n","text":"玛格莱特 你为什么不回答我？要我出多少赎金？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00712","html":"\u003cp class=\"epub-calibre1\">萨福克 \u003cb class=\"epub-calibre3\">（旁白）\u003c/b>她既是美如天仙，就该向她求爱；她既是个女人，就可以将她占有。\u003c/p>\n","text":"萨福克 （旁白）她既是美如天仙，就该向她求爱；她既是个女人，就可以将她占有。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00713","html":"\u003cp class=\"epub-calibre1\">玛格莱特 你肯不肯接受赎金？你肯还是不肯？\u003c/p>\n","text":"玛格莱特 你肯不肯接受赎金？你肯还是不肯？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00714","html":"\u003cp class=\"epub-calibre1\">萨福克 \u003cb class=\"epub-calibre3\">（旁白）\u003c/b>痴情人呵，你已经有了老婆，你忘了吗？你怎能又把玛格莱特当作情妇？\u003c/p>\n","text":"萨福克 （旁白）痴情人呵，你已经有了老婆，你忘了吗？你怎能又把玛格莱特当作情妇？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00715","html":"\u003cp class=\"epub-calibre1\">玛格莱特 我说的话，他好似不愿听，我走吧。\u003c/p>\n","text":"玛格莱特 我说的话，他好似不愿听，我走吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00716","html":"\u003cp class=\"epub-calibre1\">萨福克 \u003cb class=\"epub-calibre3\">（旁白）\u003c/b>想到这里，事情就难办了，好似浇了一盆冷水。\u003c/p>\n","text":"萨福克 （旁白）想到这里，事情就难办了，好似浇了一盆冷水。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00717","html":"\u003cp class=\"epub-calibre1\">玛格莱特 他乱七八糟的说的是些什么话？这人一定是疯了。\u003c/p>\n","text":"玛格莱特 他乱七八糟的说的是些什么话？这人一定是疯了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00718","html":"\u003cp class=\"epub-calibre1\">萨福克 \u003cb class=\"epub-calibre3\">（旁白）\u003c/b>可是办法总是有的。\u003c/p>\n","text":"萨福克 （旁白）可是办法总是有的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00719","html":"\u003cp class=\"epub-calibre1\">玛格莱特 可是我请你答复我。\u003c/p>\n","text":"玛格莱特 可是我请你答复我。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00720","html":"\u003cp class=\"epub-calibre1\">萨福克 \u003cb class=\"epub-calibre3\">（旁白）\u003c/b>我一定把玛格莱特郡主弄到手。弄给谁呢？哼，给我们的王上。嗨，木头脑瓜子！\u003c/p>\n","text":"萨福克 （旁白）我一定把玛格莱特郡主弄到手。弄给谁呢？哼，给我们的王上。嗨，木头脑瓜子！\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00721","html":"\u003cp class=\"epub-calibre1\">玛格莱特 \u003cb class=\"epub-calibre3\">（偶然听到）\u003c/b>他在说到什么木头，他大概是个木匠吧。\u003c/p>\n","text":"玛格莱特 （偶然听到）他在说到什么木头，他大概是个木匠吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00722","html":"\u003cp class=\"epub-calibre1\">萨福克 \u003cb class=\"epub-calibre3\">（旁白）\u003c/b>这样一来，我的想头也能实现了，两国之间也可以言归于好了。不过这其中还有一层顾虑：她父亲虽是那不勒斯国王，兼任安佐和缅因公爵，可是他财产不丰，只怕我们的大臣们未必赞同这门亲事。\u003c/p>\n","text":"萨福克 （旁白）这样一来，我的想头也能实现了，两国之间也可以言归于好了。不过这其中还有一层顾虑：她父亲虽是那不勒斯国王，兼任安佐和缅因公爵，可是他财产不丰，只怕我们的大臣们未必赞同这门亲事。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00723","html":"\u003cp class=\"epub-calibre1\">玛格莱特 听见吗，将军？你现在没有空闲吗？\u003c/p>\n","text":"玛格莱特 听见吗，将军？你现在没有空闲吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00724","html":"\u003cp class=\"epub-calibre1\">萨福克 \u003cb class=\"epub-calibre3\">（旁白）\u003c/b>一定这样办，他们反对也反不了的。亨利还年轻，他一听说是位美貌佳人，他耳朵就会软的。郡主，我要跟你谈一件秘密事。\u003c/p>\n","text":"萨福克 （旁白）一定这样办，他们反对也反不了的。亨利还年轻，他一听说是位美貌佳人，他耳朵就会软的。郡主，我要跟你谈一件秘密事。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00725","html":"\u003cp class=\"epub-calibre1\">玛格莱特 \u003cb class=\"epub-calibre3\">（旁白）\u003c/b>我现在被他捉住，他不会有什么歹意吧？看上去他还是个正派的骑士，大概不至于糟蹋我。\u003c/p>\n","text":"玛格莱特 （旁白）我现在被他捉住，他不会有什么歹意吧？看上去他还是个正派的骑士，大概不至于糟蹋我。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00726","html":"\u003cp class=\"epub-calibre1\">萨福克 小姐，请垂听我的话。\u003c/p>\n","text":"萨福克 小姐，请垂听我的话。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00727","html":"\u003cp class=\"epub-calibre1\">玛格莱特 \u003cb class=\"epub-calibre3\">（旁白）\u003c/b>法国军队也许能救我出去，我就不须恳求他的优待了。\u003c/p>\n","text":"玛格莱特 （旁白）法国军队也许能救我出去，我就不须恳求他的优待了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00728","html":"\u003cp class=\"epub-calibre1\">萨福克 温柔的小姐，请听我谈一件正经事——\u003c/p>\n","text":"萨福克 温柔的小姐，请听我谈一件正经事——\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00729","html":"\u003cp class=\"epub-calibre1\">玛格莱特 算了，女人向来是受人摆布的。\u003c/p>\n","text":"玛格莱特 算了，女人向来是受人摆布的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00730","html":"\u003cp class=\"epub-calibre1\">萨福克 小姐，你为什么说这话呀？\u003c/p>\n","text":"萨福克 小姐，你为什么说这话呀？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00731","html":"\u003cp class=\"epub-calibre1\">玛格莱特 我向你乞怜，还不就是这么一回事。\u003c/p>\n","text":"玛格莱特 我向你乞怜，还不就是这么一回事。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00732","html":"\u003cp class=\"epub-calibre1\">萨福克 我说，温良的郡主，如果你这次被俘，由此而成为一国的王后，你不觉得你的拘禁是幸福的吗？\u003c/p>\n","text":"萨福克 我说，温良的郡主，如果你这次被俘，由此而成为一国的王后，你不觉得你的拘禁是幸福的吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00733","html":"\u003cp class=\"epub-calibre1\">玛格莱特 在拘禁中当王后比在下贱的奴役中当奴才更糟糕，君王们应该是自由的。\u003c/p>\n","text":"玛格莱特 在拘禁中当王后比在下贱的奴役中当奴才更糟糕，君王们应该是自由的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00734","html":"\u003cp class=\"epub-calibre1\">萨福克 如果幸福的英国王上是自由的，你也就是自由的。\u003c/p>\n","text":"萨福克 如果幸福的英国王上是自由的，你也就是自由的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00735","html":"\u003cp class=\"epub-calibre1\">玛格莱特 怎么，他的自由与我何干？\u003c/p>\n","text":"玛格莱特 怎么，他的自由与我何干？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00736","html":"\u003cp class=\"epub-calibre1\">萨福克 我要设法使你成为亨利的王后，使你手里拿着金色的皇杖，头上戴着贵重的王冠，只要你俯允做我的——\u003c/p>\n","text":"萨福克 我要设法使你成为亨利的王后，使你手里拿着金色的皇杖，头上戴着贵重的王冠，只要你俯允做我的——\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00737","html":"\u003cp class=\"epub-calibre1\">玛格莱特 什么？\u003c/p>\n","text":"玛格莱特 什么？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00738","html":"\u003cp class=\"epub-calibre1\">萨福克 他的爱人。\u003c/p>\n","text":"萨福克 他的爱人。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00739","html":"\u003cp class=\"epub-calibre1\">玛格莱特 我不配当亨利的妻子。\u003c/p>\n","text":"玛格莱特 我不配当亨利的妻子。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00740","html":"\u003cp class=\"epub-calibre1\">萨福克 不，温良的小姐，我替他求得这样一位标致的小姐做妻子，这桩好事却于我无份，我才是不配呢。小姐，你对这门亲事有什么意见？满意不满意？\u003c/p>\n","text":"萨福克 不，温良的小姐，我替他求得这样一位标致的小姐做妻子，这桩好事却于我无份，我才是不配呢。小姐，你对这门亲事有什么意见？满意不满意？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00741","html":"\u003cp class=\"epub-calibre1\">玛格莱特 如果中我父亲的意，我就满意。\u003c/p>\n","text":"玛格莱特 如果中我父亲的意，我就满意。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00742","html":"\u003cp class=\"epub-calibre1\">萨福克 那我就召集我们的将领，展开我们的旌旗，小姐，我们到你父亲的城边，要求一次会谈，来商量这件事。\u003cb class=\"epub-calibre3\">（队伍向前移动。）\u003c/b>\u003c/p>\n","text":"萨福克 那我就召集我们的将领，展开我们的旌旗，小姐，我们到你父亲的城边，要求一次会谈，来商量这件事。（队伍向前移动。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00743","html":"\u003cp class=\"epub-block1\">吹起议和的军号。瑞尼埃上城头。\u003c/p>\n","text":"吹起议和的军号。瑞尼埃上城头。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00744","html":"\u003cp class=\"epub-calibre1\">萨福克 看吧，瑞尼埃，看！你的女儿成为俘虏啦！\u003c/p>\n","text":"萨福克 看吧，瑞尼埃，看！你的女儿成为俘虏啦！\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00745","html":"\u003cp class=\"epub-calibre1\">瑞尼埃 被谁俘去的？\u003c/p>\n","text":"瑞尼埃 被谁俘去的？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00746","html":"\u003cp class=\"epub-calibre1\">萨福克 被我。\u003c/p>\n","text":"萨福克 被我。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00747","html":"\u003cp class=\"epub-calibre1\">瑞尼埃 萨福克，你要怎么办？我是一个军人，我不会因为碰到倒楣的事，就哭哭啼啼，呼天抢地的。\u003c/p>\n","text":"瑞尼埃 萨福克，你要怎么办？我是一个军人，我不会因为碰到倒楣的事，就哭哭啼啼，呼天抢地的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00748","html":"\u003cp class=\"epub-calibre1\">萨福克 是的，办法尽有，殿下。只要你应允，只要你慨然应允，将你女儿嫁给英王，一切都好办啦。我费了一番唇舌，向令嫒提亲，得到她的同意。她受了一次不太吃苦的囚禁，却获得了至高无上的自由。\u003c/p>\n","text":"萨福克 是的，办法尽有，殿下。只要你应允，只要你慨然应允，将你女儿嫁给英王，一切都好办啦。我费了一番唇舌，向令嫒提亲，得到她的同意。她受了一次不太吃苦的囚禁，却获得了至高无上的自由。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00749","html":"\u003cp class=\"epub-calibre1\">瑞尼埃 萨福克说的是真心话吗？\u003c/p>\n","text":"瑞尼埃 萨福克说的是真心话吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00750","html":"\u003cp class=\"epub-calibre1\">萨福克 你问你的女儿就知道了，我是从不虚情假意、口是心非的。\u003c/p>\n","text":"萨福克 你问你的女儿就知道了，我是从不虚情假意、口是心非的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00751","html":"\u003cp class=\"epub-calibre1\">瑞尼埃 凭着你的冠冕堂皇的保证，我下城来答复你的正当的请求。\u003cb class=\"epub-calibre3\">（从城头下。）\u003c/b>\u003c/p>\n","text":"瑞尼埃 凭着你的冠冕堂皇的保证，我下城来答复你的正当的请求。（从城头下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00752","html":"\u003cp class=\"epub-calibre1\">萨福克 我在这里恭候了。\u003c/p>\n","text":"萨福克 我在这里恭候了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00753","html":"\u003cp class=\"epub-block1\">吹奏喇叭。瑞尼埃来至城下。\u003c/p>\n","text":"吹奏喇叭。瑞尼埃来至城下。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00754","html":"\u003cp class=\"epub-calibre1\">瑞尼埃 英勇的伯爵，欢迎你到敝境来，在安佐郡内，尊驾如有吩咐，无不从命。\u003c/p>\n","text":"瑞尼埃 英勇的伯爵，欢迎你到敝境来，在安佐郡内，尊驾如有吩咐，无不从命。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00755","html":"\u003cp class=\"epub-calibre1\">萨福克 多谢，瑞尼埃，你有这样温柔的一位千金，能和国君匹配，你是好福气呵。殿下对于我的请求，有何高见？\u003c/p>\n","text":"萨福克 多谢，瑞尼埃，你有这样温柔的一位千金，能和国君匹配，你是好福气呵。殿下对于我的请求，有何高见？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00756","html":"\u003cp class=\"epub-calibre1\">瑞尼埃 承蒙眷顾，为小女做媒，配给英国大君主为妻，我只要求安享我缅因与安佐两郡之地，不受外力压迫，不受战争惊扰，如能同意我这个条件，我就应允将女儿嫁给亨利。\u003c/p>\n","text":"瑞尼埃 承蒙眷顾，为小女做媒，配给英国大君主为妻，我只要求安享我缅因与安佐两郡之地，不受外力压迫，不受战争惊扰，如能同意我这个条件，我就应允将女儿嫁给亨利。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00757","html":"\u003cp class=\"epub-calibre1\">萨福克 这就作为她的赎金，我将她交还给你。至于那两郡之地，我一定尽力说合，保证殿下可以安享无虞。\u003c/p>\n","text":"萨福克 这就作为她的赎金，我将她交还给你。至于那两郡之地，我一定尽力说合，保证殿下可以安享无虞。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00758","html":"\u003cp class=\"epub-calibre1\">瑞尼埃 我再一次表示我同意将小女许配给英王，今天一言为定，望你以亨利陛下的名义，代表那位仁慈的君王，接受我的诚意。\u003c/p>\n","text":"瑞尼埃 我再一次表示我同意将小女许配给英王，今天一言为定，望你以亨利陛下的名义，代表那位仁慈的君王，接受我的诚意。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00759","html":"\u003cp class=\"epub-calibre1\">萨福克 法兰西的瑞尼埃，我对你表示王室的谢意，这是咱们为国王办的事。\u003cb class=\"epub-calibre3\">（旁白）\u003c/b>可是如果这件婚事是为我自己办的，那就更妙了。我马上返回英国，报告这个喜讯，筹备结婚大典。再见，瑞尼埃，把你这颗掌上明珠放在黄金屋里，好好保藏着吧。\u003c/p>\n","text":"萨福克 法兰西的瑞尼埃，我对你表示王室的谢意，这是咱们为国王办的事。（旁白）可是如果这件婚事是为我自己办的，那就更妙了。我马上返回英国，报告这个喜讯，筹备结婚大典。再见，瑞尼埃，把你这颗掌上明珠放在黄金屋里，好好保藏着吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00760","html":"\u003cp class=\"epub-calibre1\">瑞尼埃 我拥抱你，如同我拥抱那位信奉基督教的君主亨利一样，如果他是在这里的话。\u003c/p>\n","text":"瑞尼埃 我拥抱你，如同我拥抱那位信奉基督教的君主亨利一样，如果他是在这里的话。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00761","html":"\u003cp class=\"epub-calibre1\">玛格莱特 再见，大人，玛格莱特向萨福克致以无穷的敬意和祝福。\u003cb class=\"epub-calibre3\">（欲行。）\u003c/b>\u003c/p>\n","text":"玛格莱特 再见，大人，玛格莱特向萨福克致以无穷的敬意和祝福。（欲行。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00762","html":"\u003cp class=\"epub-calibre1\">萨福克 再见，温柔的小姐。且慢，玛格莱特，你对我的王上不想说几句颂词吗？\u003c/p>\n","text":"萨福克 再见，温柔的小姐。且慢，玛格莱特，你对我的王上不想说几句颂词吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00763","html":"\u003cp class=\"epub-calibre1\">玛格莱特 请你为我转致适合于一个待字的女子、一个臣下对君王的颂词吧。\u003c/p>\n","text":"玛格莱特 请你为我转致适合于一个待字的女子、一个臣下对君王的颂词吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00764","html":"\u003cp class=\"epub-calibre1\">萨福克 这句话真是既得体，又动听。不过，小姐，我还得麻烦你，你没有一件定情的礼物送给我的王上吗？\u003c/p>\n","text":"萨福克 这句话真是既得体，又动听。不过，小姐，我还得麻烦你，你没有一件定情的礼物送给我的王上吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00765","html":"\u003cp class=\"epub-calibre1\">玛格莱特 有的，大人，我献给王上一颗纯洁无瑕的、从未动情过的处女的心。\u003c/p>\n","text":"玛格莱特 有的，大人，我献给王上一颗纯洁无瑕的、从未动情过的处女的心。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00766","html":"\u003cp class=\"epub-calibre1\">萨福克 还有这一吻。\u003cb class=\"epub-calibre3\">（吻玛格莱特。）\u003c/b>\u003c/p>\n","text":"萨福克 还有这一吻。（吻玛格莱特。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00767","html":"\u003cp class=\"epub-calibre1\">玛格莱特 那只能代表你自己。这样粗疏的礼物，我不能冒昧地献给王上。\u003cb class=\"epub-calibre3\">（瑞尼埃、玛格莱特同下。）\u003c/b>\u003c/p>\n","text":"玛格莱特 那只能代表你自己。这样粗疏的礼物，我不能冒昧地献给王上。（瑞尼埃、玛格莱特同下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00768","html":"\u003cp class=\"epub-calibre1\">萨福克 啊，我自己若能弄你到手，那是多么好！可是，且慢，萨福克，不要再心猿意马啦，这样下去是危险的。替她多说几句好话，去打动亨利的心。要多吹嘘她的过人的贤淑，她不假修饰而独具的自然丰韵。在海上的旅途中，我要把这些绘声绘影的词句多温习几遍，以便晋见亨利王上的时候，说得天花乱坠，使他不能不堕入彀中。\u003cb class=\"epub-calibre3\">（下。）\u003c/b>\u003c/p>\n","text":"萨福克 啊，我自己若能弄你到手，那是多么好！可是，且慢，萨福克，不要再心猿意马啦，这样下去是危险的。替她多说几句好话，去打动亨利的心。要多吹嘘她的过人的贤淑，她不假修饰而独具的自然丰韵。在海上的旅途中，我要把这些绘声绘影的词句多温习几遍，以便晋见亨利王上的时候，说得天花乱坠，使他不能不堕入彀中。（下。）\n","sourceAnchor":null,"tag":"p"}],"heading":"第三场 同前。安及尔斯城前","headingLevel":4,"sourceAnchor":"a488","actNumber":5,"sceneNumber":3},{"id":"part0022-section-031","label":"第五幕 · 第四场 同前。安佐境内约克公爵营帐","kind":"scene","blocks":[{"id":"part0022-00769","html":"\u003ch4 id=\"epub-part0022-a489\" class=\"epub-calibre12\">第四场 同前。安佐境内约克公爵营帐\u003c/h4>\n","text":"第四场 同前。安佐境内约克公爵营帐\n","sourceAnchor":"a489","tag":"h4"},{"id":"part0022-00770","html":"\u003cp class=\"epub-block1\">约克、华列克及余人上。\u003c/p>\n","text":"约克、华列克及余人上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00771","html":"\u003cp class=\"epub-calibre1\">约克 将那判决受火刑的巫婆带上来。\u003c/p>\n","text":"约克 将那判决受火刑的巫婆带上来。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00772","html":"\u003cp class=\"epub-block1\">兵士押贞德上，一牧羊老人随上。\u003c/p>\n","text":"兵士押贞德上，一牧羊老人随上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00773","html":"\u003cp class=\"epub-calibre1\">牧人 哎呀，贞德呀，你父亲的心肝要碎啦！我走遍了全国，到处找你，今天是找到了，却要看着你死于非命吗？唉，贞德，我心爱的女儿贞德呀，你死我就和你同死！\u003c/p>\n","text":"牧人 哎呀，贞德呀，你父亲的心肝要碎啦！我走遍了全国，到处找你，今天是找到了，却要看着你死于非命吗？唉，贞德，我心爱的女儿贞德呀，你死我就和你同死！\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00774","html":"\u003cp class=\"epub-calibre1\">贞德 老朽的守财奴！下贱的可怜虫！我出身高贵，哪有你这父亲，哪有你这朋友！\u003c/p>\n","text":"贞德 老朽的守财奴！下贱的可怜虫！我出身高贵，哪有你这父亲，哪有你这朋友！\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00775","html":"\u003cp class=\"epub-calibre1\">牧人 哪里的话，哪里的话！众位大人，别信她。她是我生的，全教区都知道。她母亲还活着，她能证明贞德是我头生的女儿。\u003c/p>\n","text":"牧人 哪里的话，哪里的话！众位大人，别信她。她是我生的，全教区都知道。她母亲还活着，她能证明贞德是我头生的女儿。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00776","html":"\u003cp class=\"epub-calibre1\">华列克 没人伦的东西！你连亲生的父亲也不认吗？\u003c/p>\n","text":"华列克 没人伦的东西！你连亲生的父亲也不认吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00777","html":"\u003cp class=\"epub-calibre1\">约克 这就说明她一生是个什么样的人，极邪极恶，这样处死她毫不足惜。\u003c/p>\n","text":"约克 这就说明她一生是个什么样的人，极邪极恶，这样处死她毫不足惜。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00778","html":"\u003cp class=\"epub-calibre1\">牧人 呀，贞德，你怎么这样倔强？上帝鉴察，你明明是我的亲骨血，我不知为你哭过多少次啦。我求求你，我的好贞德，认了我吧。\u003c/p>\n","text":"牧人 呀，贞德，你怎么这样倔强？上帝鉴察，你明明是我的亲骨血，我不知为你哭过多少次啦。我求求你，我的好贞德，认了我吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00779","html":"\u003cp class=\"epub-calibre1\">贞德 乡下人，走开！你是故意替他们做假证人来诬蔑我的高贵出身的。\u003c/p>\n","text":"贞德 乡下人，走开！你是故意替他们做假证人来诬蔑我的高贵出身的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00780","html":"\u003cp class=\"epub-calibre1\">牧人 真的，我和她母亲结婚的那天早晨，我是付出一块金洋给那牧师的。跪下来接受我的祝福吧，我的好女儿。怎么，你不肯下跪吗？叫你从出生的日子起就倒楣！我愿你母亲喂你的乳汁变成杀鼠的毒药！要不然，我就愿你在替我放羊的时候被贪馋的豺狼吃掉！你这狠心的婊子，连父亲都不认吗？好，烧死她，烧死她！若是吊死她，就太便宜她了。\u003cb class=\"epub-calibre3\">（下。）\u003c/b>\u003c/p>\n","text":"牧人 真的，我和她母亲结婚的那天早晨，我是付出一块金洋给那牧师的。跪下来接受我的祝福吧，我的好女儿。怎么，你不肯下跪吗？叫你从出生的日子起就倒楣！我愿你母亲喂你的乳汁变成杀鼠的毒药！要不然，我就愿你在替我放羊的时候被贪馋的豺狼吃掉！你这狠心的婊子，连父亲都不认吗？好，烧死她，烧死她！若是吊死她，就太便宜她了。（下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00781","html":"\u003cp class=\"epub-calibre1\">约克 把她带走，这种伤风败俗的贱人，在世上已经活得太久了。\u003c/p>\n","text":"约克 把她带走，这种伤风败俗的贱人，在世上已经活得太久了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00782","html":"\u003cp class=\"epub-calibre1\">贞德 先让我告诉你们被你们判处死刑的是个什么人。我不是牧羊的村夫所生，我乃是皇族的苗裔。我志行芳洁，气宇神明。我受上天的鼓舞，来到人世，要做下一番惊天动地的事业。我从来没有差遣过邪魔恶鬼。只因你们被肉欲冲昏了头脑，被无辜者的鲜血沾染了灵魂；只因你们无恶不作，腐朽不堪，缺乏一般人所具有的恻隐之心；所以你们才认为除了乞援于恶鬼，就不能创造奇迹。错了，你们这些坚持谬见的人！贞德从降生以来就是一个贞女，她的心地是纯洁无疵的，她惨遭你们的屠杀，她要上叩天阍，申求昭雪。\u003c/p>\n","text":"贞德 先让我告诉你们被你们判处死刑的是个什么人。我不是牧羊的村夫所生，我乃是皇族的苗裔。我志行芳洁，气宇神明。我受上天的鼓舞，来到人世，要做下一番惊天动地的事业。我从来没有差遣过邪魔恶鬼。只因你们被肉欲冲昏了头脑，被无辜者的鲜血沾染了灵魂；只因你们无恶不作，腐朽不堪，缺乏一般人所具有的恻隐之心；所以你们才认为除了乞援于恶鬼，就不能创造奇迹。错了，你们这些坚持谬见的人！贞德从降生以来就是一个贞女，她的心地是纯洁无疵的，她惨遭你们的屠杀，她要上叩天阍，申求昭雪。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00783","html":"\u003cp class=\"epub-center\">\u003cimg src=\"data/chinese-collection/images/00112.jpeg\" alt=\"\" loading=\"lazy\" class=\"epub-calibre2 epub-image\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00784","html":"\u003cp class=\"epub-calibre1\">约克 嗯，嗯，把她带走，立即行刑！\u003c/p>\n","text":"约克 嗯，嗯，把她带走，立即行刑！\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00785","html":"\u003cp class=\"epub-calibre1\">华列克 众位，请听我说。姑念她是一个女子，你们在火刑柱前，多堆一些柴草，浇上几桶油脂，让她死得快些，少受一些折磨。\u003c/p>\n","text":"华列克 众位，请听我说。姑念她是一个女子，你们在火刑柱前，多堆一些柴草，浇上几桶油脂，让她死得快些，少受一些折磨。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00786","html":"\u003cp class=\"epub-calibre1\">贞德 我说了半晌，还不能叫你们回心转意吗？那么，贞德，宣布你的隐衷吧，依照法律，你是应当受照顾的。嗜杀的凶手们，告诉你，我是个孕妇。你们只能叫我本人惨死，你们不能杀害我胎里的婴儿。\u003c/p>\n","text":"贞德 我说了半晌，还不能叫你们回心转意吗？那么，贞德，宣布你的隐衷吧，依照法律，你是应当受照顾的。嗜杀的凶手们，告诉你，我是个孕妇。你们只能叫我本人惨死，你们不能杀害我胎里的婴儿。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00787","html":"\u003cp class=\"epub-calibre1\">约克 皇天不许的！圣女竟会怀胎！\u003c/p>\n","text":"约克 皇天不许的！圣女竟会怀胎！\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00788","html":"\u003cp class=\"epub-calibre1\">华列克 这要算是你干下的最伟大的奇迹了。你那样的规行矩步，居然也干出这等事来。\u003c/p>\n","text":"华列克 这要算是你干下的最伟大的奇迹了。你那样的规行矩步，居然也干出这等事来。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00789","html":"\u003cp class=\"epub-calibre1\">约克 她跟那太子一向就是鬼鬼祟祟的，我早料到她会以此为借口来要求活命的。\u003c/p>\n","text":"约克 她跟那太子一向就是鬼鬼祟祟的，我早料到她会以此为借口来要求活命的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00790","html":"\u003cp class=\"epub-calibre1\">华列克 哼，想得美；我们偏不饶私生子的命，特别是查理的孽种。\u003c/p>\n","text":"华列克 哼，想得美；我们偏不饶私生子的命，特别是查理的孽种。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00791","html":"\u003cp class=\"epub-calibre1\">贞德 我是骗你们的，我的孩子不是他的，阿朗松才和我有过爱情。\u003c/p>\n","text":"贞德 我是骗你们的，我的孩子不是他的，阿朗松才和我有过爱情。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00792","html":"\u003cp class=\"epub-calibre1\">约克 阿朗松！那个臭名昭彰的恶霸！这孩子非死不可，即便他有一千条命也叫他活不成。\u003c/p>\n","text":"约克 阿朗松！那个臭名昭彰的恶霸！这孩子非死不可，即便他有一千条命也叫他活不成。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00793","html":"\u003cp class=\"epub-calibre1\">贞德 啊，对不起，我又骗了你们了。也不是查理，也不是阿朗松，是那不勒斯的国王瑞尼埃。\u003c/p>\n","text":"贞德 啊，对不起，我又骗了你们了。也不是查理，也不是阿朗松，是那不勒斯的国王瑞尼埃。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00794","html":"\u003cp class=\"epub-calibre1\">华列克 一个已经有老婆的人！那更叫人不能容忍！\u003c/p>\n","text":"华列克 一个已经有老婆的人！那更叫人不能容忍！\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00795","html":"\u003cp class=\"epub-calibre1\">约克 呸，这还算是个大姑娘哪！我看她相好的实在太多了，她简直不知道指控谁好。\u003c/p>\n","text":"约克 呸，这还算是个大姑娘哪！我看她相好的实在太多了，她简直不知道指控谁好。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00796","html":"\u003cp class=\"epub-calibre1\">华列克 可见得她是一个放荡的女人。\u003c/p>\n","text":"华列克 可见得她是一个放荡的女人。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00797","html":"\u003cp class=\"epub-calibre1\">约克 可是她还自称为童贞女哪。淫妇，凭你自己的话，就该把你和你那小杂种处死。不要讨饶了，怎么说也不行。\u003c/p>\n","text":"约克 可是她还自称为童贞女哪。淫妇，凭你自己的话，就该把你和你那小杂种处死。不要讨饶了，怎么说也不行。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00798","html":"\u003cp class=\"epub-calibre1\">贞德 把我带走吧，我要咒骂你们一顿：叫你们居住的地方永远照不到太阳的荣光，叫你们的周围尽是黑暗和死亡的阴影，叫各种各样的灾祸逼你们去上吊，或者折断你们的颈项！\u003cb class=\"epub-calibre3\">（押下。）\u003c/b>\u003c/p>\n","text":"贞德 把我带走吧，我要咒骂你们一顿：叫你们居住的地方永远照不到太阳的荣光，叫你们的周围尽是黑暗和死亡的阴影，叫各种各样的灾祸逼你们去上吊，或者折断你们的颈项！（押下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00799","html":"\u003cp class=\"epub-calibre1\">约克 你这来自地狱的恶阴差，叫你碎成齑粉，化为灰尘！\u003c/p>\n","text":"约克 你这来自地狱的恶阴差，叫你碎成齑粉，化为灰尘！\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00800","html":"\u003cp class=\"epub-block1\">波福红衣主教即温彻斯特率侍从上。\u003c/p>\n","text":"波福红衣主教即温彻斯特率侍从上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00801","html":"\u003cp class=\"epub-calibre1\">红衣主教 总管大人，我携带王上的谕旨特来和您联系。奉告两位大人，有几个信奉基督教的国家，有感于频年战祸，民不聊生，竭力劝导我国与发愤图强的法国进行和解，法国太子率领他的廷臣不久就要到来，和我们议和。\u003c/p>\n","text":"红衣主教 总管大人，我携带王上的谕旨特来和您联系。奉告两位大人，有几个信奉基督教的国家，有感于频年战祸，民不聊生，竭力劝导我国与发愤图强的法国进行和解，法国太子率领他的廷臣不久就要到来，和我们议和。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00802","html":"\u003cp class=\"epub-calibre1\">约克 我们多年的努力就得到这样的结果吗？我们多少贵族、多少将军、多少骑士、多少士兵，一个个为了国家的利益，奋不顾身，战死沙场，到末了只落得个委屈求和吗？我们的先人苦战得来的城市，不是大部分都被阴谋诡计所卖而丧失了吗？唉，华列克，华列克！我痛心地预料到，我们在法兰西的领土将要丧失无余了。\u003c/p>\n","text":"约克 我们多年的努力就得到这样的结果吗？我们多少贵族、多少将军、多少骑士、多少士兵，一个个为了国家的利益，奋不顾身，战死沙场，到末了只落得个委屈求和吗？我们的先人苦战得来的城市，不是大部分都被阴谋诡计所卖而丧失了吗？唉，华列克，华列克！我痛心地预料到，我们在法兰西的领土将要丧失无余了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00803","html":"\u003cp class=\"epub-calibre1\">华列克 宽心点，约克。如果和议成功，我们一定规定下严厉的条款，使法国人讨不到任何便宜。\u003c/p>\n","text":"华列克 宽心点，约克。如果和议成功，我们一定规定下严厉的条款，使法国人讨不到任何便宜。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00804","html":"\u003cp class=\"epub-block1\">查理率扈从上，阿朗松、奥尔良庶子、瑞尼埃及余人随上。\u003c/p>\n","text":"查理率扈从上，阿朗松、奥尔良庶子、瑞尼埃及余人随上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00805","html":"\u003cp class=\"epub-calibre1\">查理 英国的列位爵爷，我们双方既已同意在法兰西境内缔结和约，我们特来听取你们提出什么条款。\u003c/p>\n","text":"查理 英国的列位爵爷，我们双方既已同意在法兰西境内缔结和约，我们特来听取你们提出什么条款。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00806","html":"\u003cp class=\"epub-calibre1\">约克 温彻斯特，请你说吧。我一见到可恨的敌人，不由得怒气填胸，噎得我说不出话来。\u003c/p>\n","text":"约克 温彻斯特，请你说吧。我一见到可恨的敌人，不由得怒气填胸，噎得我说不出话来。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00807","html":"\u003cp class=\"epub-calibre1\">红衣主教 查理和众人听着。奉英王陛下谕旨：“本王仁厚为怀，不忍尔国人民流离失所，特准签订和约，俾尔等稍抒喘息，尔即应仰体德意，俯首称臣。”查理，如果你向我王矢效忠诚，他就任命你为法国总督，你同时还可享有国王的待遇。\u003c/p>\n","text":"红衣主教 查理和众人听着。奉英王陛下谕旨：“本王仁厚为怀，不忍尔国人民流离失所，特准签订和约，俾尔等稍抒喘息，尔即应仰体德意，俯首称臣。”查理，如果你向我王矢效忠诚，他就任命你为法国总督，你同时还可享有国王的待遇。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00808","html":"\u003cp class=\"epub-calibre1\">阿朗松 这样他就只剩一个空衔了。他头上虽然戴着王冠，但在实权上他将与平民无异。这样的条件是太苛刻了。\u003c/p>\n","text":"阿朗松 这样他就只剩一个空衔了。他头上虽然戴着王冠，但在实权上他将与平民无异。这样的条件是太苛刻了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00809","html":"\u003cp class=\"epub-calibre1\">查理 大家都知道，法国土地已有一大部分在我的掌握之中，而且在这些地区以内，我被公认为合法的国王。我岂能为了企图收复其余的领土，反把我原已享有的实权大大削弱，仅担任全境总督一个空名？不行，钦差大人，我宁愿保持我原有的东西，不愿为了贪多，反使恢复全境的希望落空。\u003c/p>\n","text":"查理 大家都知道，法国土地已有一大部分在我的掌握之中，而且在这些地区以内，我被公认为合法的国王。我岂能为了企图收复其余的领土，反把我原已享有的实权大大削弱，仅担任全境总督一个空名？不行，钦差大人，我宁愿保持我原有的东西，不愿为了贪多，反使恢复全境的希望落空。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00810","html":"\u003cp class=\"epub-calibre1\">约克 傲慢无礼的查理！你偷偷摸摸地请人出来调停，及至进行和议，你又把你幻想能得到的东西来和我们提出的条件比较，争多较少，推三阻四。要么你就接受我们王上赏给你的头衔——其实你并无丝毫贡献值得封赏，要么我们就对你大动干戈，使你不得安宁。\u003c/p>\n","text":"约克 傲慢无礼的查理！你偷偷摸摸地请人出来调停，及至进行和议，你又把你幻想能得到的东西来和我们提出的条件比较，争多较少，推三阻四。要么你就接受我们王上赏给你的头衔——其实你并无丝毫贡献值得封赏，要么我们就对你大动干戈，使你不得安宁。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00811","html":"\u003cp class=\"epub-calibre1\">瑞尼埃 殿下，关于和约条文，不要过于固执、吹毛求疵吧。难得能够和平解决，机会一错过，就再也不来了。\u003c/p>\n","text":"瑞尼埃 殿下，关于和约条文，不要过于固执、吹毛求疵吧。难得能够和平解决，机会一错过，就再也不来了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00812","html":"\u003cp class=\"epub-calibre1\">阿朗松 \u003cb class=\"epub-calibre3\">（对查理旁白）\u003c/b>说实在的，您是不忍战火蔓延，生灵涂炭，想要拯救您的百姓的，为了执行您的政策，就接受这个和约吧。反正以后看形势如何，遵守不遵守您还可以相机行事的。\u003c/p>\n","text":"阿朗松 （对查理旁白）说实在的，您是不忍战火蔓延，生灵涂炭，想要拯救您的百姓的，为了执行您的政策，就接受这个和约吧。反正以后看形势如何，遵守不遵守您还可以相机行事的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00813","html":"\u003cp class=\"epub-calibre1\">华列克 怎么样，查理？我们的条款你同意吗？\u003c/p>\n","text":"华列克 怎么样，查理？我们的条款你同意吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00814","html":"\u003cp class=\"epub-calibre1\">查理 我同意，但须附带这一条件：现在由我们驻防的城市，你们不得染指。\u003c/p>\n","text":"查理 我同意，但须附带这一条件：现在由我们驻防的城市，你们不得染指。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00815","html":"\u003cp class=\"epub-calibre1\">约克 那么你就宣誓效忠于英王陛下；你以骑士的身份，决不反抗或背叛英王陛下的权力，你和你部下的将领都不得背叛。\u003cb class=\"epub-calibre3\">（查理等表示臣服）\u003c/b>你宣誓之后，在适当的时间以内，要偃旗息鼓，解散你的军队，让我们实现庄严肃穆的和平。\u003cb class=\"epub-calibre3\">（各下。）\u003c/b>\u003c/p>\n","text":"约克 那么你就宣誓效忠于英王陛下；你以骑士的身份，决不反抗或背叛英王陛下的权力，你和你部下的将领都不得背叛。（查理等表示臣服）你宣誓之后，在适当的时间以内，要偃旗息鼓，解散你的军队，让我们实现庄严肃穆的和平。（各下。）\n","sourceAnchor":null,"tag":"p"}],"heading":"第四场 同前。安佐境内约克公爵营帐","headingLevel":4,"sourceAnchor":"a489","actNumber":5,"sceneNumber":4},{"id":"part0022-section-032","label":"第五幕 · 第五场 伦敦。宫中一室","kind":"scene","blocks":[{"id":"part0022-00816","html":"\u003ch4 id=\"epub-part0022-a490\" class=\"epub-calibre12\">第五场 伦敦。宫中一室\u003c/h4>\n","text":"第五场 伦敦。宫中一室\n","sourceAnchor":"a490","tag":"h4"},{"id":"part0022-00817","html":"\u003cp class=\"epub-block1\">亨利王与萨福克上，两人边走边谈。葛罗斯特及爱克塞特随上。\u003c/p>\n","text":"亨利王与萨福克上，两人边走边谈。葛罗斯特及爱克塞特随上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00818","html":"\u003cp class=\"epub-calibre1\">亨利王 尊贵的伯爵，那美貌的玛格莱特，经你这一番描绘，真使我心神向往。她称得起是秀外慧中，我心中的爱情之苗已经茁壮起来了。犹如劲吹的狂飙激荡着艨艟巨舰去和波涛搏斗一般，她的芳名使我心旌摇摇，不能自持了；我若是不能驶进她爱河的港口，我宁愿覆舟而亡。\u003c/p>\n","text":"亨利王 尊贵的伯爵，那美貌的玛格莱特，经你这一番描绘，真使我心神向往。她称得起是秀外慧中，我心中的爱情之苗已经茁壮起来了。犹如劲吹的狂飙激荡着艨艟巨舰去和波涛搏斗一般，她的芳名使我心旌摇摇，不能自持了；我若是不能驶进她爱河的港口，我宁愿覆舟而亡。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00819","html":"\u003cp class=\"epub-calibre1\">萨福克 喏，我的好王上，我的拙口笨腮，还不能将她的高贵品德形容于万一呢。如果我长于文采，能将这位绝代佳人的幽姿淑质尽情描述，简直可以写成一部动人心弦的诗歌，就是一个缺乏想象的人听了，也不免神魂颠倒。还有一层，尽管她是尽善尽美，多才多艺，但她却是谦恭克己，对陛下一定能够唯命是从。唯命是从，我的意思是说，在礼法的范围以内，她对陛下一定是敬爱备至的。\u003c/p>\n","text":"萨福克 喏，我的好王上，我的拙口笨腮，还不能将她的高贵品德形容于万一呢。如果我长于文采，能将这位绝代佳人的幽姿淑质尽情描述，简直可以写成一部动人心弦的诗歌，就是一个缺乏想象的人听了，也不免神魂颠倒。还有一层，尽管她是尽善尽美，多才多艺，但她却是谦恭克己，对陛下一定能够唯命是从。唯命是从，我的意思是说，在礼法的范围以内，她对陛下一定是敬爱备至的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00820","html":"\u003cp class=\"epub-calibre1\">亨利王 那我就不作他想了。照此情形，护国公贤卿，你就同意将玛格莱特立为英国王后吧。\u003c/p>\n","text":"亨利王 那我就不作他想了。照此情形，护国公贤卿，你就同意将玛格莱特立为英国王后吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00821","html":"\u003cp class=\"epub-calibre1\">葛罗斯特 如果我同意，那就是逢君之恶了。陛下，您大概还记得，您已和另一位高贵的小姐订了婚的。怎能取消那桩婚约而无损于陛下的威信呢？\u003c/p>\n","text":"葛罗斯特 如果我同意，那就是逢君之恶了。陛下，您大概还记得，您已和另一位高贵的小姐订了婚的。怎能取消那桩婚约而无损于陛下的威信呢？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00822","html":"\u003cp class=\"epub-calibre1\">萨福克 那也没有什么了不起。一国之君对于不合法的誓言是可以打消的。有如和人约定比武，如果发现对方不是平等的对手，也可以中途停止比斗。一个穷伯爵的女儿哪能和国王匹配？取消这种婚约，有什么要紧？\u003c/p>\n","text":"萨福克 那也没有什么了不起。一国之君对于不合法的誓言是可以打消的。有如和人约定比武，如果发现对方不是平等的对手，也可以中途停止比斗。一个穷伯爵的女儿哪能和国王匹配？取消这种婚约，有什么要紧？\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00823","html":"\u003cp class=\"epub-calibre1\">葛罗斯特 哼，我请问，玛格莱特又能高贵多少？她父亲也不过是个伯爵，虽然他还另有个虚衔。\u003c/p>\n","text":"葛罗斯特 哼，我请问，玛格莱特又能高贵多少？她父亲也不过是个伯爵，虽然他还另有个虚衔。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00824","html":"\u003cp class=\"epub-calibre1\">萨福克 是呀，她父亲是个国王，他是那不勒斯和耶路撒冷的国王。况且他在法国很有权力，和他攀了亲，更可保障和平，使法国人始终臣服。\u003c/p>\n","text":"萨福克 是呀，她父亲是个国王，他是那不勒斯和耶路撒冷的国王。况且他在法国很有权力，和他攀了亲，更可保障和平，使法国人始终臣服。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00825","html":"\u003cp class=\"epub-calibre1\">葛罗斯特 关于这一点，阿玛涅克伯爵也能办到，他是查理的近派宗支。\u003c/p>\n","text":"葛罗斯特 关于这一点，阿玛涅克伯爵也能办到，他是查理的近派宗支。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00826","html":"\u003cp class=\"epub-calibre1\">爱克塞特 再说呢，阿玛涅克家资雄厚，陪嫁的妆奁一定丰盛。瑞尼埃么，非但陪不出什么，只怕还要向这边叨光一点哩。\u003c/p>\n","text":"爱克塞特 再说呢，阿玛涅克家资雄厚，陪嫁的妆奁一定丰盛。瑞尼埃么，非但陪不出什么，只怕还要向这边叨光一点哩。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00827","html":"\u003cp class=\"epub-calibre1\">萨福克 谈什么妆奁，大人们！不要把咱们的王上说得这般难堪吧，难道他是那样的无聊、那样的卑贱、那样的贫困，以至于必须为金钱而结婚，不是为爱情而结婚吗？咱们王上有的是钱，只有他送钱给王后，他哪会向王后要钱？下流的乡下人才拿婚姻当买卖，好像在市集上交易牛羊驴马一般。婚姻是一桩郑重的大事，不能依靠掮客们的撺掇的。什么人做他的卧榻上的伴侣，不能决定于我们要谁，而应决定于他爱的是谁。既然王上最爱的是玛格莱特，那么，大人们，在一切理由之中，这一项就是最为重要的理由，它支使我们非选中她不可。不如意的婚姻好比是座地狱，一辈子鸡争鹅斗，不得安生；相反的，选到一个称心如意的配偶，就能百年谐和，幸福无穷。亨利王上，作为一国之君，除了玛格莱特，一个国君的女儿之外，还能娶谁？她的绝色仙姿，加上她高贵的身世，也只有国王才有资格娶她为妻。她那刚毅果断的性格，是女性中罕见的，也使我们关于诞育一位英俊的皇储的希望能于实现。亨利王上的父亲是一位英明圣主，他本人和意志坚强的玛格莱特由爱情而结为夫妇，将会诞育出许许多多的英明圣主。大人们，别坚持成见吧，咱们一致同意选定玛格莱特为王后，别再考虑别人吧。\u003c/p>\n","text":"萨福克 谈什么妆奁，大人们！不要把咱们的王上说得这般难堪吧，难道他是那样的无聊、那样的卑贱、那样的贫困，以至于必须为金钱而结婚，不是为爱情而结婚吗？咱们王上有的是钱，只有他送钱给王后，他哪会向王后要钱？下流的乡下人才拿婚姻当买卖，好像在市集上交易牛羊驴马一般。婚姻是一桩郑重的大事，不能依靠掮客们的撺掇的。什么人做他的卧榻上的伴侣，不能决定于我们要谁，而应决定于他爱的是谁。既然王上最爱的是玛格莱特，那么，大人们，在一切理由之中，这一项就是最为重要的理由，它支使我们非选中她不可。不如意的婚姻好比是座地狱，一辈子鸡争鹅斗，不得安生；相反的，选到一个称心如意的配偶，就能百年谐和，幸福无穷。亨利王上，作为一国之君，除了玛格莱特，一个国君的女儿之外，还能娶谁？她的绝色仙姿，加上她高贵的身世，也只有国王才有资格娶她为妻。她那刚毅果断的性格，是女性中罕见的，也使我们关于诞育一位英俊的皇储的希望能于实现。亨利王上的父亲是一位英明圣主，他本人和意志坚强的玛格莱特由爱情而结为夫妇，将会诞育出许许多多的英明圣主。大人们，别坚持成见吧，咱们一致同意选定玛格莱特为王后，别再考虑别人吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00828","html":"\u003cp class=\"epub-calibre1\">亨利王 我不知道是由于萨福克伯爵的话打动了我的心，还是由于我年事太轻，受不住炽热的爱情的冲击，我只觉得心烦意乱，又热望，又担忧，忐忑不宁，我连想都不愿意再想下去了。萨福克爱卿，你就马上乘船，前往法国，不论他们提出什么条件，只要能使玛格莱特郡主应允渡海来到英格兰做我的王后就行。你的一切开支用费，可向百姓们征收什一税来支应。快去吧，在你回国以前，我是千头万绪，不得片刻安宁的。还有你，我的好叔父，请你不要见怪。你若是像你过去那样，而不是像你现在这样，来衡量我，我知道你一定能够原谅我做出这突然的决断的。现在让我到一所清静的去处，不要有人来打搅我，我要仔细回味一下我心头的烦恼。\u003cb class=\"epub-calibre3\">（下。）\u003c/b>\u003c/p>\n","text":"亨利王 我不知道是由于萨福克伯爵的话打动了我的心，还是由于我年事太轻，受不住炽热的爱情的冲击，我只觉得心烦意乱，又热望，又担忧，忐忑不宁，我连想都不愿意再想下去了。萨福克爱卿，你就马上乘船，前往法国，不论他们提出什么条件，只要能使玛格莱特郡主应允渡海来到英格兰做我的王后就行。你的一切开支用费，可向百姓们征收什一税来支应。快去吧，在你回国以前，我是千头万绪，不得片刻安宁的。还有你，我的好叔父，请你不要见怪。你若是像你过去那样，而不是像你现在这样，来衡量我，我知道你一定能够原谅我做出这突然的决断的。现在让我到一所清静的去处，不要有人来打搅我，我要仔细回味一下我心头的烦恼。（下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00829","html":"\u003cp class=\"epub-calibre1\">葛罗斯特 不错，烦恼——只怕从此以后，烦恼的日子多着哩。\u003cb class=\"epub-calibre3\">（葛罗斯特、爱克塞特同下。）\u003c/b>\u003c/p>\n","text":"葛罗斯特 不错，烦恼——只怕从此以后，烦恼的日子多着哩。（葛罗斯特、爱克塞特同下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00830","html":"\u003cp class=\"epub-calibre1\">萨福克 萨福克是胜利了。我此番前往法国，好比当年特洛亚的青年帕里斯去到希腊做下一番风流韵事一样，但我的结局会比那特洛亚的青年更好。玛格莱特立为王后，她就能控制王上，而我呢，我既能控制她，也能控制王上和整个英国。\u003cb class=\"epub-calibre3\">（下。）\u003c/b>\u003c/p>\n","text":"萨福克 萨福克是胜利了。我此番前往法国，好比当年特洛亚的青年帕里斯去到希腊做下一番风流韵事一样，但我的结局会比那特洛亚的青年更好。玛格莱特立为王后，她就能控制王上，而我呢，我既能控制她，也能控制王上和整个英国。（下。）\n","sourceAnchor":null,"tag":"p"}],"heading":"第五场 伦敦。宫中一室","headingLevel":4,"sourceAnchor":"a490","actNumber":5,"sceneNumber":5},{"id":"part0022-section-033","label":"注释","kind":"notes","blocks":[{"id":"part0022-00831","html":"\u003chr class=\"epub-calibre14\">","text":"","sourceAnchor":null,"tag":"hr"},{"id":"part0022-00832","html":"\u003cp class=\"epub-note\"> \u003ca id=\"epub-part0022-m001\">\u003c/a>\u003ca href=\"#epub-part0022-w001\" data-source-anchor=\"w001\">[1]\u003c/a>指上帝。\u003c/p>\n","text":" [1]指上帝。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00833","html":"\u003cp class=\"epub-note\"> \u003ca id=\"epub-part0022-m002\">\u003c/a>\u003ca href=\"#epub-part0022-w002\" data-source-anchor=\"w002\">[2]\u003c/a>百合花纹章代表法兰西，英国占有法兰西土地，所以在英国国徽上也绣有百合花。\u003c/p>\n","text":" [2]百合花纹章代表法兰西，英国占有法兰西土地，所以在英国国徽上也绣有百合花。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00834","html":"\u003cp class=\"epub-note\"> \u003ca id=\"epub-part0022-m003\">\u003c/a>\u003ca href=\"#epub-part0022-w003\" data-source-anchor=\"w003\">[3]\u003c/a>底波拉（Deborah），《圣经》里的女先知，曾帮助以色列人战败迦南王的大将西西拉。事见《旧约》：《士师记》第四章。\u003c/p>\n","text":" [3]底波拉（Deborah），《圣经》里的女先知，曾帮助以色列人战败迦南王的大将西西拉。事见《旧约》：《士师记》第四章。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00835","html":"\u003cp class=\"epub-note\"> \u003ca id=\"epub-part0022-m004\">\u003c/a>\u003ca href=\"#epub-part0022-w004\" data-source-anchor=\"w004\">[4]\u003c/a>这里是引用普鲁塔克关于恺撒的传记中恺撒对一个舵工说的话：“我的好人，不用害怕，因为你船上装载着恺撒和他的好运。”\u003c/p>\n","text":" [4]这里是引用普鲁塔克关于恺撒的传记中恺撒对一个舵工说的话：“我的好人，不用害怕，因为你船上装载着恺撒和他的好运。”\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00836","html":"\u003cp class=\"epub-note\"> \u003ca id=\"epub-part0022-m005\">\u003c/a>\u003ca href=\"#epub-part0022-w005\" data-source-anchor=\"w005\">[5]\u003c/a>据基督教传说，海伦娜太后重新发现了耶稣受难的十字架。\u003c/p>\n","text":" [5]据基督教传说，海伦娜太后重新发现了耶稣受难的十字架。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00837","html":"\u003cp class=\"epub-note\"> \u003ca id=\"epub-part0022-m006\">\u003c/a>\u003ca href=\"#epub-part0022-w006\" data-source-anchor=\"w006\">[6]\u003c/a>据基督教传说，圣腓力的女儿们能预知未来。\u003c/p>\n","text":" [6]据基督教传说，圣腓力的女儿们能预知未来。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00838","html":"\u003cp class=\"epub-note\"> \u003ca id=\"epub-part0022-m007\">\u003c/a>\u003ca href=\"#epub-part0022-w007\" data-source-anchor=\"w007\">[7]\u003c/a>伦敦泰晤士河南岸娼妓受温彻斯特主教管辖，向他纳税，领取执照。\u003c/p>\n","text":" [7]伦敦泰晤士河南岸娼妓受温彻斯特主教管辖，向他纳税，领取执照。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00839","html":"\u003cp class=\"epub-note\"> \u003ca id=\"epub-part0022-m008\">\u003c/a>\u003ca href=\"#epub-part0022-w008\" data-source-anchor=\"w008\">[8]\u003c/a>唐米莉是西徐亚王后，她击败居鲁士入侵的军队，并捕杀了居鲁士本人。\u003c/p>\n","text":" [8]唐米莉是西徐亚王后，她击败居鲁士入侵的军队，并捕杀了居鲁士本人。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00840","html":"\u003cp class=\"epub-note\"> \u003ca id=\"epub-part0022-m009\">\u003c/a>\u003ca href=\"#epub-part0022-w009\" data-source-anchor=\"w009\">[9]\u003c/a>萨福克伯爵的本名是威廉·德·拉·波勒。\u003c/p>\n","text":" [9]萨福克伯爵的本名是威廉·德·拉·波勒。\n","sourceAnchor":null,"tag":"p"},{"id":"part0022-00841","html":"\u003cp class=\"epub-note\"> \u003ca id=\"epub-part0022-m010\">\u003c/a>\u003ca href=\"#epub-part0022-w010\" data-source-anchor=\"w010\">[10]\u003c/a>希腊神话，伊卡洛斯和他父亲代达罗斯一起用蜡制的翅膀逃离克里特，他因飞近太阳，坠海而死。\u003c/p>\n","text":" [10]希腊神话，伊卡洛斯和他父亲代达罗斯一起用蜡制的翅膀逃离克里特，他因飞近太阳，坠海而死。\n","sourceAnchor":null,"tag":"p"}],"heading":"","headingLevel":null,"sourceAnchor":null}],"language":"zh","alignment":"none","source":{"type":"user-provided-epub","title":"莎士比亚全集","publisher":"人民文学出版社","isbn":"978-7-02-010568-7","epubSha256":"e0385e88e1428b9accb344d45650a0f52ea1d917cbb12009036b2fb32fd9b747","attribution":"朱生豪等译（逐作保留原书署名）","path":"text/part0022.html","blockCount":842,"imageCount":2,"textSha256":"ae63aca216cac553a3d4ea4ef851d8cf64bd8151d4aaab7e3042412f18eecd9d","anchorSections":{"a458":"part0022-section-000","a459":"part0022-section-001","a460":"part0022-section-002","w001":"part0022-section-002","w002":"part0022-section-002","a461":"part0022-section-003","w003":"part0022-section-003","w004":"part0022-section-003","w005":"part0022-section-003","w006":"part0022-section-003","a462":"part0022-section-004","w007":"part0022-section-004","a463":"part0022-section-005","a464":"part0022-section-006","a465":"part0022-section-007","a466":"part0022-section-008","a467":"part0022-section-009","a468":"part0022-section-010","a469":"part0022-section-011","w008":"part0022-section-011","a470":"part0022-section-012","w009":"part0022-section-012","a471":"part0022-section-013","a472":"part0022-section-014","a473":"part0022-section-015","a474":"part0022-section-016","a475":"part0022-section-017","a476":"part0022-section-018","a477":"part0022-section-019","a478":"part0022-section-020","a479":"part0022-section-021","a480":"part0022-section-022","a481":"part0022-section-023","a482":"part0022-section-024","a483":"part0022-section-025","w010":"part0022-section-025","a484":"part0022-section-026","a485":"part0022-section-027","a486":"part0022-section-028","a487":"part0022-section-029","a488":"part0022-section-030","a489":"part0022-section-031","a490":"part0022-section-032","m001":"part0022-section-033","m002":"part0022-section-033","m003":"part0022-section-033","m004":"part0022-section-033","m005":"part0022-section-033","m006":"part0022-section-033","m007":"part0022-section-033","m008":"part0022-section-033","m009":"part0022-section-033","m010":"part0022-section-033"},"note":"用户提供的多译者 EPUB；保留原书署名、注释与图像。未作逐句双语对齐。"}};
